                if (dataRows.Length > 0)
                {
                    dataRows = dtDictionaryFieldAccount.Select("DictionaryID=" + n.DictionaryID + " AND ParameterName='" + n.ParameterName + "' ");
                    if (dataRows.Length == 0)
                    {
                        return null;
                    }
                    else
                    {
                        n.Comment = dataRows[0]["Comment"].ToString();
