                }

            }

            elementTableOuputs.Add(obj);


            //Spread spread = new Spread();
            //spread.displayName = n.Comment;
            //spread.name = n.ParameterName;
            //spread.size = n.Width.GetValueOrDefault(100);
            //spread.formatter = n.Formatter;
