        /// <summary>
        /// 获取APP配置
        /// </summary>
        /// <returns></returns>

        public string GetConfigApp()
        {

            List<ElementTableOuput> elementTableOuputs = new List<ElementTableOuput>();

            List<SearchForm> searchFormsAll = new List<SearchForm>();
            List<List<SearchForm>> searchForms = new List<List<SearchForm>>();
            List<List<ElementTableOuput>> datas = new List<List<ElementTableOuput>>();
            string msg = "读取成功";
            bool result = true;


            try
            {
                List<ElementTableInput> elementTable =
          JsonConvert.DeserializeObject<List<ElementTableInput>>(BodyJson);
                string id = "";
                if (elementTable == null || elementTable.Count == 0)
                {
                    result = false;
                    msg = "没有接收到ID";
                }
                else
                {
                    elementTable.ForEach(m =>
                    {
                        id += m.ID + ",";
                    });
                    List<V_DictionaryField> dev_DictionaryFields = Entities.SqlQueryRaw<V_DictionaryField>(string.Format(@"SELECT A.*
  FROM [V_DictionaryField] A
 
  where A.[DictionaryID] IN({0})", id.Trim(','))).ToList();


                    int left = 0;
                    foreach (var n in dev_DictionaryFields.OrderBy(m => m.FieldIndex))
                    {
                        if (n.IsVisibleApp == true)
                        {
                            ElementTableOuput obj = new ElementTableOuput();

                            obj.width = n.Width.GetValueOrDefault(100).ToString();
                            obj.label = n.Comment;
                            obj.prop = n.ParameterName;
                            obj.fix = string.IsNullOrEmpty(n.fix) ? null : n.fix;
                            obj.sortable = string.IsNullOrEmpty(n.sortable) ? null : n.sortable;
                            obj.align = n.align;

                            obj.icon = n.icon;
                            try
                            {
                                if (!string.IsNullOrEmpty(n.button))
                                {
                                    obj.button = n.button;
                                }

                                if (!string.IsNullOrEmpty(n.active))
                                {
                                    obj.active = n.active;
                                }
                                if (!string.IsNullOrEmpty(n.component))
                                {
                                    obj.component = n.component;
                                }
                                if (!string.IsNullOrEmpty(n.icon))
                                {
                                    obj.icon = n.icon;
                                }
                            }
                            catch (Exception ex)
                            {

                            }


                            obj.isEdit = n.IsEdit.GetValueOrDefault();
                            obj.isMerge = n.isMerge.GetValueOrDefault();
                            obj.dicID = n.DictionaryID.ToString();
                            obj.isLook = false;
                            obj.routerName = n.RouterName.GetValueOrDefault();
                            elementTableOuputs.Add(obj);
                        }
                        if (n.IsQuery == true)
                        {//查询
                            SearchForm searchForm = new SearchForm();
                            searchForm.placeholder = "请输入" + n.Comment;
                            searchForm.label = n.Comment;
                            searchForm.prop = n.ParameterName;
                            searchForm.dicID = n.DictionaryID.GetValueOrDefault().ToString();
                            searchForm.value = StringHelper.GetDefaultValue("", n.DefaultValue, n.ParameterName, true);
                            switch (n.ControlType)
                            {
                                case "textbox":
                                case "textarea":
                                case "el-input":
                                    searchForm.type = "Input";
                                    break;
                                case "el-select":
                                case "combobox":
                                case "comboboxMultiple":
                                    searchForm.type = "Select";
                                    if (!string.IsNullOrEmpty(n.DataSourceID))
                                    {
                                      //  DataTable dataTable = SqlHelper.ExecuteDataTable("SELECT * FROM [Dev_DataSource] WHERE [DataSourceID]='" + n.DataSourceID + "'");
                                        DataTable dataTable = null;
                                        if (lstDataSource.ContainsKey(n.DataSourceID) == false)
                                        {
                                            dataTable = SqlHelper.ExecuteDataTable("SELECT * FROM [Dev_DataSource] WHERE [DataSourceID]='" + n.DataSourceID + "'");
                                            lstDataSource.Add(n.DataSourceID, dataTable);
                                        }
                                        else
                                        {
                                            dataTable = lstDataSource[n.DataSourceID];
                                        }
                                        string value = "", label = "";
                                        if (dataTable.Rows.Count > 0)
                                        {

                                            value = dataTable.Rows[0]["DataValue"].ToString();
                                            label = dataTable.Rows[0]["DataText"].ToString();
                                            string USQL = dataTable.Rows[0]["USQL"].ToString();
                                            USQL = USQL.Replace("{CenterID}", dev_Account.CenterID.ToString());
                                            USQL = USQL.Replace("{WorkFlowInstanceID}", dev_Account.WorkFlowInstanceID);
                                            USQL = USQL.Replace("{Account}", dev_Account.Account.ToString());
                                            USQL = USQL.Replace("{GroupID}", dev_Account.GroupID.ToString());
                                            DataTable dtUSQL = SqlHelper.ExecuteDataTable(USQL);

                                            if (dtUSQL.Columns.Contains("value") == false)
                                            {
                                                dtUSQL.Columns.Add("value");
                                            }
                                            if (dtUSQL.Columns.Contains("label") == false)
                                            {
                                                dtUSQL.Columns.Add("label");
                                            }

                                            if (!string.IsNullOrEmpty(n.DefaultValue))
                                            {

                                                if (n.DefaultValue.IndexOf("选择项") > -1)
                                                {
                                                    searchForm.value = dtUSQL.Rows[int.Parse(searchForm.value.ToString())][value].ToString();
                                                }
                                            }
                                            if (value.ToLower() != "value")
                                            {
                                                dtUSQL.Columns["value"].Expression = value;
                                            }
                                            if (value.ToLower() != "label")
                                            {
                                                dtUSQL.Columns["label"].Expression = label;

                                            }
                                          
                                            //if (value.ToLower() != "text")
                                            //{

                                            //    dtUSQL.Columns["text"].Expression = label;
                                            //}

                                            searchForm.options = dtUSQL;
                                        }
                                        if (n.ControlType.ToLower() == "comboboxMultiple".ToLower())
                                        {
                                            searchForm.multiple = true;

                                        }
                                    }

                                    break;
                                case "el-radio":
                                case "radio":
                                    searchForm.type = "Radio";
                                    break;
                                case "RadioButton":
                                    searchForm.type = "RadioButton";
                                    break;
                                case "checkbox":
                                case "el-checkbox":
                                    searchForm.type = "Checkbox";
                                    break;
                                case "datebox":
                                case "el-date-picker":
                                    searchForm.type = "Daterange";
                                    searchForm.width = "260";
                                    break;
                            }
                            searchFormsAll.Add(searchForm);
                        }
                    }
                   
                    foreach (string dicID in id.Split(','))
                    {
                        if (string.IsNullOrEmpty(dicID))
                        {
                            continue;
                        }
                        var tmp = elementTableOuputs.Where(m => m.dicID == dicID).ToList();

                        searchForms.Add(searchFormsAll.Where(m => m.dicID == dicID).ToList());
                        left = 0;


                        int thisID = int.Parse(dicID);
                        V_DictionaryField v_DictionaryField = dev_DictionaryFields.Where(m => m.DictionaryID == thisID).FirstOrDefault();
                        //foreach (var obj in dev_Account.ButtonMenuRoleMap.Where(m => m.MenuCode == v_DictionaryField.MenuCode))
                        //{
                        //    SearchForm button = new SearchForm();
                        //    button.label = obj.MenuName;
                        //    button.icon = obj.Icon;
                        //    button.type = obj.ButtonType;
                        //    button.methods = obj.OnClick;
                        //    //searchHandle.Add(button)
                        //}
                        foreach (var obj in tmp)
                        {
                            // foreach (var obj1 in obj.Value)
                            {
                                if (!string.IsNullOrEmpty(obj.fix))
                                {
                                    obj.left = left;
                                    left += int.Parse(obj.width);
                                }

                            }

                        }
                        datas.Add(tmp);



                    }

                }
            }
            catch (Exception ex)
            {
                msg = ex.Message;
                result = false;
            }

            //dev_Account.Menu.Where()
            // searchForm:{forms:[],datas:{},btns:[]} 组件 prop值 按钮
            // tableColumns:[ [],[]]  表头数据
            return JsonConvert.SerializeObject(new { result, msg, forms = searchForms, datas = datas, btns = new string[0] });
        }
        /// <summary>
        /// 获取页面权限
        /// </summary>
        /// <returns></returns>
        public string GetRole()
        {
            string msg = "读取成功";
            bool result = true;

            List<V_Dev_ButtonMenuRoleMapRead> v_Dev_ButtonMenuRoleMapReads = new List<V_Dev_ButtonMenuRoleMapRead>();
            try
            {
                JObject jObject = JsonConvert.DeserializeObject(BodyJson) as JObject;
                string menuCode = "";
                if (jObject.ContainsKey("MenuCode"))
                {
                    menuCode = jObject["MenuCode"].ToString();
                }
                if (string.IsNullOrEmpty(menuCode))
                {
                    result = false;
                    msg = "没有菜单代码";
                }
                else
                {
                    v_Dev_ButtonMenuRoleMapReads = Entities.SqlQueryRaw<V_Dev_ButtonMenuRoleMapRead>(string.Format(@"  
SELECT *,ButtonName as BtnName,OnClick as Methods,ButtonType as Type
  FROM[dbo].[V_Dev_ButtonMenuRoleMapRead]
  WHERE RoleID in (
SELECT ROLEID FROM[dbo].[Dev_RoleMap] WHERE Account = '{0}'
	union all 
	   SELECT C.ROLEID FROM[dbo].[Dev_RoleMap] A
   INNER JOIN Dev_Role B ON A.RoleID=B.RoleID
     INNER JOIN Dev_Role C ON c.ParentID=b.RoleID
    WHERE Account = '{0}'
  )", dev_Account.Account)).ToList();
                    if (dev_Account == null)
                    {
                        msg = "当前未登录";
                        result = false;
                    }
                    else
                    {
                        result = dev_Account.Menu.Where(m => m.MenuCode == menuCode).FirstOrDefault() != null;
                    }


                }
            }
            catch (Exception ex)
            {
                msg = ex.Message;
                result = false;
            }
            return JsonConvert.SerializeObject(new { result, msg, datas = v_Dev_ButtonMenuRoleMapReads });
        }

        protected int rowNumber = -1;
        List<string> lstDelete = new List<string>();
        long tmpOrderID = 0;
        /// <summary>
        /// 获取相关的工段
        /// </summary>
        /// <param name="obj"></param>
        /// <param name="list"></param>
        /// <param name="dataTable"></param>
        /// <param name="childrens"></param>
        private void GetPartPlanChild(V_OrderPlan2 obj, List<V_APS_ProcessPartPlan> list, DataTable dataTable, List<V_APS_OrganizeProcessID> childrens)
        {

            foreach (DataRow dataRow in dataTable.Select("FirstPlanID=" + obj.FirstPlanID))
            {
                long firstPlanID = 0;
                long.TryParse(dataRow["FirstPlanID"].ToString(), out firstPlanID);
                string ProcessPartName = dataRow["ProcessPartName"].ToString();
                decimal Capacity = 0;
                decimal.TryParse(dataRow["Capacity"].ToString(), out Capacity);


                V_APS_ProcessPartPlan aPS_ProcessPartPlan = list.Where(m => m.FirstPlanID == firstPlanID && m.ProcessPartName == ProcessPartName).FirstOrDefault();

                decimal AwaitQty = 0;
                decimal.TryParse(dataRow["AwaitQty"].ToString(), out AwaitQty);
                int fixDay = 0;
                int.TryParse(dataRow["FixDay"].ToString(), out fixDay);
                if (aPS_ProcessPartPlan == null)
                {//新的工段
                    aPS_ProcessPartPlan = new V_APS_ProcessPartPlan();
                    aPS_ProcessPartPlan.Reset();
                    aPS_ProcessPartPlan.FixDay = fixDay;
                    aPS_ProcessPartPlan.RowNumber = obj.RowNumber;
                    aPS_ProcessPartPlan.FirstPlanID = firstPlanID;
                    aPS_ProcessPartPlan.PlanQty = obj.AwaitQty;
                    aPS_ProcessPartPlan.ProcessPartName = ProcessPartName;
                    //  aPS_ProcessPartPlan.ExpectTime = Math.Round(AwaitQty, 2);
                    aPS_ProcessPartPlan.OrderNo = obj.OrderNo;
                    aPS_ProcessPartPlan.Code = obj.Code;
                    aPS_ProcessPartPlan.Spec = obj.Spec;
                    aPS_ProcessPartPlan.ProcessIDs = new List<string>();
                    aPS_ProcessPartPlan.MaterialID = obj.MaterialID;
                    aPS_ProcessPartPlan.OrderID = obj.OrderID;
                    aPS_ProcessPartPlan.DemandDate = obj.DemandDate;
                    if (AppInfo.PushType == "5")
                    {
                        aPS_ProcessPartPlan.DemandDate = obj.DemandDate.GetValueOrDefault(DateTime.Now.AddDays(2)).AddDays(-2);
                    }
                    if (aPS_ProcessPartPlan.DemandDate >= DateTime.Now.Date)
                    {
                        aPS_ProcessPartPlan.DemandDate = obj.DemandDate;
                        aPS_ProcessPartPlan.DemandDate = aPS_ProcessPartPlan.DemandDate.GetValueOrDefault().AddDays(-fixDay);
                    }

                    aPS_ProcessPartPlan.TotalPlanQty = obj.TotalPlanQty;
                    aPS_ProcessPartPlan.FormQty = obj.FormQty;
                    if (tmpOrderID != obj.OrderID && (string.IsNullOrEmpty(obj.SourceOrderNo) || (!string.IsNullOrEmpty(obj.SourceOrderNo) && dataTable.Select("OrderNo='" + obj.SourceOrderNo + "'").Length == 0)))
                    {
                        tmpOrderID = obj.OrderID.GetValueOrDefault();
                        aPS_ProcessPartPlan.IsLocked = true;
                    }
                    aPS_ProcessPartPlan.OrderNo = obj.OrderNo;
                    aPS_ProcessPartPlan.ProcessPartName = ProcessPartName;
                    if (!string.IsNullOrEmpty(dataRow["WorkShopID"].ToString()))
                    {
                        aPS_ProcessPartPlan.WorkShopID = long.Parse(dataRow["WorkShopID"].ToString());
                        aPS_ProcessPartPlan.WorkShopName = dataRow["WorkShopName"].ToString();
                    }
                    if (Capacity <= 0)
                    {
                        aPS_ProcessPartPlan.IsBackground = true;
                    }


                    list.Add(aPS_ProcessPartPlan);
                }
                else
                {
                    //  aPS_ProcessPartPlan.ExpectTime = aPS_ProcessPartPlan.ExpectTime.GetValueOrDefault() + AwaitQty * Capacity;
                }
                aPS_ProcessPartPlan.ProcessIDs.Add(dataRow["ProcessID"].ToString());

            }

            //获取可用的车间，加入  
            foreach (var order in list)
            {


                List<V_APS_OrganizeProcessID> thisChildrens = childrens.Where(m => order.ProcessIDs.Contains(m.ProcessID)).ToList();
                order.childrens = new List<V_APS_OrganizeProcessID>();
                foreach (var org in thisChildrens)
                {
                    if (order.childrens.Where(m => m.WorkShopID == org.WorkShopID).Count() == 0)
                    {
                        order.childrens.Add(new V_APS_OrganizeProcessID { WorkShopID = org.WorkShopID, WorkShopName = org.WorkShopName });
                    }

                }

                if (order.childrens.Count == 1)
                {//当只有一个车间的时候，默认选中

                    order.WorkShopID = order.childrens[0].WorkShopID;
                    order.WorkShopName = order.childrens[0].WorkShopName;
                    order.childrens[0].isChecked = true;
                }
                //order.childrens = childrens;

            }
            //递归可能的children
            if (obj.children != null)
            {
                foreach (var child in obj.children)
                {
                    GetPartPlanChild(child, list, dataTable, childrens);
                }
            }

        }

        private void GetChildren(DataTable dt, int dicID, DataTable dt2)
        {
            dt.Columns.Add("children", typeof(DataTable));
            string OrderNos = "";
            foreach (DataRow dataRow in dt.Rows)
            {
                OrderNos += "'" + dataRow["OrderNo"] + "',";

            }
            if (!string.IsNullOrEmpty(OrderNos))
            {



                foreach (DataRow dataRow in dt.Rows)
                {
                    if (dicID == 5150)
                    {
                        dataRow["update"] = true;
                    }

                    DataTable dataTable = dt2.Clone();
                    foreach (DataRow dr in dt2.Select("SourceOrderNo='" + dataRow["OrderNo"] + "' and SourceOrderNo<>OrderNo"))
                    {
                        var newRow = dataTable.NewRow();
                        foreach (DataColumn col in dataTable.Columns)
                        {
                            newRow[col.ColumnName] = dr[col.ColumnName];
                        }
                        dataTable.Rows.Add(newRow);
                        lstDelete.Add(dataRow["OrderNo"].ToString());
                    }
                    dataRow["children"] = dataTable;
                    dataRow["RowNumber"] = rowNumber;
                    rowNumber--;
                    if (dataTable.Rows.Count > 0)
                    {
                        GetChildren(dataTable, dicID, dt2);
                    }

                }

            }
        }

