FROM   APS_ProcessPlan A
LEFT JOIN APS_ProcessGroupInfo B ON A.ProcessGroupInfoID=B.ProcessGroupInfoID
LEFT JOIN APS_ProcessGroupInfo B2 ON B2.ProcessGroupID=B.ProcessGroupID 
