                if (!string.IsNullOrEmpty(LineID))
                {
                    newRow["ExpectTime"] = ds.Tables[0].Compute("SUM(ExpectTime)", "LineID=" + LineID);
                }

   
                if (dataRow.Table.Columns.Contains("NoWorkHours"))
                {
                    foreach (DataRow dataRow1 in dataRow.Table.Select("NoWorkHours=1"))
                    {
                        lstProcessPlanID.Add(dataRow1["ProcessPlanID"].ToString());
                    }
                }
                //如何配置了合计或者求和，需要进一步合计
                foreach (var obj in fields)
                {
                    if (!string.IsNullOrEmpty(obj.FooterType))
                    {
                        if (ds.Tables[0].Columns.Contains(obj.ParameterName))
                        {
                            if (!string.IsNullOrEmpty(LineID))
                            {
                                object s2 = ds.Tables[0].Compute(obj.FooterType + "([" + obj.ParameterName + "])", "LineID=" + LineID);
                                if (s2 != null)
                                {
                                    newRow[obj.ParameterName] = s2;

                                }
                            }
                        }

                    }
                }
             
              
                foreach (DataColumn dataColumn in ds.Tables[0].Columns)
                {
                    bColors.Add(dataColumn.ColumnName, "#AECDEF");
                }
                newRow["BColors"] = bColors;

            
                // for (int i = 0; i < GetSchedulingDays(); i++)
             
                while (dateStart <= dateTime2)
                {
                   
                    string WorkFlowInstanceID = drDic[0]["WorkFlowInstanceID"].ToString();


                    foreach (string s1 in WorkFlowInstanceID.Split(','))
                    {
                        string wid = s1.Trim();



                        string objID = string.Format("{0:MM-dd}", dateStart).ToString();
                        if (!string.IsNullOrEmpty(wid))
                        {
                            objID += wid;
                        }
                        string thisLineID = LineID;
                        decimal qty = 0;
                  
                        long.TryParse(dataRow["ProcessPlanID"].ToString(), out processPlanID);
                       
                        string sumQty = objs.Where(m => m.LineID.GetValueOrDefault().ToString() == thisLineID && m.PlanDay == dateStart && m.WorkingTimesID == s1).Sum(m => m.PlanQty).ToString();
                        //每天的计划信息
                        V_APS_DayPlan dayPlanInfo = new V_APS_DayPlan();
                        dayPlanInfo.PlanDay = dateStart;
                        dayPlanInfo.PlanQty = 0;
                        dayPlanInfo.TotalHours = 0;
                        dayPlanInfo.DayCapacity = 0;

                        if (!string.IsNullOrEmpty(sumQty))
                        {
                            dayPlanInfo.PlanQty = decimal.Parse(sumQty);
                        }
                        if (dayPlanInfo.PlanQty > 0)
                        {
                            newRow[string.Format("{0}", objID)] = string.Format("{0:0.##########}", dayPlanInfo.PlanQty);

                        }
                    }
                    dateStart = dateStart.AddDays(1);

                }



                // newRow["ViewSort"] = 10000;
                newRow["StartDate"] = DBNull.Value;

        
                rowNumber = 1;

                dRlines.Add(new { label = lineName, text = lineName, value = LineID, RowNumber = rowNumber });

                newRow["Lines"] = dRlines;
                if (ds.Tables[0].Columns.Contains("ProcessID"))
                {

                    newRow["ProcessID"] = dataRow["ProcessID"];
                }
                // newRow["LineIDText"] =  lineName;
                ds.Tables[0].Rows.InsertAt(newRow, newRowIndex);
                newRowIndex++;
                // if (WorkShopID == "")
                //{
                //    LineID = dataRow["LineID"].ToString();
                //    preWorkShopID = dataRow["WorkShopID"].ToString();
                //    lineName = dataRow["lineName"].ToString();
                //}



            }

            if(workLoad)
            {
                newRow = ds.Tables[0].NewRow();


                newRow["OrderNo"] = lineName + "负荷：";
                newRow["ProcessPlanID"] = newRow["ProcessPartID"] = -1;
                if (string.IsNullOrEmpty(LineID) == false)
                {
                  //  newRow["LineID"] = long.Parse(LineID);
                }

                newRow["WorkShopID"] = dataRow["WorkShopID"];
                newRow["lineName"] = lineName;
                 bColors = new Dictionary<string, string>();//背景颜色
                foreach(DataColumn dataColumn in ds.Tables[0].Columns)
                {
                    bColors.Add(dataColumn.ColumnName, "#AECDEF");
                }
                if (!string.IsNullOrEmpty(LineID))
            {
                    ds.Tables[0].Compute("SUM(ExpectTime)", "LineID=" + LineID);
                }



                dateStart = dateTime1;
                while (dateStart <= dateTime2)
                {
                    string WorkFlowInstanceID = drDic[0]["WorkFlowInstanceID"].ToString();


                    foreach (string s1 in WorkFlowInstanceID.Split(','))
                    {
                        string wid = s1.Trim();



                        string objID = string.Format("{0:MM-dd}", dateStart).ToString();
                        if (!string.IsNullOrEmpty(WorkFlowInstanceID))
                        {
                            objID += wid;
                        }
                        string thisLineID = LineID;
                        decimal qty = 0;
                   
                        long.TryParse(dataRow["ProcessPlanID"].ToString(), out processPlanID);
                 
                        decimal workload = objs.Where(m => m.LineID.GetValueOrDefault().ToString() == thisLineID && m.PlanDay == dateStart && m.WorkingTimesID.ToString() == s1 && lstProcessPlanID.Contains(m.ProcessPlanID.ToString()) == false).Sum(m => m.Workload);
                        workload = workload;
                        //每天的计划信息
                        V_APS_DayPlan dayPlanInfo = new V_APS_DayPlan();
                        dayPlanInfo.PlanDay = dateStart;
                        dayPlanInfo.PlanQty = 0;
                        dayPlanInfo.TotalHours = 0;
                        dayPlanInfo.DayCapacity = 0;
                        string bColor = "#AECDEF";
                        if (workload > 0)
                        {
                            if (workload >= 0.99m)
                            {
                                workload = 1;
                            }
                            dayPlanInfo.PlanQty = workload;
                            if(workload>1.2m)
                            {
                                bColor= "#EF949F";
                            }
                            else if (workload < 0.99m)
                            {
                                bColor = "#FFFF00";
                            }
                        }
                       
                        bColors[objID]=bColor;
                        if (dayPlanInfo.PlanQty > 0)
                        {
                            newRow[string.Format("{0}", objID)] = string.Format("{0:F2}", dayPlanInfo.PlanQty);

                        }

                    }
                    dateStart = dateStart.AddDays(1);
                }
                newRow["BColors"] = bColors;


                // newRow["ViewSort"] = 10000;
                newRow["StartDate"] = DBNull.Value;

                newRow["Lines"] = dRlines;
                if (ds.Tables[0].Columns.Contains("ProcessID"))
                {

                    newRow["ProcessID"] = dataRow["ProcessID"];
            }
                //newRow["LineIDText"] =  lineName;
                ds.Tables[0].Rows.InsertAt(newRow, newRowIndex);
                newRowIndex++;

            }
            // if (WorkShopID == "")
            {
                LineID = dataRow["LineID"].ToString();
                preWorkShopID = dataRow["WorkShopID"].ToString();
                lineName = dataRow["lineName"].ToString();
            }
            return preWorkShopID;
        }

        private static void GetSum(Dictionary<string, List<decimal>> dicSum, DataRow dataRow3)
        {
            string SaleTo = dataRow3["SaleTo"].ToString();
            if (dicSum.ContainsKey(dataRow3["SaleTo"].ToString()) == false)
            {
                dicSum.Add(SaleTo, new List<decimal>() { 0, 0, 0, 0, 0 });
            }
            decimal tmp1 = 0;
            decimal.TryParse(dataRow3["OweStockOutQty"].ToString(), out tmp1);
            dicSum[SaleTo][0] += tmp1;

            decimal tmp2 = 0;
            decimal.TryParse(dataRow3["Extend1"].ToString(), out tmp2);
            dicSum[SaleTo][1] += tmp2;

            decimal tmp3 = 0;
            decimal.TryParse(dataRow3["Extend2"].ToString(), out tmp3);
            dicSum[SaleTo][2] += tmp3;


            decimal tmp4 = 0;
            decimal.TryParse(dataRow3["Extend3"].ToString(), out tmp4);
            dicSum[SaleTo][3] += tmp4;

            decimal tmp5 = 0;
            decimal.TryParse(dataRow3["Extend4"].ToString(), out tmp5);
            dicSum[SaleTo][4] += tmp5;
            if (dataRow3["FreightType"].ToString() != "")
            {
                string FreightType = dataRow3["FreightType"].ToString();
                if (dicSum.ContainsKey(FreightType) == false)
                {
                    dicSum.Add(FreightType, new List<decimal>() { 0, 0, 0, 0, 0 });
                }
                tmp1 = 0;
                decimal.TryParse(dataRow3["OweStockOutQty"].ToString(), out tmp1);
                dicSum[FreightType][0] += tmp1;

                tmp2 = 0;
                decimal.TryParse(dataRow3["Extend1"].ToString(), out tmp2);
                dicSum[FreightType][1] += tmp2;

                tmp3 = 0;
                decimal.TryParse(dataRow3["Extend2"].ToString(), out tmp3);
                dicSum[FreightType][2] += tmp3;


                tmp4 = 0;
                decimal.TryParse(dataRow3["Extend3"].ToString(), out tmp4);
                dicSum[FreightType][3] += tmp4;

                tmp5 = 0;
                decimal.TryParse(dataRow3["Extend4"].ToString(), out tmp5);
                dicSum[FreightType][4] += tmp5;
            }
        }
       static Dictionary<string, DataTable>    lstDataSource = new Dictionary<string, DataTable>();
          Dictionary<string, DataTable> lstDataSourceData = new Dictionary<string, DataTable>();
        /// <summary>
        /// 生成行的下拉数据
        /// </summary>
        /// <param name="ds"></param>
        /// <param name="mSSQLCore"></param>
        protected void GetDataSource(DataTable dt, MSSQLCore mSSQLCore)
        {
            if (dt.Columns.Contains("BColors") == false)
            {
                dt.Columns.Add("BColors", typeof(Dictionary<string, string>));
            }
            if (dt.Columns.Contains("FColors") == false)
            {
                dt.Columns.Add("FColors", typeof(Dictionary<string, string>));
            }
            foreach (var n in mSSQLCore.Dev_DictionaryFields.Where(m => (m.ControlType == "combobox" || m.ControlType == "el-select") && m.IsVisible == true))
            {

                if (!string.IsNullOrEmpty(n.DataSourceID))
                {
                    if (n.QueryMethod == (int)QueryMethod.模糊匹配 || n.QueryMethod == (int)QueryMethod.精确匹配 || n.QueryMethod.HasValue == false)
                    {
                        DataTable dataTable = null;
                        if (lstDataSource.ContainsKey(n.DataSourceID) == false)
                        {
                            dataTable = SqlHelper.ExecuteDataTable("SELECT * FROM [Dev_DataSource] WHERE [DataSourceID]='" + n.DataSourceID + "'");
                            lstDataSource.Add(n.DataSourceID, dataTable);
                        }
                        else
                        {
                            dataTable = lstDataSource[n.DataSourceID];
                        }

                        string value = "", label = "";
                        if (dt.Columns.Contains(n.ParameterName + "Text") == false)
                        {
                            dt.Columns.Add(n.ParameterName + "Text");
                        }
                        if (dataTable.Rows.Count > 0)
                        {

                            value = dataTable.Rows[0]["DataValue"].ToString();
                            label = dataTable.Rows[0]["DataText"].ToString();
                            string USQL = dataTable.Rows[0]["USQL"].ToString();
                            try
                            {
                                if (dev_Account != null)
                                {
                                    USQL = USQL.Replace("{CenterID}", dev_Account.CenterID.ToString());
                                    USQL = USQL.Replace("{WorkFlowInstanceID}", dev_Account.WorkFlowInstanceID);
                                    USQL = USQL.Replace("{Account}", dev_Account.Account);
                                    USQL = USQL.Replace("{GroupID}", dev_Account.GroupID.ToString());
                                }


                            }
                            catch (Exception ex)
                            {

                            }
                            DataTable dtUSQL = null;
                            if (lstDataSourceData.ContainsKey(n.DataSourceID) == false)
                            {
                                dtUSQL = SqlHelper.ExecuteDataTable(USQL);
                            }
                            else
                            {
                                dtUSQL = lstDataSourceData[n.DataSourceID];
                            }
                            

                            if (dtUSQL.Columns.Contains("value") == false)
                            {
                                dtUSQL.Columns.Add("value", dtUSQL.Columns[value].DataType);
                            }
                            if (dtUSQL.Columns.Contains("label") == false)
                            {
                                dtUSQL.Columns.Add("label");
                            }
                            if (dtUSQL.Columns.Contains("text") == false)
                            {
                                dtUSQL.Columns.Add("text");
                            }
                            if (value.ToLower() != "value")
                            {
                                dtUSQL.Columns["value"].Expression = value;
                            }
                            if (value.ToLower() != "label")
                            {
                                dtUSQL.Columns["label"].Expression = label;

                            }
                            if (value.ToLower() != "text")
                            {

                                dtUSQL.Columns["text"].Expression = label;
                            }

                            if (dt.Columns.Contains(dataTable.Rows[0]["DataSouceName"].ToString()) == false)
                            {
                                dt.Columns.Add(dataTable.Rows[0]["DataSouceName"].ToString(), typeof(DataTable));
                            }
                            List<string> listColumnsFilter = new List<string>();
                            foreach (DataRow rowData in dt.Rows)
                            {



                                DataTable dtDataSource = dtUSQL.Clone();
                                //临时查询语句
                                //if (n.DictionaryID == 9016 && n.DataSourceID == "D1811230001" && !string.IsNullOrEmpty(rowData["MaterialID"].ToString()))
                                //{

                                //    foreach (DataRow dataRow in dtUSQL.Select("MaterialID=" + rowData["MaterialID"]))
                                //    {
                                //        DataRow newRow = dtDataSource.NewRow();
                                //        foreach (DataColumn dataColumn in dtUSQL.Columns)
                                //        {
                                //            newRow[dataColumn.ColumnName] = dataRow[dataColumn.ColumnName];
                                //        }
                                //        dtDataSource.Rows.Add(newRow);
                                //    }
                                //}
                                //else
                                {
                                    if (dataTable.Columns.Contains("RowFilter") && !string.IsNullOrEmpty(dataTable.Rows[0]["RowFilter"].ToString()))
                                    {
                                        string RowFilter = dataTable.Rows[0]["RowFilter"].ToString();

                                        if (listColumnsFilter.Count == 0)
                                        {
                                            foreach (DataColumn dataColumn1 in dt.Columns)
                                            {
                                                if (RowFilter.Contains($"{dataColumn1.ColumnName}"))
                                                {
                                                    listColumnsFilter.Add(dataColumn1.ColumnName);
                                                }
                                              
                                            }
                                        }
                                        foreach (string s in listColumnsFilter)
                                        {
                                            RowFilter = RowFilter.Replace("{" + s + "}", rowData[s].ToString());
                                            
                                        }
                                        try
                                        {


                                            DataRow[] drSelect = dtUSQL.Select(RowFilter);
                                            foreach (DataRow dataRow in drSelect)
                                            {
                                          
                                                dtDataSource.ImportRow(dataRow);
                                            }
                                            if (drSelect.Length == 0 && rowData["RowNumber"].ToString()!="")
                                            {



                                                Dictionary<string, string> fColors = new Dictionary<string, string>();//字体颜色
                                                Dictionary<string, string> bColors = new Dictionary<string, string>();//背景颜色

                                                bColors.Add(n.ParameterName, "#F25353");
                                                rowData["BColors"] = bColors;



                                            }
                                        }
                                        catch(Exception ex)
                                        {

                                        }
                                        //没有条件的不再返回
                                        rowData[dataTable.Rows[0]["DataSouceName"].ToString()] = dtDataSource;
                                    }
                                    else
                                    {
                                        dtDataSource = dtUSQL;
                                    }

                                }

                                if (lstDayList.Contains(dicID)||AppInfo.PushType=="TP")
                                {
                                    rowData[dataTable.Rows[0]["DataSouceName"].ToString()] = dtDataSource;
                                }

                               
                                string text = "";
                                DataRow[] dataRows = null;
                                // if(dt.Columns[n.ParameterName].DataType==typeof(int))
                                try
                                {
                                    if (!string.IsNullOrEmpty(rowData[n.ParameterName].ToString()))
                                    {
                                        var cellVal = rowData[n.ParameterName].ToString().Replace("'", "''");
                                        dataRows = dtDataSource.Select("value='" + cellVal + "'");
                                        if (dataRows.Length == 0)
                                            dataRows = dtDataSource.Select("label='" + cellVal + "'");
                                    }
                                    if (dataRows != null && dataRows.Length > 0)
                                    {
                                        text = dataRows[0]["label"].ToString();
                                    }
                                    else if (string.IsNullOrEmpty(text) && !string.IsNullOrEmpty(rowData[n.ParameterName].ToString()))
                                    {
                                        text = rowData[n.ParameterName].ToString();
                                    }
                                    if (!string.IsNullOrEmpty(text))
                                    {
                                        rowData[n.ParameterName + "Text"] = text;
                                    }
                                }
                                catch (Exception ex)
                                { }
                            }


                        }
                    }

                }
                else if (n.ParameterName == "QueryMethod")
                {


                    if (dt.Columns.Contains("QueryMethodProp") == false)
                    {
                        dt.Columns.Add("QueryMethodProp", typeof(DataTable));

                    }


                    DataTable dtUSQL = new DataTable();

                    if (dtUSQL.Columns.Contains("value") == false)
                    {
                        dtUSQL.Columns.Add("value", typeof(int));
                    }
                    if (dtUSQL.Columns.Contains("label") == false)
                    {
                        dtUSQL.Columns.Add("label");
                    }
                    if (dtUSQL.Columns.Contains("text") == false)
                    {
                        dtUSQL.Columns.Add("text");
                    }
                    int index = 0;
                    foreach (var obj in Enum.GetValues(typeof(QueryMethod)))
                    {
                        DataRow newRow = dtUSQL.NewRow();
                        newRow["value"] = index;
                        newRow["label"] = obj.ToString();
                        newRow["text"] = obj.ToString();
                        dtUSQL.Rows.Add(newRow);
                        index++;
                    }
                    if (dt.Columns.Contains(n.ParameterName + "Text") == false)
                    {
                        dt.Columns.Add(n.ParameterName + "Text");
                    }
                    foreach (DataRow dataRow1 in dt.Rows)
                    {
                        dataRow1["QueryMethodProp"] = dtUSQL;
                        string text = "";
                        DataRow[] dataRows = null;
                        // if(dt.Columns[n.ParameterName].DataType==typeof(int))
                        try
                        {
                            if (!string.IsNullOrEmpty(dataRow1[n.ParameterName].ToString()))
                            {
                                dataRows = dtUSQL.Select("Value='" + dataRow1[n.ParameterName] + "'");
                            }
                            else
                            {
                                //  dataRows = dtUSQL.Select("Value='" + dataRow1[n.ParameterName] + "'");
                            }
                            if (dataRows != null && dataRows.Length > 0)
                            {
                                text = dataRows[0]["label"].ToString();
                                dataRow1[n.ParameterName + "Text"] = text;
                            }
                        }
                        catch (Exception ex)
                        { }
                    }

                }
            }
        }

        public bool isAllOK = true;
        public string allMsg = "";
        protected JArray jArray = null;
        List<int> listErrorRows = new List<int>();
        string ReturnSql = "";
       /// <summary>
       /// 保存初始化一些工作
       /// </summary>
        protected void DataReset()
        {
            if (Dev_DictionaryAll == null)
            {

                Dev_DictionaryAll = Entities.Dev_Dictionary.ToList();
                lstOrgs = Entities.Dev_Organize.ToList();
            }
           
        }
        /// <summary>
        /// 添加后返回的主键集合
        /// </summary>
        public List<string> lstKeyValue = new List<string>();
        /// <summary>
        /// 通用保存版本
        /// </summary>
        /// <returns></returns>
        public JsonResult SaveData()
        {

            //最外层：数组，表头与行的关系：childrens,行的外键ID：ForeginKey保持主表，
            //数据格式：[{dicID:5100,OrderID:2000},         {dicID:5200,OrderID:5201,KeyID:'',childrens:[{Scheduling:201,OrderID:5201,KeyID:''}]}]
            // //  this.firstData[0]["childrens"] = [{ dicID: 22, Remark1: '3344', OrganizeID: null }, { dicID: 22, Remark1: '2244', OrganizeID: null }]

            bool result = true;
          
            int index = -1;
            string msg = "";
            if (jArray == null)
            {
                jArray = JsonConvert.DeserializeObject(BodyJson) as JArray;
            }

            if (jArray == null)
            {
                msg = "未接收到数据，请确认是否为JSON格式";
                result = false;
            }
            else
            {
                if (jArray.Count > 0)
                {

                    //var a=  V_Dev_Account.GetDev_Account("admin");
                    //  V_Dev_Account.SetDev_Account(a);
                    if (dev_Account != null)
                    {

                        DataReset();

                             SqlConnection connection = new SqlConnection(SqlHelper.MSSQLConnectionString);
                        connection.Open();
                        using (SqlTransaction tran = connection.BeginTransaction())
                        {
                            try
                            {

                                //   dev_DictionariesAll = Entities.Dev_DictionaryField.ToList();

                             
                                isAllOK = true;
                                string DictionaryID = "";
                                //第一步，循环所有的对象，这里可包含多个表
                                foreach (var jObject1 in jArray)
                                {

                                    index++;
                                    JObject jObject = jObject1 as JObject;
                                    if (jObject == null)
                                    {
                                        continue;
                                    }
                                    if (jObject.ContainsKey("RowNumber") && string.IsNullOrEmpty(jObject["RowNumber"].ToString()))
                                    {
                                        continue;
                                    }
                                    if (!string.IsNullOrEmpty(jObject["dicID"].ToString()))
                                    {
                                        dicID = int.Parse(jObject["dicID"].ToString());
                                        if (dicID == 35)
                                        {
                                            DictionaryID = jObject["DictionaryID"].ToString();
                                        }
                                    }
                                    //if(jObject.Count>21)
                                    //{
                                    try
                                    {

                                        if (jObject["dicID"].ToString() == "6704")
                                        {
                                            jObject["Remark2"] = jObject["MaterialName"].ToString();
                                            if (jObject.ContainsKey("ID") && !string.IsNullOrEmpty(jObject["ID"].ToString()))
                                            {

                                            }
                                            else
                                            {
                                                if (jObject.ContainsKey("childrens") == false || ((JArray)jObject["childrens"]).Count == 0 || string.IsNullOrEmpty(((JArray)jObject["childrens"])[0]["Account"].ToString()) || string.IsNullOrEmpty(((JArray)jObject["childrens"])[0]["dicID"].ToString()))
                                                {
                                                    result = false;
                                                    msg = allMsg = "报工必须选中人员";
                                                    isAllOK = false;
                                                    break;
                                                }
                                            }
                                        }
                                        JObject obj = jObject.DeepClone() as JObject;
                                        if (AppInfo.IsSaveLog)
                                        {


                                            systemLog.SaveLog(SystemLog.SystemLogType.SQL更新, obj.ToString(), dev_Account, null);
                                        }
                                      
                                        result = SaveDB(obj, ref msg, tran, "", "");
                                     
                                        if (result == false)
                                        {
                                            //tran.Rollback();
                                            allMsg = msg;
                                            isAllOK = false;
                                            break;
                                        }
                                        else
                                        {
                                            if (dicID == 45&& jObject.ContainsKey("DataSourceID"))
                                            {//去掉数据与的缓存
                                                lstDataSource.Remove(jObject["DataSourceID"].ToString());
                                            }
                                        }
                                    }
                                    catch (Exception ex)
                                    {
                                        tran.Rollback();
                                        msg += "第" + (index + 1) + "行发送错误：" + ex.Message;// + ex.StackTrace;
                                        listErrorRows.Add(index);
                                        if (jObject["dicID"].ToString() == "5043")
                                        {
                                            jObject["MaterialType"] = ex.Message;
                                        }
                                        result = false;
                                        allMsg = msg;
                                        isAllOK = false;
                                        break;
                                    }
                                    //}
                                    //else
                                    //{ }


                                }



                                if (isAllOK == true)
                                {

                                    msg = "保存成功";
                                    allMsg = msg;

                                    DataTable dataTable = SqlHelper.ExecuteDataTable($@"SELECT AfterExecution
FROM Dev_Dictionary
WHERE DictionaryID={dicID}");
                                    if(dataTable.Rows.Count>0)
                                    {
                                        string AfterExecution = dataTable.Rows[0]["AfterExecution"].ToString();
                                        if (!string.IsNullOrEmpty(AfterExecution))
                                        {
                                            
                                            SqlHelper.ExecuteNonQuery(tran,CommandType.Text,AfterExecution);
                                        }
                                    }
                                    tran.Commit();
                                  

                                    if (dicID == 35)
                                    {
                                        List<string> list = new List<string>();
                                       foreach(string key in APSCatchElemet.Keys)
                                        {

                                            if (key.Contains(DictionaryID)){

                                                list.Add(key);
                                              
                                            }
                                     
                                        }
                                       foreach(string key in list)
                                        {
                                            APSCatchElemet.Remove(key);
                                        }
                                       
                                    }
                                  
                                }






                            }
                            catch (Exception ex)
                            {
                                //tran.Rollback();
                                msg = "第" + index + "行发送错误：" + ex.Message;// + ex.StackTrace;
                                result = false;
                                allMsg = msg;
                                isAllOK = false;
                            }

                        }
                        connection.Close();
                    }
                    else
                    {
                        msg = "请登录！";
                        result = false;
                    }
                }
                else
                {
                    msg = "未接收到数据！";
                    result = false;
                }


            }
            JsonResult json = new JsonResult();
            json.MaxJsonLength = int.MaxValue;
            msg = Translation(msg);
            json.Data = new { msg, result, //data = jArray, sql = ReturnSql
                 lstKeyValue };
            return json;

        }
        /// <summary>
        /// 对语言进行翻译，要先配置对应的语言表
        /// </summary>
        /// <param name="msg"></param>
        /// <returns></returns>
        public string Translation(string msg)
        {
           
            if (dtLanguage != null)
            {
              // foreach (DataRow dr in dt.Rows)
                {
                    DataRow[] dataRows = dtLanguage.Select("zhcn ='" + StringHelper.ReplaceSQL(msg) + "'");
                    if (dataRows.Length > 0)
                    {
                        msg = dataRows[0]["TargetCode"].ToString();
                    }
                    else
                    {
                        foreach (DataRow dr in dtLanguage.Select("zhcn ='" + StringHelper.ReplaceSQL(msg) + "' AND DataSource='后台信息'"))
                        {
                            
                                msg = msg.Replace(dataRows[0]["zhcn"].ToString(),dataRows[0]["TargetCode"].ToString());
                           
                        }
                    }
                }
            }
            return msg;
        }
