                {//第一次没有读取到数据
                    dev_DictionaryFields = Entities.Dev_DictionaryField.Where(m => m.DictionaryID == dicID).ToList();
                    //加入数据
                    dev_DictionaryFieldsAll.AddRange(dev_DictionaryFields);
                    dev_DictionaryFieldsOld = dev_DictionaryFields;
                }
                else
