                    }
                }
            }
            else
            {
                result = false;
                msg = "dicID没有值";
                isAllOK = false;
            }

            return result;
        }

        public string APSDataOR()
        {
            bool result = true;
            string msg = "";
            DataSet ds = null;
            JObject jObject = null;
            try
            {
                //使用数组的关系
                ///数组结构[dicid:100,{name:'id'},{code:'10020003'}]
                jObject = JsonConvert.DeserializeObject(BodyJson) as JObject;
                try
                {

                    int dicID = int.Parse(jObject["dicID"].ToString());

                    MSSQLCore mSSQLCore = new MSSQLCore(dicID, jObject, "");
                    mSSQLCore.IsUserOR = true;
                    // mSSQLCore.Where = "  AND Status=1";


                    mSSQLCore.GetSql();

                    ds = SqlHelper.ExecuteDataset(SqlHelper.MSSQLConnectionString, CommandType.Text, mSSQLCore.SQL);


                    if (dicID == 12)
                    {//产品读取工序信息

                        ds.Tables[0].Columns.Add("Process", typeof(List<V_APS_ProcessMaterial>));
                        string materialID = "0";
                        foreach (DataRow dr in ds.Tables[0].Rows)
                        {
                            materialID += dr["MaterialID"].ToString() + ",";
                        }

                        List<V_APS_ProcessMaterial> LIST = Entities.SqlQueryRaw<V_APS_ProcessMaterial>("SELECT * FROM V_APS_ProcessMaterial WHERE MaterialID IN(" + materialID.Trim(',') + ")").ToList();
                        foreach (DataRow dr in ds.Tables[0].Rows)
                        {
                            long MaterialID = (long)dr["MaterialID"];
                            dr["Process"] = LIST.Where(m => m.MaterialID == MaterialID).ToList();
                        }

                    }
                    msg = "读取成功";
                }
                catch (Exception ex)
                {
                    msg = ex.Message;
                    result = false;
                }

            }
            catch (Exception ex)
            {
                result = false;
                msg = ex.Message;
            }
            if (result == false)
            {
                ds = new DataSet();
                ds.Tables.Add(new DataTable());
                ds.Tables.Add(new DataTable());
            }

            int count = 0;
            try
            {
                count = int.Parse(ds.Tables[1].Rows[0][0].ToString());
            }
            catch (Exception ex)
            {

            }
            IsoDateTimeConverter timeFormat = new IsoDateTimeConverter();
            timeFormat.DateTimeFormat = "yyyy-MM-dd";

            return JsonConvert.SerializeObject(new
            {

                data = ds.Tables[0].DefaultView.ToTable(),//数据
                result//返回标记
                       ,
                msg//返回的信息
                       ,
                count = count < ds.Tables[0].Rows.Count ? ds.Tables[0].Rows.Count : count //记录数
            }, timeFormat);

        }
