        /// <summary>
        /// 通过组件报工
        /// </summary>
        /// <returns></returns>
        public JsonResult ProbaictionByBom()
        {
            bool result = true;

            string msg = "";
            JArray jArray = JsonConvert.DeserializeObject(BodyJson) as JArray;
            if (jArray == null)
            {
                msg = "未接收到数据，请确认是否为JSON格式";
                result = false;
            }
            else
            {
                SqlConnection connection = new SqlConnection(SqlHelper.MSSQLConnectionString);
                connection.Open();
                using (SqlTransaction tran = connection.BeginTransaction())
                {
                    try
                    {
                        //第一步，循环所有的对象，这里可包含多个表
                        foreach (JObject jObject in jArray)
                        {
                            decimal d1 = 0, d2 = 0;
                            if (jObject.ContainsKey("ProductionQty") && jObject["ProductionQty"] != null)
                            {
                                decimal.TryParse(jObject["ProductionQty"].ToString(), out d1);
                            }
                            if (jObject.ContainsKey("BadQty") && jObject["BadQty"] != null)
                            {
                                decimal.TryParse(jObject["BadQty"].ToString(), out d2);
                            }
                            if (d1 > 0)
                            {
                                SqlParameter[] sqlParameters = new SqlParameter[9];
                                sqlParameters[0] = new SqlParameter("@ProcessPlanID", jObject["ProcessPlanID"].ToString());//工序计划ID
                                sqlParameters[1] = new SqlParameter("@OrderBOMID", jObject["OrderBOMID"].ToString());// BO主建
                                sqlParameters[2] = new SqlParameter("@ProductionQty", d1);//本次报工数量
                                sqlParameters[3] = new SqlParameter("@BadQty", d2);//损坏数量
                                sqlParameters[4] = new SqlParameter("@StarHour", jObject["StarHour"].ToString());//开始日期
                                sqlParameters[5] = new SqlParameter("@EndHour", jObject["EndHour"].ToString());//结束日期
                                sqlParameters[6] = new SqlParameter("@Account", dev_Account.Account);
                                sqlParameters[7] = new SqlParameter("@Result", SqlDbType.Int);
                                sqlParameters[8] = new SqlParameter("@Msg", SqlDbType.NVarChar, 300);
                                SqlHelper.ExecuteNonQuery(SqlHelper.MSSQLConnectionString, "P_APS_DayProductionByProcessPlanID", sqlParameters);

                            }


                        }



                        if (isAllOK == true)
                        {

                            msg = "保存成功";
                            result = true;
                        }



                        tran.Commit();


                    }
                    catch (Exception ex)
                    {
                        tran.Rollback();
                        msg = ex.Message;
                        result = false;
                    }
                }
                connection.Close();
            }
            return FormResult(result, msg, "");
        }


