                    connection.Open();
                    using (SqlTransaction tran = connection.BeginTransaction())
                    {
                        try
                        {

                            string sql = "DECLARE @PreparePlanID bigint;DECLARE @SalesOrderDetailID varchar(20);DECLARE @setPrepareCount int;";
                            bool isError = false;
                            //第一步，循环所有的对象，这里可包含多个表
