                                    // sql += "SET @PreparePlanID=" + jObject["PreparePlanID"];
                                    sql += ";SET @SalesOrderDetailID='" + jObject["SalesOrderDetailID"] + "'";
                                    sql += string.Format(@"
--1.先删除备料计划
delete APS_PreparePlan where SalesOrderDetailID = @SalesOrderDetailID
--2.比较销售单的总工单数与已经生成备料计划的工单数 ,更新销售单的状态
 
select  @setPrepareCount = count(1)
from APS_PreparePlan a where a.SalesOrderDetailID = @SalesOrderDetailID

if(@setPrepareCount = 0)
begin 
update APS_SalesPlan set IsSetPrepare = '未生成' where SalesOrderDetailID = @SalesOrderDetailID
end
else if(@setPrepareCount > 0)
begin 
update APS_SalesPlan set IsSetPrepare = '部分生成' where SalesOrderDetailID = @SalesOrderDetailID
end
");
                                }

                            }
                            if (isError == false)
                            {
                                SqlHelper.ExecuteNonQuery(tran, CommandType.Text, sql);
                                tran.Commit();
                                msg = "操作成功";
                            }
                            else
                            {
