                        catch (Exception ex)
                        {
                            tran.Rollback();
                            result = false;
                            msg = ex.Message;
                        }
                    }
                }

            }
            catch (Exception ex)
            {
                msg = ex.Message;
                result = false;
            }

            return new JsonResult()
            {
                Data = new
                {
                    data = new string[] { code },
                    result//返回标记
                       ,
                    msg//返回的信息 }
                }
            };
