        /// <summary>
        /// V2获取工单信息
        /// </summary>
        /// <returns></returns>
        public string GetOrderInfo()
        {
            bool result = true;
            string msg = "";
            DataSet ds = null;

            try
            {


                ds = SqlHelper.ExecuteDataset(SqlHelper.MSSQLConnectionString, CommandType.Text, @"SELECT 
sum(CASE WHEN ProductionStatus=26 and ProductionStatus<>24 THEN 1 ELSE 0 END) AS Qty1
,sum(CASE WHEN ProductionStatus=26 and ProductionStatus<>24   THEN 0 ELSE 1 END) AS Qty2
,sum(CASE WHEN ProductionStatus=24   THEN 1 ELSE 0 END) AS Qty3
,SUM(ProducedQty)-sum(StockOutQty) AS Qty4
,SUM(Qty)-sum(ProducedQty) AS Qty5
,SUM(A2.Qty6) AS Qty6
,sum(CASE WHEN GroupCabinet<>''   THEN ProducedQty ELSE 0 END) AS Qty7
,SUM(A.Volume*A.ProducedQty) AS Qty8
,SUM(A.Volume*A.OweProducedQty) AS Qty9
FROM APS_Order A
LEFT JOIN(
SELECT SUM(a.PlanQty-a.HasQty) as Qty6,OrderID
 FROM
APS_ProcessPlan A
INNER JOIN APS_Process B ON A.ProcessID=B.ProcessID
WHERE B.ProcessName='包装'
GROUP BY OrderID
) A2 ON A.OrderID=A2.OrderID
WHERE   Status=1
");


            }
            catch (Exception ex)
            {
                result = false;
                msg = ex.Message;
            }
            if (result == false)
            {
                ds = new DataSet();
                ds.Tables.Add(new DataTable());
                ds.Tables.Add(new DataTable());
            }

            int count = 0;
            try
            {
                count = int.Parse(ds.Tables[1].Rows[0][0].ToString());
            }
            catch (Exception ex)
            {

            }
            IsoDateTimeConverter timeFormat = new IsoDateTimeConverter();
            timeFormat.DateTimeFormat = "yyyy-MM-dd";

            return JsonConvert.SerializeObject(new
            {

                data = ds.Tables[0].DefaultView.ToTable(),//数据
                result//返回标记
                       ,
                msg//返回的信息
                       ,
                count = count < ds.Tables[0].Rows.Count ? ds.Tables[0].Rows.Count : count //记录数
            }, timeFormat);
        }

        /// <summary>
        /// APP送货需求
        /// </summary>
        /// <returns></returns>
        public string GetDeliverDemand()
        {
            bool result = true;

            string msg = "";
            JObject jObject = JsonConvert.DeserializeObject(BodyJson) as JObject;
            if (jObject == null)
            {
                msg = "未接收到数据，请确认是否为JSON格式";
                result = false;
            }
            else
            {

            }
            int count = 0;
            Dictionary<string, DataTable> keyValuePairs = new Dictionary<string, DataTable>();
            try
            {


                int pageSize = 5;
                int pageIndex = 1;

                //一次显示多少日期
                if (jObject["rows"] != null)
                {
                    int.TryParse(jObject["rows"].ToString(), out pageSize);
                }
                //当前的页数
                if (jObject["page"] != null)
                {
                    int.TryParse(jObject["page"].ToString(), out pageIndex);
                }
                DateTime dateTime = DateTime.Now;
                for (int i = pageSize * (pageIndex - 1); i < pageSize * (pageIndex - 1); i++)
                {

                    DataTable dataTable = SqlHelper.ExecuteDataTable(@"SELECT * FROM V_APS_AppSetGoodsList
        WHERE DeliveryDay='" + dateTime + @"'
                    ");
                    if (dataTable.Rows.Count <= 0)
                    {
                        continue;
                    }
                    else
                    {
                        keyValuePairs.Add(string.Format("{0:yyyy-MM-dd}", dateTime), dataTable);
                    }
                }

            }
            catch (Exception ex)
            {

            }
            IsoDateTimeConverter timeFormat = new IsoDateTimeConverter();
            timeFormat.DateTimeFormat = "yyyy-MM-dd";

            return "";
        }

