                    {
                        if (jObject.ContainsKey("dicID") == true)
                        {
                            int dicID = int.Parse(jObject["dicID"].ToString());
                            string Account = jObject["Account"].ToString();
                            string OrganizeID = jObject["OrganizeID"].ToString();
                            int start = int.Parse(jObject["pageSize"].ToString()) * (int.Parse(jObject["pageIndex"].ToString()) - 1);
                            int end = start + int.Parse(jObject["pageSize"].ToString());
                            JArray DeliveryDays = jObject["DeliveryDay"] as JArray;
                            String where = "Account = '" + Account + "' and OrganizeID = '" + OrganizeID + "' and  abs(OweQty) > 0 ";
                            if (DeliveryDays == null)
                            {
                                msg = "未接收到数据，请确认是否为JSON格式";
                                result = false;
                            }
                            else
                            {
                                string fields = "";
                                if (jObject.ContainsKey("fields"))
                                {
                                    fields = jObject["fields"].ToString(); ;
                                }
                                MSSQLCore mSSQLCore = new MSSQLCore(dicID, jObject, "");
                                mSSQLCore.Fields = fields;
                                if (jObject.ContainsKey("groupby"))
                                {
                                    mSSQLCore.GroupBy = jObject["groupby"].ToString(); ;
                                }

                                mSSQLCore.GetSql();
                                ds = SqlHelper.ExecuteDataset(SqlHelper.MSSQLConnectionString, CommandType.Text, mSSQLCore.SQL);

                                if (!string.IsNullOrEmpty(DeliveryDays[0].ToString()))
                                {
                                    where += " and DeliveryDay >= '" + DeliveryDays[0].ToString() + "' ";
                                }
                                else if (!string.IsNullOrEmpty(DeliveryDays[1].ToString()))
                                {
                                    where += " and DeliveryDay <= '" + DeliveryDays[1].ToString() + "' ";
                                }
                                DataTable LIST = SqlHelper.ExecuteDataTable(@"select format(DeliveryDay,'yyyy-MM-dd') as DeliveryDay from V_APS_AppSetGoodsList where " + where + " group by DeliveryDay ");

                                LIST.Columns.Add("childrens", typeof(DataTable));
                                foreach (DataColumn dataColumn1 in LIST.Columns)
                                {
                                    newDs.Tables[0].Columns.Add(dataColumn1.ColumnName, dataColumn1.DataType);
                                }
                                foreach (DataRow dr in LIST.Rows)
                                {
                                    DataRow[] dataRows = ds.Tables[0].Select("DeliveryDay='" + dr["DeliveryDay"].ToString() + "'");

                                    DataTable children = ds.Tables[0].Clone();
                                    foreach (DataRow dataRow in dataRows)
                                    {
                                        DataRow newRow = children.NewRow();
                                        foreach (DataColumn dataColumn in ds.Tables[0].Columns)
                                        {
                                            newRow[dataColumn.ColumnName] = dataRow[dataColumn.ColumnName];
                                        }
                                        children.Rows.Add(newRow);
                                    }
                                    dr["childrens"] = children;
                                    //m[name]

                                }
                                for (int i = start; i < end; i++)
                                {

                                    if (i >= LIST.Rows.Count)
                                    {
                                        break;
                                    }
                                    else
                                    {
                                        //DataRow x = ds.Tables[0].Rows[i];
                                        //newDs.Tables[0].Rows.Add(x);

                                        DataRow newRows = newDs.Tables[0].NewRow();
                                        foreach (DataColumn dataColumn in LIST.Columns)
                                        {
                                            newRows[dataColumn.ColumnName] = LIST.Rows[i][dataColumn.ColumnName];
                                        }
                                        newDs.Tables[0].Rows.Add(newRows);

                                    }
                                }
                            }
                            msg = "读取成功";
                        }
                        else
                        {
                            msg = "没有接收到dicID";
                            result = false;
                        }
                    }
                    catch (Exception ex)
                    {
                        msg = ex.Message;
                        result = false;
                    }
                }
            }
            catch (Exception ex)
            {
                result = false;
                msg = ex.Message;
            }
            if (result == false)
            {
                ds = new DataSet();
                ds.Tables.Add(new DataTable());
            }

            int count = 0;
            try
            {
                count = int.Parse(ds.Tables[1].Rows[0][0].ToString());
            }
            catch (Exception ex)
            {

            }
            IsoDateTimeConverter timeFormat = new IsoDateTimeConverter();
            timeFormat.DateTimeFormat = "yyyy-MM-dd";

            return JsonConvert.SerializeObject(new
            {

                data = newDs.Tables[0].DefaultView.ToTable(),//数据
                result//返回标记
                       ,
                msg//返回的信息
                       ,
                count = count < newDs.Tables[0].Rows.Count ? newDs.Tables[0].Rows.Count : count //记录数
            }, timeFormat);
        }

