        /// <summary>
        /// 生成开拉期
        /// </summary>
        /// <returns></returns>
        public string GetProcessPartPlanEndDate()
        {

            bool result = false;
            string msg = "";
            List<V_APS_ProcessPartPlan> schedulings = JsonConvert.DeserializeObject<List<V_APS_ProcessPartPlan>>(BodyJson);
            try
            {


                Entities.Configuration.ValidateOnSaveEnabled = false;



                try
                {

                    DateTime endDate = DateTime.Now;

                    if (schedulings.Count == 0)
                    {
                        result = false;
                        msg = "没有选中的记录";
                    }
                    else
                    {


                        if (schedulings[0].DemandDate.HasValue == false)
                        {
                            result = false;
                            msg = "第一笔记录没有指定完工日期";
                        }

                        else
                        {
                            int rowNumber = 0;
                            bool tmp = true;
                            foreach (var obj in schedulings)
                            {
                                obj.Reset();

                                //if (obj.IsLocked == true)
                                {
                                    rowNumber++;
                                }
                                int tmpRowNumber = obj.RowNumber;
                                obj.RowNumber = tmpRowNumber;
                                if (obj.IsLocked == true && obj.DemandDate.HasValue == false)
                                {
                                    msg += "第" + rowNumber + "笔记录没有指定完工日期";
                                    result = false;
                                    tmp = false;

                                }
                                else if (obj.IsLocked == true && obj.DemandDate.HasValue == true && obj.DemandDate.Value.Date < DateTime.Now.Date)
                                {
                                    msg += "第" + rowNumber + "笔记录完工日期小于今天";
                                    result = false;
                                    tmp = false;

                                }

                                endDate = schedulings[0].DemandDate.Value;

                            }

                            if (tmp)
                            {

                                int rowIndex = 1;
                                foreach (var obj in schedulings)
                                {
                                    if (obj.IsLocked == true)
                                    {

                                        endDate = obj.DemandDate.GetValueOrDefault();
                                    }
                                    endDate = endDate.AddDays(-obj.FixDay);
                                    ObjectParameter objectParameter1 = new ObjectParameter("EndDate", endDate);
                                    ObjectParameter objectParameter2 = new ObjectParameter("Result", false);
                                    ObjectParameter objectParameter3 = new ObjectParameter("Msg", "");
                                    ObjectParameter objectParameter4 = new ObjectParameter("StartDate", DBNull.Value);
                                    ObjectParameter ExpectTime = new ObjectParameter("ExpectTime", DBNull.Value);

                                    Entities.P_aps_getstartdatebyenddate(obj.ProcessPartName, obj.MaterialID, obj.WorkShopID.GetValueOrDefault(), obj.OrderID.GetValueOrDefault(), obj.PlanQty.GetValueOrDefault(), objectParameter4, objectParameter1, ExpectTime, objectParameter2, objectParameter3).ToString();
                                    if (objectParameter2.Value.ToString().ToLower() != "true")
                                    {
                                        msg += objectParameter3.Value.ToString() + "<br/>";
                                        obj.IsBackground = true;
                                        tmp = false;
                                    }
                                    else
                                    {
                                        //从存储过程计算完成后重新赋值
                                        obj.StartDate = (DateTime)objectParameter4.Value;
                                        obj.DemandDate = (DateTime)objectParameter1.Value;
                                        endDate = obj.StartDate.GetValueOrDefault();
                                        obj.ExpectTime = Convert.ToDecimal(ExpectTime.Value);
                                        if (obj.StartDate.Value.Date < DateTime.Now.Date)
                                        {
                                            msg += "第" + rowIndex + "笔记录开拉期小于今天";
                                            result = false;
                                        }

                                    }

                                    rowIndex++;
                                }
                            }
                            if (tmp)
                            {
                                result = true;
                                msg = "计算成功";
                            }

                        }

                    }





                }
                catch (Exception ex)
                {
                    result = false;
                    msg = ex.Message;




                }
                finally
                {

                }




            }
            catch (Exception ex)
            {
                result = false;
                msg = ex.Message;
            }
            IsoDateTimeConverter timeFormat = new IsoDateTimeConverter();
            timeFormat.DateTimeFormat = "yyyy-MM-dd";
            return JsonConvert.SerializeObject(new { data = schedulings, result, msg }, timeFormat);

        }
