        public JsonResult GetErpData()
        {

            //  this.firstData[0]["childrens"] = [{ dicID: 22, Remark1: '3344', OrganizeID: null }, { dicID: 22, Remark1: '2244', OrganizeID: null }]

            bool result = true;

            string msg = null;
            string erpPro = "";
            if (ConfigurationManager.AppSettings["ErpPro"] != null)
            {//读取web.config配置文件
                erpPro = ConfigurationManager.AppSettings["ErpPro"].ToString();
            }
            if (string.IsNullOrEmpty(erpPro))
            {
                msg = "存储过程未配置";
                result = false;
            }
            try
            {
                SqlHelper.ExecuteNonQuery(SqlHelper.MSSQLConnectionString, CommandType.StoredProcedure, erpPro);
                msg = "数据下载成功";
            }
            catch (Exception ex)
            {
                msg = ex.Message;
                result = false;
            }
            return FormResult(result, msg, "");
        }

