        /// <summary>
        /// 产线负荷
        /// </summary>
        public class LineLoadInfo
        {
            public string Month
            {
                get
                {
                    return Date.Month.ToString();
                }
            }
            public string Name
            {
                get
                {
                    return Month + "月";
                }
            }
            public string YearMonth
            {
                get
                {
                    return string.Format("{0:yyyy-MM}", Date);
                }
            }
            public DateTime Date
            {
                get; set;
            }
            public List<DayInfo> Days
            {
                get; set;
            }
            public class DayInfo
            {
                public string Day
                {
                    get
                    {
                        return Date.HasValue ? Date.Value.Day.ToString() : "";
                    }
                }
                public DateTime? Date
                {
                    get; set;
                }
                public decimal Lineload
                {
                    get; set;
                }
                public decimal PlanQty
                {
                    get; set;
                }
                public string Work
                {
                    get; set;
                }
                public List<object> childrens
                {
                    get; set;
                }
            }
        }
        /// <summary>
        /// 获取产线负荷接口
        /// </summary>
        /// <returns></returns>
        public string GetLineLoad()
        {
            bool result = false;
            string msg = "";
            JObject jArray = JsonConvert.DeserializeObject(BodyJson) as JObject;
            int WorkShopID = int.Parse(jArray["WorkShopID"].ToString());
            DataTable dataTable = SqlHelper.ExecuteDataTable("SELECT * FROM V_APS_Lineload WHERE PlanDay>=CAST(GETDATE() AS DATE) and WorkShopID=" + WorkShopID);
            //查日历
            DateTime date = DateTime.Now.Date.AddDays(-30);
            var workingTimesDetails = Entities.Query<APS_OrganizeWorkingTimesDetail>().Where(m => m.WorkingDate >= date && m.OrganizeID == WorkShopID).ToList();

            //查日计划明细
            var aPS_DayPlans = Entities.Query<V_APS_DayPlan>().Where(m => m.PlanDay >= date && m.WorkShopID == WorkShopID && m.Status == 1).ToList();

            List<LineLoadInfo> list = new List<LineLoadInfo>();
            try
            {
                for (int month = 0; month < 3; month++)
                {
                    DateTime monthDate = DateTime.Now.AddMonths(month);
                    monthDate = monthDate.AddDays(-monthDate.Day + 1);
                    LineLoadInfo lineLoadInfo = new LineLoadInfo();
                    lineLoadInfo.Date = monthDate;
                    lineLoadInfo.Days = new List<LineLoadInfo.DayInfo>();
                    bool isFirstDay = false;
                    int day = 0;
                    for (int i = 0; i < 31; i++)
                    {

                        DateTime thisDate = monthDate.AddDays(day).Date;

                        LineLoadInfo.DayInfo dayInfo = new LineLoadInfo.DayInfo();
                        int week = ((int)thisDate.DayOfWeek);
                        if (week == 0)
                        {
                            week = 7;
                        }

                        if (isFirstDay == false)
                        {
                            if ((i + 1) < week)
                            {


                                lineLoadInfo.Days.Add(dayInfo);
                                continue;
                            }
                            else
                            {
                                isFirstDay = true;
                            }
                        }
                        thisDate = monthDate.AddDays(day).Date;
                        day++;

                        dayInfo.Date = thisDate.Date;

                        //查询是否上班
                        var details = workingTimesDetails.Where(m => m.WorkingDate == thisDate).FirstOrDefault();

                        //找日计划信息
                        DataRow[] dataRow = dataTable.Select("PlanDay='" + thisDate + "'");
                        //负荷
                        decimal lineload = 0;
                        //每日计划数量
                        decimal planQty = 0;
                        dayInfo.childrens = new List<object>();

                        if (dataRow.Length > 0)
                        {//找到日计划信息
                            decimal.TryParse(dataRow[0]["lineload"].ToString(), out lineload);
                            decimal.TryParse(dataRow[0]["planQty"].ToString(), out planQty);


                        }
                        dayInfo.Lineload = lineload;
                        dayInfo.PlanQty = planQty;
                        dayInfo.Date = thisDate;
                        if (details == null)
                        {//没有日历，则判断为休息：
                            dayInfo.Work = "休";
                        }
                        else
                        {
                            dayInfo.Work = "";
                        }
                        //日计划明细
                        dayInfo.childrens = new List<object>();
                        foreach (var dayPlan in aPS_DayPlans.Where(m => m.PlanDay == thisDate).ToList())
                        {
                            dayInfo.childrens.Add(new { dayPlan.OrderNo, dayPlan.PlanQty, dayPlan.HasQty, dayPlan.MaterialName, dayPlan.Code });
                        }

                        lineLoadInfo.Days.Add(dayInfo);

                    }
                    list.Add(lineLoadInfo);
                }
                result = true;
            }
            catch (Exception ex)
            {
                msg = ex.Message;
            }

            IsoDateTimeConverter timeFormat = new IsoDateTimeConverter();
            timeFormat.DateTimeFormat = "yyyy-MM-dd";
            return JsonConvert.SerializeObject(new { data = list, result, msg }, timeFormat);
        }


        /// <summary>
        /// 新版计算开拉期
        /// </summary>
        /// <returns></returns>
        public string ComputedStartDate()
        {
            bool result = true;
            string msg = "";



            try
            {
                JArray jArray = JsonConvert.DeserializeObject(BodyJson) as JArray;
                List<V_APS_OrganizeWorkingTimesDetail> v_APS_OrganizeWorkingTimesDetails = new List<V_APS_OrganizeWorkingTimesDetail>();
                if (jArray.Count > 0)
                {
                    DateTime dateTime = DateTime.Now.Date;
                    v_APS_OrganizeWorkingTimesDetails = Entities.Query<V_APS_OrganizeWorkingTimesDetail>().Where(m => m.WorkingDate >= dateTime).ToList();
                }
                else
                {
                    result = false;
                    msg = "未接收到数据";
                }
                string MaterialID = "0";
                foreach (JObject jObject in jArray)
                {
                    MaterialID += "," + jObject["MaterialID"].ToString();
                }


                DataTable dtCapacity = SqlHelper.ExecuteDataTable(@"SELECT  [MaterialID]
      ,[ProcessID]
      ,[Capacity]
       ,StandardPeoples
  FROM[dbo].[V_APS_ProcessMaterial]
where MaterialID in(" + MaterialID + @")
");



                Dictionary<long, DateTime> lines = new Dictionary<long, DateTime>();
                DateTime endDate = DateTime.Now;
                bool isFirst = true;
                string oldMaterialID = "0";
                foreach (JObject jObject in jArray)
                {
                    long lineID = 0;
                    long.TryParse(jObject["LineID"].ToString(), out lineID);
                    string orderID = jObject["OrderID"].ToString();
                    string processID = jObject["ProcessID"].ToString();
                    string startDate = jObject["StartDate"].ToString();
                    MaterialID = jObject["MaterialID"].ToString();
                    if (oldMaterialID == "0")
                    {
                        oldMaterialID = MaterialID;
                    }
                    if (string.IsNullOrEmpty(startDate))
                    {
                        //result = false;
                        //msg = "没有开拉期";
                        // break;
                        DataTable dataTable = SqlHelper.ExecuteDataTable(@"SELECT TOP 1 PlanDay FROM APS_DayPlan
WHERE LineID =" + lineID + @"
ORDER BY PlanDay DESC ");
                        if (dataTable.Rows.Count > 0)
                        {
                            startDate = dataTable.Rows[0]["PlanDay"].ToString();
                        }
                        else
                        {
                            startDate = string.Format("{0:yyyy-MM-dd 08:00:00}", DateTime.Now);
                        }
                        jObject["StartDate"] = startDate;
                    }
                    else
                    {
                        if (isFirst)
                        {
                            endDate = DateTime.Parse(startDate);
                            isFirst = false;
                        }
                    }

                    //分配数
                    decimal distributionQty = 0;
                    decimal.TryParse(jObject["DistributionQty"].ToString(), out distributionQty);
                    if (distributionQty <= 0)
                    {
                        result = false;
                        msg = "分配数不能为0";
                        break;
                    }
                    decimal capacity = 0;
                    decimal.TryParse(jObject["Capacity"].ToString(), out capacity);

                    if (capacity <= 0)
                    {
                        result = false;
                        msg = "产能不能为0";
                        break;
                    }
                    bool isFirstDay = false;
                    if (lines.ContainsKey(lineID) == false)
                    {
                        endDate = DateTime.Parse(startDate);
                        lines.Add(lineID, endDate);
                        isFirstDay = true;
                    }
                    else
                    {
                        endDate = lines[lineID];
                    }
                    jObject["StartDate"] = string.Format("{0:yyyy-MM-dd HH:mm:ss}", endDate);
                    int errorCount = 0;
                    decimal totalExpectTime = 0;
                    //标准人力
                    decimal StandardPeoples = 0;


                    DataRow[] dataRows = dtCapacity.Select("MaterialID=" + MaterialID + " AND ProcessID='" + processID + "'");

                    if (dataRows.Length > 0)
                    {
                        decimal.TryParse(dataRows[0]["StandardPeoples"].ToString(), out StandardPeoples);
                    }

                    for (int i = 0; i < 90; i++)
                    {
                        // DateTime d2 = endDate.AddDays(i).Date;
                        var times = v_APS_OrganizeWorkingTimesDetails.Where(m => m.OrganizeID == lineID && m.WorkingDate == endDate.Date).FirstOrDefault();



                        if (times == null)
                        {
                            errorCount++;
                            endDate = endDate.AddDays(1);
                            continue;
                        }
                        else
                        {
                            //当然上班人数
                            decimal totelPeoples = times.Peoples.GetValueOrDefault();

                            if (StandardPeoples <= 0)
                            {
                                StandardPeoples = totelPeoples;
                            }
                            if (totelPeoples <= 0)
                            {

                                msg = endDate + "出勤人数为0";
                                result = false;
                                break;
                            }

                            if (isFirstDay)
                            {//拉线第一次计算日期

                                isFirstDay = false;
                                DateTime d2 = DateTime.Parse(string.Format("{0:yyyy-MM-dd} ", endDate) + times.StartTime.Replace("T", "") + ":00");
                                jObject["StartDate"] = string.Format("{0:yyyy-MM-dd HH:mm:ss}", d2);
                                endDate = d2;
                            }
                            else
                            {

                            }
                            //当日可加工的数量=分配数量-产能*当天工时
                            decimal lessHours = 0;
                            if (string.IsNullOrEmpty(times.Code))
                            {//临时使用这个保存当天剩余的工时

                                lessHours = times.TotalHours.GetValueOrDefault();
                                times.Code = lessHours.ToString();
                            }
                            else
                            {
                                decimal.TryParse(times.Code, out lessHours);
                            }
                            if (i >= 29)
                            {
                                capacity = distributionQty;
                            }
                            decimal oweQty = distributionQty - (totelPeoples / StandardPeoples * capacity * lessHours);

                            if (oweQty <= 0)
                            {//说明当天产能已经剩余，当天可以做完了
                                //算出实际的产能
                                decimal qty2 = totelPeoples / StandardPeoples * capacity * lessHours - distributionQty;
                                // if (qty2 > distributionQty)
                                {
                                    qty2 = distributionQty;
                                }
                                //推算出加工工时
                                decimal ExpectTime = qty2 / (totelPeoples / StandardPeoples * capacity * lessHours) * times.TotalHours.GetValueOrDefault();
                                totalExpectTime += ExpectTime;
                                times.Code = (lessHours - ExpectTime).ToString();
                                endDate = endDate.AddHours(Convert.ToDouble(ExpectTime));
                                if (oldMaterialID != MaterialID)
                                {
                                    endDate = endDate.AddHours(0.5);
                                }

                                jObject["EndDate"] = string.Format("{0:yyyy-MM-dd HH:mm:ss}", endDate);

                                // jObject["ExpectTime"] = ExpectTime;
                                DateTime dateTime = DateTime.Parse(string.Format("{0:yyyy-MM-dd} ", endDate) + times.EndTime.Replace("T", "") + ":00");
                                if (endDate.Hour + 1 > dateTime.Hour)
                                {
                                    endDate = DateTime.Parse(string.Format("{0:yyyy-MM-dd} ", endDate) + times.StartTime.Replace("T", "") + ":00");

                                    endDate = endDate.AddDays(1);
                                }
                                lines[lineID] = endDate;
                                oldMaterialID = MaterialID;
                                break;
                            }
                            else
                            {
                                distributionQty = oweQty;
                                endDate = DateTime.Parse(string.Format("{0:yyyy-MM-dd} ", endDate) + times.StartTime.Replace("T", "") + ":00");
                                totalExpectTime += times.TotalHours.GetValueOrDefault();
                                endDate = endDate.AddDays(1);
                            }

                        }
                        if (errorCount > 30)
                        {
                            msg = "连续30天都未找到车间日历，请确认是否已经配置";
                            result = false;
                        }
                    }
                    jObject["ExpectTime"] = string.Format("{0:G2}", totalExpectTime);
                    DateTime WorkShopEndDate = DateTime.Now.Date;
                    if (jObject.ContainsKey("WorkShopEndDate"))
                    {
                        DateTime.TryParse(jObject["WorkShopEndDate"].ToString(), out WorkShopEndDate);
                    }
                    DateTime EndDate;
                    DateTime.TryParse(jObject["EndDate"].ToString(), out EndDate);
                    string WorkOrderTypeName = "";
                    //初样WorkOrderTypeName
                    if (jObject.ContainsKey("WorkOrderTypeName"))
                    {
                        WorkOrderTypeName = jObject["WorkOrderTypeName"].ToString();
                    }
                    if (EndDate.Date > WorkShopEndDate.Date && AppInfo.ControlLineEndDate && WorkOrderTypeName != "初样生产订单")
                    {
                        result = false;
                        msg += jObject["OrderNo"].ToString() + "完成期大于主计划期";
                    }
                }
                // result = true;

                return JsonConvert.SerializeObject(new { data = jArray, result, msg });
            }
            catch (Exception ex)
            {
                msg = ex.Message;
                result = false;
                return JsonConvert.SerializeObject(new { data = "", result, msg });
            }



        }

        /// <summary>
        /// 生成日计划
        /// </summary>
        /// <returns></returns>
        public JsonResult SaveSchedulingV2()
        {
            bool result = true;
            string msg = "";

            try
            {



                JArray jArray = JsonConvert.DeserializeObject(BodyJson) as JArray;
                if (jArray == null || jArray.Count == 0)
                {
                    msg = "未接收到数据，请确认是否为JSON格式";
                    result = false;
                }
                else
                {


                    Entities.Configuration.ValidateOnSaveEnabled = false;

                    Dictionary<string, decimal> keyValuePairs = new Dictionary<string, decimal>();

                    string ids = "0";
                    foreach (JObject jObject in jArray)
                    {
                        ids += "," + jObject["ID"].ToString();

                    }




                    SqlConnection connection = new SqlConnection(SqlHelper.MSSQLConnectionString);
                    connection.Open();
                    //   using (SqlTransaction tran = connection.BeginTransaction())
                    {
                        try
                        {



                            foreach (JObject jObject in jArray)
                            {

                                DataTable dataTable = SqlHelper.ExecuteDataTable("SELECT * FROM V_APS_OrderDistribution WHERE ID IN(" + ids + ")");
                                string sql = "DECLARE @ProcessPlanID BIGINT;DECLARE @COUNT INT;";
                                DataRow[] dataRows = dataTable.Select("ID=" + jObject["ID"].ToString());
                                if (dataRows.Length == 0)
                                {
                                    result = false;
                                    msg = "数据库数据发生了变化，找不到该数据";
                                    break;
                                }

                                //判断是否超排
                                if (keyValuePairs.ContainsKey(jObject["ID"].ToString()) == false)
                                {//
                                    keyValuePairs.Add(jObject["ID"].ToString(), decimal.Parse(dataRows[0]["UnSchedulingQty"].ToString()));
                                }
                                decimal d = 0;
                                decimal.TryParse(jObject["DistributionQty"].ToString(), out d);
                                if (d > keyValuePairs[jObject["ID"].ToString()])
                                {
                                    msg = jObject["OrderNo"].ToString() + "可剩余分配数:" + dataRows[0]["UnSchedulingQty"].ToString();
                                    result = false;

                                }
                                else
                                {
                                    keyValuePairs[jObject["ID"].ToString()] -= d;
                                }
                                if (string.IsNullOrEmpty(jObject["EndDate"].ToString()))
                                {
                                    msg = jObject["OrderNo"].ToString() + "没有结束日期";
                                    result = false;
                                }
                                if (string.IsNullOrEmpty(jObject["WorkShopEndDate"].ToString()))
                                {
                                    msg = jObject["OrderNo"].ToString() + "没有计划结束日期";
                                    result = false;

                                }
                                DateTime d1 = DateTime.Parse(jObject["EndDate"].ToString());
                                DateTime d2 = DateTime.Parse(jObject["WorkShopEndDate"].ToString());
                                if (d1.Date > d2.Date && jObject["WorkOrderTypeID"].ToString() != "1001108140100002")
                                {
                                    msg = jObject["OrderNo"].ToString() + "结束日期不能大于计划结束，请与计划协调";
                                    result = false;
                                }
                                sql += string.Format(@"
                                set @ProcessPlanID=0;

                            
                                IF isnull(@ProcessPlanID,0)=0 
                                    BEGIN
                                        INSERT INTO [dbo].[APS_ProcessPlan]
                                       ([ProcessPartID]
                                       ,[MaterialID]
                                       ,[FirstPlanID]
                                       ,[OrderID]
                                       ,[ProcessGroupInfoID]
                                       ,[Capacity]
                                       ,[PlanQty]
                                       ,[HasQty]
                                  
                                       ,[StartDate]
                                       ,[EndDate]
                                       ,[WorkShopID]
                                       ,[LineID]
                                       ,[ProductionStatus]
                                       ,[Status]
                                       ,[CreatedBy]
                                       ,[CreatedByName]
                                 
                                       ,[CreatedOn]
                                       ,[ModifyedOn] 
                                       ,[Coefficient]
                                     
                                       ,[ProcessID]
                                       ,[STD]
                                       ,[TotalPeoples],Remark2)
                                       SELECT top 1 {13}
                                        ,A.MaterialID,A.FirstPlanID,A.OrderID,A.ProcessGroupInfoID,{4}
                                        ,{5},0,'{6}','{7}',B.ParentID,{8}--WorkShopID
                                        ,23,1,'{9}','{10}',GETDATE(),GETDATE(),1,A.ProcessID,NULL,b.TotalPeoples
,A2.Urgency
                                       FROM V_APS_OrderDistribution A
                                         inner join APS_ProcessPartPlan A2 ON A2.ProcessPartID={13}
										LEFT JOIN (
										SELECT SUM(PlanQty) AS P1,ProcessPartID,ProcessGroupInfoID
										FROM APS_ProcessPlan
										WHERE ProcessPartID={13}
										GROUP BY ProcessPartID,ProcessGroupInfoID
										) A3 ON A2.ProcessPartID=A3.ProcessPartID
										AND A3.ProcessGroupInfoID=A.ProcessGroupInfoID
                                        LEFT JOIN Dev_Organize B ON B.OrganizeID={8}
                                        WHERE A.ID={3}
		AND A2.PlanQty>=ISNULL(A3.P1,0)
                                    END

                                ", jObject["OrderID"], jObject["ProcessID"], jObject["MaterialID"]
                            , jObject["ID"], jObject["Capacity"], jObject["DistributionQty"], jObject["StartDate"]
                            , jObject["EndDate"], jObject["LineID"], dev_Account.Account, dev_Account.Name, jObject["WorkShopID"]
                            , jObject["ExpectTime"], jObject["ProcessPartID"]
                            );
                                if (result)
                                {
                                    SqlHelper.ExecuteNonQuery(SqlHelper.MSSQLConnectionString, CommandType.Text, sql + ";EXEC	  [dbo].[P_APS_DayPlanForDay] " + jObject["OrderID"] + ", '" + dev_Account.Account + "',NULL,NULL ");
                                    //tran.Commit();
                                    result = true;
                                    msg = "操作成功";
                                }
                            }




                        }
                        catch (Exception ex)
                        {
                            //tran.Rollback();
                            result = false;
                            msg = ex.Message;



                        }
                        finally
                        {

                        }
                    }
                    connection.Close();

                }

            }
            catch (Exception ex)
            {
                result = false;
                msg = ex.Message;
            }
            return FormResult(result, msg, null);
        }
