        public string GetBadReport3()
        {
            bool result = true;
            string msg = "";
            JObject jArray = null;
            DataTable dataTable = null;
            try
            {



                jArray = JsonConvert.DeserializeObject(BodyJson) as JObject;
                if (jArray != null)
                {
                    string MFGOrganizeName = jArray["MFGOrganizeName"].ToString();
                    string w1 = "", w2 = "", w3 = "";

                    JArray CreatedOn = jArray["CreatedOn"] as JArray;
                    if (CreatedOn != null)
                    {
                        string d1 = CreatedOn[0].ToString();
                        string d2 = CreatedOn[1].ToString();


                        if (!string.IsNullOrEmpty(d1))
                        {
                            w2 += " AND  a.CreatedOn>='" + d1 + "'";
                            w3 += " AND  a.ProducedDate>='" + d1 + "'";
                        }
                        if (!string.IsNullOrEmpty(d2))
                        {
                            w2 += "AND  a.CreatedOn<='" + d2 + "'";
                            w3 += "AND  a.ProducedDate<='" + d2 + "'";
                        }
                    }
                    if (!string.IsNullOrEmpty(MFGOrganizeName))
                    {
                        w1 = " and  D.OrganizeName LIKE '%" + StringHelper.ReplaceSQL(MFGOrganizeName) + "%'";

                    }
                    dataTable = SqlHelper.ExecuteDataTable(string.Format(@"SELECT A.OrganizeID AS WorkShopID,A.OrganizeName as WorkShopName
,isnull(B.BadQty,0) as BadQty
,isnull(C.ConfirmQty,0) as ConfirmQty
,D.OrganizeName
,cast(BadQty/isnull(ConfirmQty,1) as decimal(18,4)) AS BadRate
FROM   dev_organize A
left join(
select sum(a.BadQty) as BadQty,A.WorkShopID from  APS_AbnormalNoDetails a
where a.AbnormalStatus<>0 {0}
GROUP BY A.WorkShopID 
) B ON A.OrganizeID=B.WorkShopID
left join(
select SUM(a.ConfirmQty) AS ConfirmQty,B.ParentID WorkShopID from  APS_MaterialReportDetail a
INNER JOIN Dev_Organize B ON A.LineID=B.OrganizeID AND B.Remark2='Y'
where A.Status=25 {1}

GROUP BY B.ParentID
) C ON A.OrganizeID=C.WorkShopID
inner join Dev_Organize D ON A.ParentID=D.OrganizeID
WHERE  A.organizetypeid = 5 {2}
 ", w2, w3, w1));
                }


            }
            catch (Exception ex)
            {
                result = false;
                msg = ex.Message;
            }
            return JsonConvert.SerializeObject(new { msg = "", result = true, data = dataTable });

        }
