        /// <summary>
        /// 数据解析
        /// </summary>
        /// <returns></returns>
        public JsonResult Analysis()
        {
            bool result = true;
            string msg = "";
            JArray jArray = null;
            try
            {



                jArray = JsonConvert.DeserializeObject(BodyJson) as JArray;
                if (jArray == null || jArray.Count == 0)
                {
                    msg = "未接收到数据，请确认是否为JSON格式";
                    result = false;
                }
                else
                {


                    Entities.Configuration.ValidateOnSaveEnabled = false;




                    string s = "0";
                    //foreach (JObject jObject in jArray)
                    //{

                    //    s += "," + jObject["SalesPlanID"].ToString();
                    //}


                    try
                    {
                        //找到料品
                        DataTable dataTable1 = SqlHelper.ExecuteDataTable(string.Format(@"
                                       
SELECT  Code,CustomerCode,MaterialID,Extend5,MaterialName
  FROM  [dbo].[APS_Material]

                            ", ""));

                        foreach (JObject jObject in jArray)
                        {
                            //long SalesPlanID = 0;
                            //long.TryParse(jObject["SalesPlanID"].ToString(), out SalesPlanID);

                            decimal planQty = 0;
                            DateTime planDay = DateTime.Now;
                            bool isDate = false;
                            if (!string.IsNullOrEmpty(jObject["PlanDay"].ToString()))
                            {
                                isDate = DateTime.TryParse(jObject["PlanDay"].ToString(), out planDay);
                            }

                            if (!string.IsNullOrEmpty(jObject["PlanQty"].ToString()))
                            {
                                decimal.TryParse(jObject["PlanQty"].ToString(), out planQty);
                                // planQty = decimal.Parse(jObject["PlanQty"].ToString());
                            }
                            if (planDay.Date <= DateTime.Now.AddDays(1).Date)
                            {
                                planDay = DateTime.Now.AddDays(1).Date;
                            }
                            planDay = planDay.Date;
                            string code = jObject["Code"].ToString();
                            if (!string.IsNullOrEmpty(code))
                            {


                                if (isDate)
                                {

                                    DataRow[] dataRows = dataTable1.Select("CustomerCode='" + code + "'");
                                    if (dataRows.Length == 0)
                                    {
                                        jObject["Remark1"] = code + "未找到本公司料号";
                                        dataRows = dataTable1.Select("Code='" + code + "'");
                                        if (dataRows.Length == 0)
                                        {
                                            jObject["Remark1"] = code + "找不到任何关联数据";
                                        }
                                        else
                                        {
                                            jObject["Remark1"] = "OK,匹配到本公司料号";
                                            jObject["MaterialName"] = dataRows[0]["MaterialName"].ToString();
                                            jObject["MaterialCode"] = dataRows[0]["Code"].ToString();
                                            jObject["MaterialID"] = dataRows[0]["MaterialID"].ToString();

                                        }

                                    }
                                    else if (dataRows.Length >= 1)
                                    {
                                        jObject["Remark1"] = code + "找到多个料号";

                                        s += "," + dataRows[0]["MaterialID"].ToString();
                                        string m = "0";
                                        foreach (DataRow dataRow in dataRows)
                                        {
                                            m += "," + dataRow["MaterialID"].ToString();
                                        }
                                        //jObject["MaterialID"] = dataRows[0]["MaterialID"].ToString();
                                        if (planQty > 0)
                                        {
                                            DataTable dataTable = SqlHelper.ExecuteDataTable(@"
                                              SELECT  top 1 A.QTY,A.StockInQty,
B.Code,B.CustomerCode,B.MaterialID,B.Extend5,B.MaterialName
                                              FROM [dbo].[APS_SalesOrderDetail](NOLOCK) A
INNER JOIN APS_Material B ON A.MaterialID=B.MaterialID 
                                            
                                             where A.MaterialID IN(" + m + ") and Qty > ISNULL(StockInQty,0)");
                                            if (dataTable.Rows.Count > 0)
                                            {
                                                jObject["MaterialName"] = dataTable.Rows[0]["MaterialName"].ToString();
                                                jObject["MaterialCode"] = dataTable.Rows[0]["Code"].ToString();
                                                jObject["MaterialID"] = dataTable.Rows[0]["MaterialID"].ToString();
                                                jObject["Remark1"] = "OK，公司料号：" + dataTable.Rows[0]["Code"].ToString();
                                            }
                                            else
                                            {
                                                jObject["Remark1"] = "错误,没有找到在制的销售单";
                                            }

                                        }
                                        else
                                        {
                                            jObject["Remark1"] = "没有数量或解析错误";
                                        }
                                    }
                                    else
                                    {
                                        s += "," + dataRows[0]["MaterialID"].ToString();
                                        jObject["MaterialID"] = dataRows[0]["MaterialID"].ToString();
                                        if (planQty > 0)
                                        {
                                            DataTable dataTable = SqlHelper.ExecuteDataTable(@"
                                              SELECT  top 1 QTY,StockInQty
                                              FROM[dbo].[APS_SalesOrderDetail](NOLOCK)
                                             where MaterialID=" + dataRows[0]["MaterialID"].ToString() + " and Qty > ISNULL(StockInQty,0)");
                                            if (dataTable.Rows.Count > 0)
                                            {
                                                jObject["MaterialName"] = dataRows[0]["MaterialName"].ToString();
                                                jObject["MaterialCode"] = dataRows[0]["Code"].ToString();
                                                jObject["MaterialID"] = dataRows[0]["MaterialID"].ToString();
                                                jObject["Remark1"] = "OK，公司料号：" + dataRows[0]["Code"].ToString();
                                            }
                                            else
                                            {
                                                jObject["Remark1"] = "错误,没有找到在制的销售单";
                                            }

                                        }
                                        else
                                        {
                                            jObject["Remark1"] = "没有数量或解析错误";
                                        }
                                    }



                                }
                                else
                                {
                                    jObject["Remark1"] = "日期格式不正确";
                                }
                            }

                        }

                        if (string.IsNullOrEmpty(msg))
                        {
                            msg = "分析完成";
                        }

                    }
                    catch (Exception ex)
                    {
                        result = false;
                        msg = ex.Message;



                    }
                    finally
                    {

                    }



                }

            }
            catch (Exception ex)
            {
                result = false;
                msg = ex.Message;
            }
            return new JsonResult() { Data = new { data = JsonConvert.SerializeObject(jArray), result, msg } };
        }

        /// <summary>
