        /// <summary>
        /// 导出的列
        /// </summary>
        Dictionary<string, string> lstExportColumn = new Dictionary<string, string>();

        private static bool IsInternalExportColumn(string columnName) =>
            columnName is "BColors" or "FColors" or "dicID" or "update" or "RowNumber"
                or "children" or "calendar" or "childrens" or "IsBackground";

        private static bool IsDynamicExportColumn(string columnName)
        {
            if (string.IsNullOrEmpty(columnName))
                return false;
            if (System.Text.RegularExpressions.Regex.IsMatch(columnName, @"^\d{4}-\d{2}-\d{2}$"))
                return true;
            if (System.Text.RegularExpressions.Regex.IsMatch(columnName, @"^\d{2}-\d{2}$"))
                return true;
            if (columnName.Length > 1
                && (columnName[0] == 'a' || columnName[0] == 'b' || columnName[0] == 'c')
                && char.IsDigit(columnName[1]))
                return true;
            return false;
        }

        private static string GetDynamicExportColumnLabel(string columnName, ElementTableOuput? colDef)
        {
            if (colDef != null && !string.IsNullOrEmpty(colDef.label))
                return colDef.label;
            if (DateTime.TryParseExact(columnName, "yyyy-MM-dd", CultureInfo.InvariantCulture, DateTimeStyles.None, out var fullDate))
                return fullDate.ToString("MM月dd日");
            if (DateTime.TryParseExact(columnName, "MM-dd", CultureInfo.InvariantCulture, DateTimeStyles.None, out var monthDay))
                return monthDay.ToString("MM月dd日");
            return columnName;
        }

        private void TryRegisterExportColumn(DataTable dt, ElementTableOuput? col, string? parentLabel)
        {
            if (col == null || string.IsNullOrEmpty(col.prop) || !col.visible)
                return;
            if (IsInternalExportColumn(col.prop))
                return;
            decimal width = 0;
            decimal.TryParse(col.width, out width);
            if (width < 0)
                return;

            string key = dt.Columns.Contains(col.prop + "Text") ? col.prop + "Text" : col.prop;
            if (!dt.Columns.Contains(key) && !dt.Columns.Contains(col.prop))
                return;
            if (!dt.Columns.Contains(key))
                key = col.prop;

            string label = string.IsNullOrEmpty(parentLabel) ? col.label : parentLabel + col.label;
            if (string.IsNullOrEmpty(label))
                label = col.prop;
            if (!lstExportColumn.ContainsKey(key))
                lstExportColumn.Add(key, label);
        }

        /// <summary>按 ElementColumn 顺序补全导出列（28634 等 SetDt 动态表头）。</summary>
        private void MergeExportColumnsFromElementColumn(DataTable dt)
        {
            if (dt == null || ElementColumn == null)
                return;

            foreach (var group in ElementColumn)
            {
                foreach (var col in group)
                {
                    TryRegisterExportColumn(dt, col, null);
                    if (col.children == null)
                        continue;
                    foreach (var child in col.children)
                        TryRegisterExportColumn(dt, child, col.label);
                }
            }

            foreach (DataColumn dc in dt.Columns)
            {
                if (IsInternalExportColumn(dc.ColumnName))
                    continue;
                var key = dt.Columns.Contains(dc.ColumnName + "Text") ? dc.ColumnName + "Text" : dc.ColumnName;
                if (lstExportColumn.ContainsKey(key))
                    continue;
                if (!IsDynamicExportColumn(dc.ColumnName))
                    continue;
                lstExportColumn.Add(key, GetDynamicExportColumnLabel(dc.ColumnName, FindExportColumnDefinition(dc.ColumnName)));
            }
        }

        private ElementTableOuput? FindExportColumnDefinition(string prop)
        {
            if (ElementColumn == null || ElementColumn.Count == 0)
                return null;

            foreach (var group in ElementColumn)
            {
                var direct = group.FirstOrDefault(m => m.prop == prop);
                if (direct != null)
                    return direct;

                foreach (var parent in group)
                {
                    if (parent.children == null)
                        continue;
                    var child = parent.children.FirstOrDefault(m => m.prop == prop);
                    if (child != null)
                    {
                        child.label = parent.label + child.label;
                        return child;
                    }
                }
            }

            return null;
        }

        public virtual Microsoft.AspNetCore.Mvc.IActionResult APSDataExcel()
        {
            lstExportColumn.Clear();
            isDownload = true;
            ApplyApsDataExportHooks();
            string s = APSData();

            if (dtData == null)
                return View("Index");

            foreach (DataColumn dc in dtData.Columns)
            {
                if (IsInternalExportColumn(dc.ColumnName))
                    continue;

                string columnName = dc.ColumnName;

                if (dtData.Columns.Contains(columnName + "Text"))
                {//有转义的Text

                    columnName = columnName + "Text";

                }

                ElementTableOuput d = null;
                if (jObject != null && jObject.ContainsKey("DIsVisibleApp") && jObject["DIsVisibleApp"].ToString() == "1")
                {
                    d = FindExportColumnDefinition(dc.ColumnName);
                    if (d != null && d.IsVisibleApp != true)
                        d = null;

                }
                else
                {
                    d = FindExportColumnDefinition(dc.ColumnName);
                    if (d != null)
                    {
                        decimal width= 0;
                        decimal.TryParse(d.width, out width);
                        if (width < 0)
                        {
                            continue;
                        }
                    }
                }


                if (d != null&&d.visible)
                {
                    if (lstExportColumn.ContainsKey(columnName) == false)
                    {
                        lstExportColumn.Add(columnName, d.label);
                    }
                }
                else if (IsDynamicExportColumn(dc.ColumnName))
                {
                    if (lstExportColumn.ContainsKey(columnName) == false)
                        lstExportColumn.Add(columnName, GetDynamicExportColumnLabel(dc.ColumnName, d));
                }

            }
            MergeExportColumnsFromElementColumn(dtData);
            ExportExcel(dtData);
            return View("Index");
        }
        /// <summary>
        /// 导出
        /// </summary>
        /// <param name="dt"></param>
        public void ExportExcel(DataTable dt)
        {
            ExcelPackage.LicenseContext = LicenseContext.NonCommercial;
            //新建一个 Excel 工作簿
            ExcelPackage package = new ExcelPackage();

            // 添加一个 sheet 表
            ExcelWorksheet worksheet = package.Workbook.Worksheets.Add(dt.TableName);

            int rowIndex = 1;   // 起始行为 1
            int colIndex = 1;   // 起始列为 1

            {
                //设置列名
                int i = 0;
                foreach (var obj in lstExportColumn)
                {
                    worksheet.Cells[rowIndex, colIndex + i].Value = obj.Value;
                    
                    //自动调整列宽，也可以指定最小宽度和最大宽度
                    worksheet.Column(colIndex + i).AutoFit();
                    
                    i++;
                }
            }
            // 跳过第一列列名
            rowIndex++;




            //字体大小
            worksheet.Cells.Style.Font.Size = 12;

            //字体颜色
            worksheet.Cells.Style.Font.Color.SetColor(System.Drawing.Color.Black);

            //单元格背景样式，要设置背景颜色必须先设置背景样式
            worksheet.Cells.Style.Fill.PatternType = ExcelFillStyle.Solid;
            //单元格背景颜色
            worksheet.Cells.Style.Fill.BackgroundColor.SetColor(System.Drawing.Color.White);



            // 单独设置单元格四边框 Top、Bottom、Left、Right 的样式和颜色
            worksheet.Cells.Style.Border.Top.Style = ExcelBorderStyle.Thin;
            worksheet.Cells.Style.Border.Top.Color.SetColor(System.Drawing.Color.Black);
            worksheet.Cells.Style.Border.Left.Style = ExcelBorderStyle.Thin;
            worksheet.Cells.Style.Border.Left.Color.SetColor(System.Drawing.Color.Black);
            //设置单元格所有边框样式和颜色
            // worksheet.Cells.Style.Border.BorderAround(ExcelBorderStyle.Thin,System.Drawing.Color.Gray);

            //垂直居中
            worksheet.Cells.Style.VerticalAlignment = ExcelVerticalAlignment.Center;

            //水平居中
            worksheet.Cells.Style.HorizontalAlignment = ExcelHorizontalAlignment.Left;

            //单元格是否自动换行
            worksheet.Cells.Style.WrapText = false;

            //设置单元格格式为文本
            //  worksheet.Cells.Style.Numberformat.Format = "#,##0.00";

            //单元格自动适应大小
            worksheet.Cells.Style.ShrinkToFit = false;

            bool isColor = dt.Columns.Contains("BColors");

            //写入数据
            for (int i = 0; i < dt.Rows.Count; i++)
            {
                int j = 0;
                DataRow dr = dt.Rows[i];
                Dictionary<string, string> bColors = dr["BColors"] as Dictionary<string, string>;
                Dictionary<string, string> fColors = dr["FColors"] as Dictionary<string, string>;
                foreach (var obj in lstExportColumn)
                {



                  
                    var lookupKey = obj.Key.EndsWith("Text", StringComparison.Ordinal)
                        ? obj.Key[..^4]
                        : obj.Key;
                    var d = FindExportColumnDefinition(lookupKey);
                    var n = mSSQLCore.Dev_DictionaryFields.Where(m => m.ParameterName == lookupKey).FirstOrDefault();
                    


                    if (isColor && bColors!=null&& bColors.ContainsKey(obj.Key))
                    {
                        worksheet.Cells[rowIndex + i, colIndex + j].Style.Fill.BackgroundColor.SetColor(System.Drawing.ColorTranslator.FromHtml(bColors[obj.Key]));
                    }
                    if (isColor &&fColors!=null&& fColors.ContainsKey(obj.Key))
                    {
                        worksheet.Cells[rowIndex + i, colIndex + j].Style.Font.Color.SetColor(System.Drawing.ColorTranslator.FromHtml(fColors[obj.Key]));
                    }
                    if (n != null && !string.IsNullOrEmpty(n.ValidType))
                    {//有权限判断
                        if (dev_Account.RoleMap.Where(m => m.RoleID == n.ValidType).Count() == 0)
                        {
                            worksheet.Cells[rowIndex + i, colIndex + j].Value = "***";
                        }
                        else
                        {
                            worksheet.Cells[rowIndex + i, colIndex + j].Value = dr[obj.Key];
                        }

                    }
                    else
                    {
                        if (d != null)
                        {
                            if (!string.IsNullOrEmpty(d.formatter))
                            {
                                worksheet.Cells[rowIndex + i, colIndex + j].Style.Numberformat.Format = d.formatter;
                            }
                            if (!string.IsNullOrEmpty(d.formater))
                            {
