        public void ExportExcelOLD(DataTable dt)
        {
            //创建一个内存流
            MemoryStream ms = new MemoryStream();

            //以指定的字符编码向指定的流写入字符
            StreamWriter sw = new StreamWriter(ms, Encoding.GetEncoding("UTF-8"));

            //StringBuilder strbu = new StringBuilder();

            ////写入标题
            //for (int i = 0; i < dt.Columns.Count; i++)
            //{
            //    strbu.Append(dt.Columns[i].Caption.ToString() + "\t");
            //}
            ////加入换行字符串
            //strbu.Append(Environment.NewLine);

            ////写入内容
            //// for (int i = 0; i < dt.Rows.Count; i++)
            //foreach (DataRowView dr in dt.DefaultView)
            //{
            //    foreach (DataColumn dc in dt.Columns)
            //    {
            //        var d = ElementColumn[0].Where(m => m.prop == dc.ColumnName).FirstOrDefault();
            //        if(d!=null)
            //        {
            //            if (!string.IsNullOrEmpty(d.formater))
            //            {
            //                try
            //                {
            //                    strbu.Append( string.Format(d.formater, dr[dc.ColumnName]).ToString().Replace("\t", "").Replace("\n", "") + "\t");

            //                }
            //                catch (Exception ex)
            //                {
            //                    strbu.Append(dr[dc.ColumnName].ToString().Replace("\t", "").Replace("\n", "") + "\t");
            //                }
            //            }
            //            else 
            //            {
            //                if(d.DataType=="nvarchar"||d.DataType=="varchar")
            //                {
            //                    strbu.Append("" + dr[dc.ColumnName].ToString().Replace("\t", "").Replace("\n", "") + "\t");
            //                }
            //                else
            //                {
            //                    strbu.Append(dr[dc.ColumnName].ToString().Replace("\t", "").Replace("\n", "") + "\t");
            //                }

            //            }
            //        }
            //      else
            //            {
            //                strbu.Append("\'" + dr[dc.ColumnName].ToString().Replace("\t", "").Replace("\n", "") + "\t");
            //            }
            //    }
            //    strbu.Append(Environment.NewLine);
            //}

            foreach (DataColumn dc in dt.Columns)
            {
                dc.ColumnName = dc.Caption;
            }
            //实例化一个流
            StringWriter stringWrite = new StringWriter();

            //指定文本输出到流
            if (dt.Rows.Count > 0)
            {

                HtmlTextWriter htmlWrite = new HtmlTextWriter(stringWrite);

                DataGrid dg = new DataGrid();
                dg.DataSource = dt;
                dg.DataBind();

                dg.Attributes.Add("style", "vnd.ms-excel.numberformat:@");

