                        }
                        catch (Exception ex)
                        {
                            result = false;
                            msg = ex.Message;
                            tran.Rollback();


                        }
                        finally
                        {

                        }
                    }
                    connection.Close();
                }


            }
            catch (Exception ex)
            {
                result = false;
                msg = ex.Message;
            }
            return FormResult(result, msg, null);
        }
