        /// <summary>
        /// 五金日计划分配查询
        /// </summary>
        /// <returns></returns>
        public string WJDayPlan()
        {
            bool result = true;
            string msg = "";
            JsonResult jsonResult = new JsonResult();
            DataTable dtNew = null;
            try
            {



                JArray jArray = JsonConvert.DeserializeObject(BodyJson) as JArray;
                if (jArray == null || jArray.Count == 0)
                {
                    msg = "未接收到数据，请确认是否为JSON格式";
                    result = false;
                    jsonResult = FormResult(result, msg, null);
                }
                else
                {


                    Entities.Configuration.ValidateOnSaveEnabled = false;



                    // using (SqlTransaction tran = connection.BeginTransaction())
                    {
                        try
                        {

                            string extend9 = "'0'";
                            foreach (JObject jObject in jArray)
                            {
                                if (!string.IsNullOrEmpty(jObject["Extend9"].ToString()))
                                {

                                    extend9 += ",'" + jObject["Extend9"].ToString() + "'";
                                }
                            }


                            DataTable dataTable = SqlHelper.ExecuteDataTable(string.Format(@"
SELECT A.MaterialID,
       a.PlanQty,
       Isnull(A2.StockQty, 0) AS StockQty,
     
       0
                         AS OweQty,
       B1.Extend9,
       b1.MaterialName,
       0                      WIP,
       Getdate()              AS OweDay,
       0                      AS DistributionQty,
       B1.Extend9
       , 0 as TotalPlanQty
,CAST(GETDATE() AS DATE) AS PlanDay
       , 0 as TotalPlanQty
	   ,0 as LineID
	   ,N'' AS LineName
	   ,'N' AS IsSales
	   ,N'' AS CustomerName
	   ,0 AS Capacity
	   ,0 AS ExpectTime
       ,a.SalesPlanProcessPartMaterialID
FROM   [dbo].[APS_SalesPlanProcessPartMaterialDay] a
       INNER JOIN APS_Material B1
               ON A.MaterialID = B1.MaterialID
       LEFT JOIN(SELECT MaterialID,
                        Sum(StockQty) AS StockQty
                 FROM   WMS_Stock
                 GROUP  BY MaterialID) A2
              ON A.MaterialID = A2.MaterialID
WHERE  PlanDay >= Cast(Getdate() AS DATE) 
and B1.Extend9 IN(
{0}
)  ", extend9));
                            dtNew = dataTable.Clone();
                            //循环品类
                            foreach (JObject jObject in jArray)
                            {
                                if (!string.IsNullOrEmpty(jObject["Extend9"].ToString()))
                                {
                                    //  foreach (DataRow dr in dataTable.Select("Extend9='"+jObject["Extend9"].ToString()+"'").OrderBy(m=>m["OweQty"]))
                                    {
                                        //循环天
                                        int dayIndex = 0;
                                        DateTime day = DateTime.Now.Date;

                                        //分配数量
                                        decimal qty = 0;
                                        decimal allQty = 0;
                                        decimal.TryParse(jObject["Qty"].ToString(), out qty);
                                        bool r = true;
                                        while (allQty < qty && r)
                                        {
                                            for (dayIndex = 0; dayIndex < 20; dayIndex++)
                                            {
                                                foreach (DataRow dr in dataTable.Select("Extend9='" + jObject["Extend9"].ToString() + "' AND PlanDay='" + day + "'").OrderBy(m => m["OweQty"]))
                                                {
                                                    DataRow[] drs = dtNew.Select("MaterialID=" + dr["MaterialID"].ToString());
                                                    DataRow newRow = null;
                                                    if (drs.Length == 0)
                                                    {
                                                        newRow = dtNew.NewRow();
                                                        foreach (DataColumn dataColumn in dtNew.Columns)
                                                        {
                                                            newRow[dataColumn.ColumnName] = dr[dataColumn.ColumnName];
                                                        }
                                                        dtNew.Rows.Add(newRow);
                                                    }
                                                    else
                                                    {
                                                        newRow = drs[0];
                                                    }
                                                    decimal planQty = 0;
                                                    decimal.TryParse(dr["planQty"].ToString(), out planQty);
                                                    decimal stockQty = 0;
                                                    decimal.TryParse(newRow["StockQty"].ToString(), out stockQty);
                                                    ///所有的计划数
                                                    decimal TotalPlanQty = 0;
                                                    decimal.TryParse(newRow["TotalPlanQty"].ToString(), out TotalPlanQty);

                                                    TotalPlanQty = TotalPlanQty + planQty;
                                                    decimal oweQty = stockQty - TotalPlanQty;
                                                    if (oweQty < 0)
                                                    {//产生了欠数需要记录

                                                        allQty += Math.Abs(oweQty);
                                                    }


                                                    //更新总数量
                                                    newRow["TotalPlanQty"] = TotalPlanQty;
                                                    if (oweQty < 0)
                                                    {
                                                        newRow["OweQty"] = Math.Abs(oweQty);
                                                        newRow["DistributionQty"] = newRow["OweQty"];
                                                    }

                                                    day = day.AddDays(dayIndex);
                                                    if (allQty > qty)
                                                    {
                                                        break;
                                                    }
                                                }
                                                dayIndex++;
                                            }
                                            r = false;

                                        }
                                    }
                                }
                            }


                        }
                        catch (Exception ex)
                        {
                            result = false;
                            msg = ex.Message;
                            // tran.Rollback();
                            jsonResult = FormResult(result, msg, null);

                        }
                        finally
                        {

                        }
                    }


                }

            }
            catch (Exception ex)
            {
                result = false;
                msg = ex.Message;

            }
            string s = JsonConvert.SerializeObject(new
            {

                data = dtNew,//数据
                result//返回标记
                        ,
                msg//返回的信息

            });
            return s;
        }

