        /// <summary>
        /// 保存复期回复
        /// </summary>
        /// <returns></returns>
        public string UpdateStockQty()
        {
            bool result = true;
            string msg = "";
            JsonResult jsonResult = new JsonResult();
            try
            {





                Entities.Configuration.ValidateOnSaveEnabled = false;



                // using (SqlTransaction tran = connection.BeginTransaction())
                {
                    try
                    {

                        if (result)
                        {
                            //  tran.Commit();
                            SqlHelper.ExecuteNonQuery(SqlHelper.MSSQLConnectionString, CommandType.Text, @"
UPDATE A 
SET A.STOCKQTY=B.StockQty,A.OncheckQty=B.OncheckQty
,A.ONLOADQTY=C.ONLOADQTY
FROM APS_Renewal A
LEFT JOIN (
SELECT CODE1,SUM(StockQty) AS StockQty,SUM(OncheckQty) AS OncheckQty FROM WMS_Stock
GROUP BY CODE1
) B ON A.F7=B.Code1
LEFT JOIN
(
SELECT Code,SUM(POQty-ReceivedQty) AS ONLOADQTY
FROM APS_PO
WHERE  ISNULL(ReceivedQty,0)<POQty AND STATUS=1
GROUP BY Code
) C ON A.F7=C.Code
");

                        }
                        msg = "读取库存成功";


                    }
                    catch (Exception ex)
                    {
                        result = false;
                        msg = ex.Message;
                        // tran.Rollback();
                        jsonResult = FormResult(result, msg, null);

                    }
                    finally
                    {

                    }
                }




            }
            catch (Exception ex)
            {
                result = false;
                msg = ex.Message;
                jsonResult = FormResult(result, msg, null);
            }
            string s = JsonConvert.SerializeObject(new
            {


                result//返回标记
                   ,
                msg//返回的信息

            });
            return s;
        }
