        public string GetDayPlanReport()
        {

            bool result = true;
            string msg = "";
            StringBuilder stringBuilder = new StringBuilder();
            JsonResult jsonResult = new JsonResult();
            try
            {





                Entities.Configuration.ValidateOnSaveEnabled = false;




                DataSet ds = null;
                int dicID = 0;
                List<ElementTableOuput> elementTableOuputs = new List<ElementTableOuput>();

                List<SearchForm> searchFormsAll = new List<SearchForm>();
                List<List<SearchForm>> searchForms = new List<List<SearchForm>>();

                List<List<Jspreadsheet>> ExcelColumns = new List<List<Jspreadsheet>>();


                try
                {


                    JObject jObject = JsonConvert.DeserializeObject(BodyJson) as JObject;

                    if (jObject != null && jObject.ContainsKey("dicID") == true)
                    {
                        int.TryParse(jObject["dicID"].ToString(), out dicID);
                        MSSQLCore mSSQLCore = new MSSQLCore(dicID, jObject, "");
                        mSSQLCore.OrderBy = "WorkShopID,LineID";
                        ds = mSSQLCore.GetDs();
                        string planDay = "";
                        if (!string.IsNullOrEmpty(jObject["PlanDay"].ToString()))
                        {
                            planDay = string.Format(@"{0:MM月dd日}", DateTime.Parse(jObject["PlanDay"].ToString()));

                        }
                        string organizeID = jObject["MFGOrganizeID"].ToString();
                        string companyname = "";
                        if (!string.IsNullOrEmpty(organizeID))
                        {
                            long org = long.Parse(organizeID);
                            var o = Entities.Query<Dev_Organize>().Where(m => m.OrganizeID == org).FirstOrDefault();
                            if (o != null)
                            {
                                companyname = o.OrganizeName;
                            }
                        }
                        stringBuilder.Append(@"    <table class=""pure-table pure-table-bordered"" cellpadding=""0"" cellspacing=""0"">
     <thead>
        <h1 style=""margin-left:200px;""> " + companyname + planDay + @"-排产计划</h1>
     </thead>
  <tr style=""background: #17375E; color: #fff;"">
<td>序号</td><td >类型</td><td >线体</td><td>客户</td><td>型号</td> <td>排产数量</td><td>实际完成</td>
<td>达成率</td><td>备注</td>
</tr>");
                        string LineID = "";
                        List<WorkShopInfo> workShopInfos = new List<WorkShopInfo>();

                        foreach (DataRow dataRow2 in ds.Tables[0].Rows)
                        {
                            WorkShopInfo workShopInfo = workShopInfos.Where(m => m.WorkShopID == dataRow2["WorkShopID"].ToString()).FirstOrDefault();
                            if (workShopInfo == null)
                            {
                                workShopInfo = new WorkShopInfo();
                                workShopInfo.ColSpan = 2;
                                workShopInfo.WorkShopID = dataRow2["WorkShopID"].ToString();
                                workShopInfo.Lines = new List<WorkShopInfo.Line>();

                                workShopInfos.Add(workShopInfo);
                            }
                            DataRow[] dataRows = ds.Tables[0].Select("WorkShopID=" + workShopInfo.WorkShopID + "");
                            workShopInfo.RowSpan = dataRows.Length;
                            foreach (DataRow dataRow in dataRows)
                            {
                                WorkShopInfo.Line line = workShopInfo.Lines.Where(m => dataRow["LineID"].ToString() == m.LineID).FirstOrDefault();

                                if (line == null)
                                {
                                    line = new WorkShopInfo.Line();
                                    workShopInfo.Lines.Add(line);
                                    line.LineID = dataRow["LineID"].ToString();
                                }
                                DataRow[] dataRowsLine = ds.Tables[0].Select("LineID=" + line.LineID);
                                line.RowSpan = dataRowsLine.Length;

                            }
                        }

                        foreach (var obj in workShopInfos)
                        {
                            int rowNumber = 1;

                            foreach (var line in obj.Lines)
                            {

                            }
                            DataRow[] dataRows = ds.Tables[0].Select("WorkShopID=" + obj.WorkShopID + "");
                            // stringBuilder.Append(@"<td   >" + dataRows[0]["ProcessName"] + "</td>");
                            //foreach (var line in obj.Lines)
                            //{
                            //    stringBuilder.Append(@"<td rowspan="""+line.RowSpan+@""">" + dataRows[0]["LineName"] + "</td>");

                            //}
                            bool isRowSpan = false;
                            decimal d1 = 0, d2 = 0;
                            decimal d3 = 0, d4 = 0;
                            foreach (DataRow dataRow in dataRows)
                            {
                                stringBuilder.Append("<tr><td>" + rowNumber + "</td>");
                                rowNumber++;
                                if (isRowSpan == false)
                                {
                                    stringBuilder.Append(@"<td rowspan=""" + obj.RowSpan + @""" valign=""middle"" align=""center"">" + dataRow["WorkShopName"] + "</td>");
                                    isRowSpan = true;
                                }
                                if (LineID != dataRow["LineID"].ToString())
                                {
                                    LineID = dataRow["LineID"].ToString();
                                    var l = obj.Lines.Where(m => m.LineID == LineID).FirstOrDefault();
                                    stringBuilder.Append(@"<td rowspan=""" + l.RowSpan + @"""  valign=""middle"" align=""center"">" + dataRow["LineName"] + "</td>");

                                }

                                stringBuilder.Append(@"<td>" + dataRow["Extend5"] + "</td>");
                                stringBuilder.Append(@"<td>" + dataRow["MaterialName"] + "</td>");
                                // stringBuilder.Append(string.Format(@"<td>{0:yyyy-MM-dd}</td>", dataRow["PlanDay"]));
                                stringBuilder.Append(string.Format(@"<td>{0:0.##########}</td>", dataRow["PlanQty"]));
                                stringBuilder.Append(string.Format(@"<td>{0:0.##########}</td>", dataRow["ConfirmQty"]));
                                stringBuilder.Append(@"<td>" + dataRow["PlanQtyP"] + "</td>");
                                stringBuilder.Append(@"<td>" + dataRow["LineName"] + "</td></tr>");
                                d3++;

                                decimal d5 = 0, d6 = 0;
                                if (!string.IsNullOrEmpty(dataRow["PlanQty"].ToString()))
                                {

                                    d5 = decimal.Parse(dataRow["PlanQty"].ToString());
                                    d1 += d5;

                                }
                                decimal confirmQty = 0;
                                decimal.TryParse(dataRow["ConfirmQty"].ToString(), out confirmQty);
                                if (confirmQty > 0)
                                {

                                    d6 = decimal.Parse(dataRow["ConfirmQty"].ToString());
                                    d2 += d6;
                                    if (d6 >= d5)
                                    {
                                        d4 += 1;
                                    }

                                }

                            }
                            stringBuilder.Append(@"<tr  style=""background-color:#94CE56""><td colspan=""5"">产出汇总表：</td>");
                            stringBuilder.Append(string.Format(@"<td>{0:0.##########}</td>", d1));
                            stringBuilder.Append(string.Format(@"<td>{0:0.##########}</td>", d2));
                            if (d1 > 0)
                            {
                                stringBuilder.Append(string.Format(@"<td>{0:P2}</td>", d2 / d1));
                            }
                            else
                            {
                                stringBuilder.Append(string.Format(@"<td>{0:P2}</td>", d2 / 1));
                            }

                            stringBuilder.Append(@"<td></td></tr>");
                            stringBuilder.Append(@"<tr  style=""background-color:#94CE56""><td colspan=""5"">计划完成率：</td>");
                            stringBuilder.Append(string.Format(@"<td>{0:0.##########}</td>", d3));
                            stringBuilder.Append(string.Format(@"<td>{0:0.##########}</td>", d4));
                            stringBuilder.Append(string.Format(@"<td>{0:P2}</td>", d4 / d3));

                            stringBuilder.Append(@"<td></td></tr>");
                        }

                        stringBuilder.Append("</table>");
                        msg = "读取库存成功";
                    }
                    else
                    {
                        result = false;
                    }

                }
                catch (Exception ex)
                {
                    result = false;
                    msg = ex.Message;
                    // tran.Rollback();
                    jsonResult = FormResult(result, msg, null);

                }
                finally
                {

                }





            }
            catch (Exception ex)
            {
                result = false;
                msg = ex.Message;

            }
            string s = JsonConvert.SerializeObject(new
            {


                result//返回标记
                   ,
                msg//返回的信息
                ,
                content = stringBuilder.ToString()

            });
            return s;
        }

