        public string UpdateProcess()
        {
            bool result = false;
            string msg = "";
            JsonResult jsonResult = new JsonResult();
            try
            {



                JObject jObject = JsonConvert.DeserializeObject(BodyJson) as JObject;
                if (jObject == null)
                {
                    msg = "未接收到数据，请确认是否为JSON格式";
                    result = false;
                    jsonResult = FormResult(result, msg, null);
                }
                else
                {
                    result = true;
                    int materialID = 0; string processGroupID = ""; string OrderID = ""; string updateOrder = "";
                    if (jObject.ContainsKey("materialID"))
                    {
                        materialID = int.Parse(jObject["materialID"].ToString());
                    }
                    else
                    {
                        result = false;
                        msg = "未接收到产品";
                    }
                    if (jObject.ContainsKey("processGroupID"))
                    {
                        processGroupID = jObject["processGroupID"].ToString();
                    }
                    else
                    {
                        result = false;
                        msg = "未接收到工艺";
                    }
                    if (dev_Account == null)
                    {
                        result = false;
                        msg = "未登录的非法操作";
                    }
                    if (result)
                    {


                        SqlParameter[] sqlParameters = new SqlParameter[6];
                        sqlParameters[0] = new SqlParameter("@MaterialID", materialID);
                        sqlParameters[1] = new SqlParameter("@ProcessGroupID", processGroupID);
                        sqlParameters[2] = new SqlParameter("@Account", dev_Account.Account);
                        sqlParameters[3] = new SqlParameter("@Name", dev_Account.Name);
                        sqlParameters[4] = new SqlParameter("@Result", SqlDbType.Int);
                        sqlParameters[5] = new SqlParameter("@Msg", SqlDbType.NVarChar, 500);
                        sqlParameters[4].Direction = sqlParameters[5].Direction = ParameterDirection.Output;
                        if (updateOrder != "1")
                        {//没有工单，则保存产品工艺
                            SqlHelper.ExecuteNonQuery(SqlHelper.MSSQLConnectionString, "P_APS_UpdateProcessByMaterialID", sqlParameters);
                        }
                        else
                        {

                            SqlHelper.ExecuteNonQuery(SqlHelper.MSSQLConnectionString, CommandType.Text, string.Format(@"
                                 UPDATE  [dbo].[APS_Order]
                                SET ProcessGroupID='{0}'
                                WHERE OrderID={1}

                                INSERT INTO [dbo].[APS_ProcessGroupMaterial]
           ([ProcessGroupMaterialID]
           ,[ProcessGroupID]
           ,[MaterialID]
 
 
           ,[CreatedOn]
 
           ,[Status]
         )
SELECT DISTINCT  'P'+CAST(A.MaterialID AS VARCHAR(10))+CAST(A.MaterialID AS VARCHAR(10))
,B.ProcessGroupID
,A.MaterialID,GETDATE(),1
FROM APS_Order A
INNER JOIN APS_ProcessGroup B ON A.ProcessGroupID=B.ProcessGroupID
LEFT JOIN APS_ProcessGroupMaterial C ON A.MaterialID=C.MaterialID
WHERE C.MaterialID IS NULL AND   A.OrderID={1}

  EXEC [P_aps_processmaterialadd]
        null
                                ", processGroupID, OrderID));
                        }

                        if (!string.IsNullOrEmpty(OrderID))
                        {
                            //有工单ID，已经排到日计划则提醒，否则删除
                            //                SqlHelper.ExecuteNonQuery(SqlHelper.MSSQLConnectionString, CommandType.Text, string.Format(@"

                            //DECLARE @COUNT INT;
                            //SELECT @COUNT=COUNT(1)
                            //FROM APS_DayPlan  where OrderID={0}
                            //IF(@COUNT>0)
                            //BEGIN
                            //--已经排到日计划,更新备注
                            //UPDATE APS_ProcessPartPlan
                            //SET ProductionStatus=85
                            // where OrderID={0}

                            //END
                            //ELSE
                            //BEGIN
                            //    delete from APS_ProcessPlan where OrderID={0}

                            //    delete from APS_DayPlan where OrderID={0}

                            //    delete from APS_ProcessPartPlan where OrderID={0}

                            //    delete from APS_DayProduction where OrderID={0}
                            //END


                            //                ", OrderID));
                            Entities.P_APS_OrderProcessAdd(long.Parse(OrderID)).ToString();
                        }
                    }
                }
            }
            catch (Exception ex)
            {

            }
            return JsonConvert.SerializeObject(new
            {

                result,
                msg
            });
        }

