                {

                    SqlHelper.ExecuteNonQuery(SqlHelper.MSSQLConnectionString, CommandType.Text, @"

		   INSERT INTO [dbo].[APS_ProcessMaterial]
           ([ProcessMaterial]
           ,[MaterialID]
           ,[ProcessID]
 
           ,[Capacity]
 
 
           ,[CreatedBy]
           ,[CreatedByName]
 
           ,[CreatedOn]
    
           ,[Status]
           ,[Remark1]
       
           ,[Efficiency]
,StandardPeoples
			 )
						 SELECT 
			 A.[ProcessMaterial]
           ,A.[MaterialID]
           ,A.[ProcessID]
 
           ,ROUND(A.[Capacity],0)
 
 
           ,A.[CreatedBy]
           ,A.[CreatedByName]
 
           ,A.[CreatedOn]
    
           ,A.[Status]
           ,A.[Remark1]
       
           ,A.[Efficiency]
		   ,A.StandardPeoples
			 FROM (
			 SELECT 
			 A.[ProcessMaterial]
           ,B.[MaterialID]
           ,C.[ProcessID]
 
           ,A.[Capacity]
 
 
           ,A.[CreatedBy]
           ,A.[CreatedByName]
 
           ,A.[CreatedOn]
    
           ,A.[Status]
           ,A.[Remark1]
       
           ,A.[Efficiency]
		   ,a.StandardPeoples
		   ,ROW_NUMBER() OVER(PARTITION BY B.Code,A.ProcessID order by A.createdon desc) as r
			 FROM APS_ProcessMaterialiMPORT A
			 inner join APS_Material B ON A.Remark1=B.Code
			 INNER join APS_Process C ON A.ProcessID=C.ProcessName
			 ) a
			 left JOIN APS_ProcessMaterial B ON A.MaterialID=B.MaterialID
			 AND A.ProcessID=B.ProcessID
			 where r=1 and b.ProcessID is null
		 
		 
			 update 
			 B SET B.Capacity=ROUND(A.[Capacity],0)
,B.StandardPeoples=A.StandardPeoples
			 FROM APS_ProcessMaterialiMPORT A
			 inner join APS_ProcessMaterial B ON A.MATERIALID=B.MaterialID AND A.Capacity>0
			 		 INNER join APS_Process C ON A.ProcessID=C.ProcessName
			 
");




                }





