        public string GetGantt()
        {
            APSData();
            bool result = false;
            string msg = allMsg;
            List<object> listResult = new List<object>();
            if (dtData != null)
            {
                dtData.Columns.Add("calendar", typeof(List<string>));
                DataTable dtCal = SqlHelper.ExecuteDataTable(@"SELECT OrganizeID,WorkingDate FROM  [dbo].[V_APS_OrganizeWorkingTimesDetail]
WHERE WorkingDate >= cast(getdate() as date)
and WorkingDate <= GETDATE() + 60");

                int index = 0;
                List<string> strings1 = new List<string>();

                foreach (DataRow dataRow in dtData.Rows)
                {
                    if (strings1.Contains(dataRow["LineID"].ToString()) == false && !string.IsNullOrEmpty(dataRow["LineID"].ToString()))
                    {
                        strings1.Add(dataRow["LineID"].ToString());
                    }
                }
                foreach (string lineID in strings1)
                {
                    index++;
                    DataRow[] dataRows = dtData.Select("LineID=" + lineID);
                    List<string> strings = new List<string>();
                    for (int i = 0; i < 60; i++)
                    {
                        if (dtCal.Select("OrganizeID=" + lineID + " and WorkingDate='" + DateTime.Now.AddDays(i).Date + "'").Length == 0)
                        {
                            strings.Add(string.Format("{0:yyyy-MM-dd}", DateTime.Now.AddDays(i)));
                        }

                    }
                    listResult.Add(new
                    {

                        RowNumber = index
                        ,
                        LineName = dataRows[0]["LineName"].ToString()
                          ,
                        LineID = lineID
                         ,
                        id = index
                        ,
                        OrderNoList = dataRows.CopyToDataTable()
                        ,
                        calendar = strings
                    }); ;



                }
                result = true;
                msg = "读取成功";
            }
            string s = JsonConvert.SerializeObject(new
            {


                result//返回标记
    ,
                msg//返回的信息
         ,
                data = listResult

            });
            return s;

        }

