        public string GetEASTReport()
        {

            DataSet dataSet = null;
            bool result = false;
            string msg = "";

            try
            {
                dataSet = SqlHelper.ExecuteDataset(@"

--0
SELECT C.OrganizeName AS N1,SUM(A.HasQty)/SUM(A.PlanQty) AS P1
FROM APS_DayPlan A
inner join APS_ProcessPlan A2 ON A.ProcessPlanID=A2.ProcessPlanID AND A2.Status=1
INNER JOIN Dev_Organize B ON A.LineID=B.OrganizeID  and b.SchedulingDays>0
INNER JOIN Dev_Organize C ON A.WorkShopID=C.OrganizeID
INNER JOIN APS_Order DX ON A2.OrderID=DX.OrderID AND DX.WorkOrderTypeID<>'ZP03'
WHERE A.PlanDay=CAST(GETDATE() AS DATE)
GROUP BY C.OrganizeName,c.OrganizeID
order by c.OrganizeID   desc

--1

SELECT B.OrganizeName AS N1
,COUNT(DISTINCT A.OrderID) AS C1
,SUM(CASE WHEN A.HasQty>0 THEN 1 ELSE 0 END) AS C2,
SUM(A2.PlanQty) AS S1,SUM(A2.HasQty) AS S2

FROM APS_DayPlan A
inner join APS_ProcessPlan A2 ON A.ProcessPlanID=A2.ProcessPlanID AND A2.Status=1
INNER JOIN Dev_Organize B ON A.LineID=B.OrganizeID  and b.SchedulingDays>0
INNER JOIN Dev_Organize C ON A.WorkShopID=C.OrganizeID
INNER JOIN APS_Order DX ON A2.OrderID=DX.OrderID AND DX.WorkOrderTypeID<>'ZP03'
WHERE A.PlanDay=CAST(GETDATE() AS DATE)
GROUP BY B.OrganizeName,a.WorkShopID
order by a.WorkShopID,b.OrganizeName

--2
SELECT CAST(B.ERPStartDate AS DATE) AS   N1 ,COUNT(1) AS C1
,COUNT(DISTINCT B.MaterialID) AS C2
FROM APS_ProcessMaterial A
INNER JOIN APS_Order B ON A.MaterialID=B.MaterialID AND B.CompletionDate IS NULL  AND B.Status=1   AND B.MFGOrganizeID in(160,162)
AND B.WorkOrderTypeID<>'ZP03'
INNER JOIN APS_ProcessGroup C ON B.ProcessGroupID=C.ProcessGroupID
INNER JOIN APS_ProcessGroupInfo D ON C.ProcessGroupID=D.ProcessGroupID
 
AND D.IsScheduling=1
WHERE ISNULL(A.Capacity,0)=0 AND B.ERPStartDate>=GETDATE()
AND B.ERPStartDate<=GETDATE()+15
GROUP BY CAST(B.ERPStartDate AS DATE)


--3

SELECT SUM(A.PlanQty) as S1,SUM(A.HasQty) AS S2,SUM(A.HasQty)/SUM(A2.PlanQty) AS P1
FROM APS_DayPlan A
inner join APS_ProcessPlan A2 ON A.ProcessPlanID=A2.ProcessPlanID AND A2.Status=1
INNER JOIN Dev_Organize B ON A.LineID=B.OrganizeID  and b.SchedulingDays>0
INNER JOIN Dev_Organize C ON A.WorkShopID=C.OrganizeID
INNER JOIN APS_Order DX ON A2.OrderID=DX.OrderID AND DX.WorkOrderTypeID<>'ZP03'
WHERE A.PlanDay=CAST(GETDATE() AS DATE)
 
 --4

 SELECT SUM(CASE WHEN A.HasQty>0 THEN 1 ELSE 0 END) AS S2
 ,COUNT(1) AS S1,SUM(CASE WHEN A.HasQty>0 THEN 1 ELSE 0.0 END)/COUNT(1.0) AS P1
FROM APS_DayPlan A
inner join APS_ProcessPlan A2 ON A.ProcessPlanID=A2.ProcessPlanID AND A2.Status=1
INNER JOIN Dev_Organize B ON A.LineID=B.OrganizeID  and b.SchedulingDays>0
INNER JOIN Dev_Organize C ON A.WorkShopID=C.OrganizeID
INNER JOIN APS_Order DX ON A2.OrderID=DX.OrderID AND DX.WorkOrderTypeID<>'ZP03'
WHERE A.PlanDay=CAST(GETDATE() AS DATE)

--5
SELECT SUM(A.PlanQty) as S1,SUM(A.HasQty) AS S2,SUM(A.HasQty)/SUM(A2.PlanQty) AS P1
FROM APS_DayPlan A
inner join APS_ProcessPlan A2 ON A.ProcessPlanID=A2.ProcessPlanID AND A2.Status=1
INNER JOIN Dev_Organize B ON A.LineID=B.OrganizeID and b.SchedulingDays>0
INNER JOIN Dev_Organize C ON A.WorkShopID=C.OrganizeID
INNER JOIN APS_Order DX ON A2.OrderID=DX.OrderID AND DX.WorkOrderTypeID<>'ZP03'
WHERE A.PlanDay=CAST(GETDATE() AS DATE)

--6
SELECT COUNT(1) AS C1,SUM(CASE WHEN ERPStartDate<=CAST(GETDATE() AS DATE) THEN 1 ELSE 0.0 END )/COUNT(1) AS P1
FROM APS_Order A
WHERE CompletionDate IS NULL AND A.Status=1   AND A.MFGOrganizeID in(160,162)
  AND A.OrderID NOT IN(
 SELECT OrderID FROM APS_ProcessPlan
  where Status=1
 )
and a.WorkOrderTypeID in(
 'ZP01',
'ZP02'
 )

 --7
 SELECT 
 SUM(A.PlanQty) AS S1,
 sum(a.HasQty)/SUM(A.PlanQty) as P1 
 ,A.PlanDay AS N1
 ,SUM(CASE WHEN A.HasQty>0 then 1 else 0.0 end)/COUNT(*) AS P2
FROM APS_DayPlan A
inner join APS_ProcessPlan A2 ON A.ProcessPlanID=A2.ProcessPlanID AND A2.Status=1
INNER JOIN Dev_Organize B ON A.LineID=B.OrganizeID  and b.SchedulingDays>0
INNER JOIN Dev_Organize C ON A.WorkShopID=C.OrganizeID
INNER JOIN APS_Order DX ON A2.OrderID=DX.OrderID AND DX.WorkOrderTypeID<>'ZP03'
WHERE A.PlanDay<CAST(GETDATE() AS DATE)
AND A.PlanDay>=CAST(GETDATE()-15 AS DATE)
GROUP BY A.PlanDay
ORDER BY A.PlanDay



SELECT COUNT(1) AS C1,A.ControlID AS N1
,SUM(CASE WHEN ERPStartDate<=CAST(GETDATE() AS DATE) THEN 1 ELSE 0 END ) AS C2
,FORMAT(SUM(CASE WHEN ERPStartDate<=CAST(GETDATE() AS DATE) THEN 1 ELSE 0.0 END )/COUNT(1),'P2') AS P1
FROM APS_Order A
 
WHERE CompletionDate IS NULL AND A.Status=1   AND A.MFGOrganizeID in(160,162)
 AND A.OrderID NOT IN(
 SELECT OrderID FROM APS_ProcessPlan
  where Status=1
 )
and a.WorkOrderTypeID in(
 'ZP01',
'ZP02'
 )
GROUP BY A.ControlID
order by SUM(CASE WHEN ERPStartDate<CAST(GETDATE() AS DATE) THEN 1 ELSE 0.0 END )/COUNT(1)

 /*
SELECT a.DSNAM as N1, 
               Min(ReceivedQty) AS C2,
			    Min(POQty) AS C3,
               count(*)        AS C1
        FROM   ERP_ZPPT036 A
               INNER JOIN APS_PO B
                       ON A.DEL12 = B.PODocNo
                          AND '0' + B.POLineNo = A.DELPS
        WHERE  A.ELE_MRP IN( '采购订单未交量', '已确认采购申请' )
               AND A.BDTER2 < Cast(Getdate() + 3 AS DATE)
        GROUP  BY a.DSNAM
		order by COUNT(*)
*/

SELECT Isnull(d.Remark2, '未分配') AS N1,
       Count(*)                 AS C1
FROM   APS_DayPlan A
       INNER JOIN APS_ProcessPlan C
               ON A.ProcessPlanID = C.ProcessPlanID
       INNER JOIN APS_OrderBOM B
