WHERE  A.PlanDay >= Cast(Getdate() AS DATE)
       AND A.PlanDay < Cast(Getdate() + 3 AS DATE)

GROUP  BY d.Remark2
ORDER  BY Count(*)
SELECT TOP 50
B.Code AS N1,A.ReceiptQty AS Q1 
,A.Remark2 AS N2
,FORMAT(A.CreatedOn,'HH:mm:ss') AS T1
FROM WMS_ReceiptDetail A
INNER JOIN APS_Material B ON A.MaterialID=B.MaterialID
ORDER BY A.CreatedOn DESC

 
");
                result = true;
            }
            catch (Exception ex)
