        /// <summary>
        /// EAST日计划更新开拉期
        /// </summary>
        /// <returns></returns>
        public string UpdateERPInfo()
        {
            bool result = false;
            string msg = "";

            try
            {



                jArray = JsonConvert.DeserializeObject(BodyJson) as JArray;
                if (jArray == null)
                {
                    msg = "未接收到数据，请确认是否为JSON格式";
                    result = false;

                }
                else if (dev_Account == null)
                {
                    msg = "当前登录信息已经丢失，请刷新页面重新登录";
                    result = false;
                }
                else
                {

                    EasyManufacture.Infrastructure.SystemInterface.EAST.SAP sAP = new SystemInterface.EAST.SAP();
                    foreach (JObject jObject in jArray)
                    {
                        if (!string.IsNullOrEmpty(jObject["OrderNo"].ToString()))
                        {
                            if (jObject["Extend11"].ToString().ToUpper().Contains("CRTD"))
                            {
                                if (jObject["Extend8"].ToString() != "已同步")
                                {
                                    result = sAP.UpdateOrder(jObject["OrderNo"].ToString(), jObject["LineErpCode"].ToString(), jObject["StartDate"].ToString(), jObject["EndDate"].ToString(), ref msg, "X", jObject["ControlID"].ToString());
                                    allMsg += jObject["OrderNo"].ToString() + msg;
                                }
                                else
                                {
                                    allMsg += jObject["OrderNo"].ToString() + "不可重复同步";
                                }
                            }
                            else
                            {
                                result = sAP.UpdateOrder(jObject["OrderNo"].ToString(), jObject["LineErpCode"].ToString(), jObject["StartDate"].ToString(), jObject["EndDate"].ToString(), ref msg, "", jObject["ControlID"].ToString());
                                //allMsg += jObject["OrderNo"].ToString() + "状态不是CRTD";
                                if (result)
                                {
                                    allMsg += jObject["OrderNo"].ToString() + msg;
                                }
                            }
                        }

                    }


                }
            }
            catch (Exception ex)
            {

            }


            return JsonConvert.SerializeObject(new
            {

                result,
                msg = allMsg,
                data = jArray
            });

        }
