        /// <summary>
        /// 读取供需平衡表
        /// </summary>
        /// <returns></returns>
        public string GetZAPSF001()
        {
            bool result = false;
            if (dev_Account == null)
            {
                allMsg = "请登录";
            }
            else
            {
                EasyManufacture.Infrastructure.SystemInterface.EAST.SAP sAP = new EasyManufacture.Infrastructure.SystemInterface.EAST.SAP();
                if (!string.IsNullOrEmpty(dev_Account.WorkFlowInstanceID))
                {


                    foreach (string s in dev_Account.WorkFlowInstanceID.Split(','))
                    {
                        if (!string.IsNullOrEmpty(s))
                        {
                            var r = sAP.GetZAPSF001(dev_Account.Extend2, s, dev_Account);
                            result = r.Result;
                            allMsg = r.message;
                        }

                    }
                }
                else
                {
                    allMsg = "请配置账号所属工厂";
                }

            }

            return JsonConvert.SerializeObject(new
            {

                result,
                msg = allMsg,
                data = jArray
            });
        }

        /// <summary>
        /// 计算日期
        /// </summary>
        /// <returns></returns>
        public string SchedulingV3()
        {
            bool result = false;
            string msg = "";

            try
            {



                jArray = JsonConvert.DeserializeObject(BodyJson) as JArray;
                if (jArray == null)
                {
                    msg = "未接收到数据，请确认是否为JSON格式";
                    result = false;

                }
                else if (dev_Account == null)
                {
                    msg = "当前登录信息已经丢失，请刷新页面重新登录";
                    result = false;
                }
                else
                {
                    int index = 1;
                    string orderIDs = "0";

                    foreach (JObject jObject in jArray)
                    {
                        long orderID = 0;
                        if (jObject.ContainsKey("OrderID") == false)
                        {
                            msg += "第" + index + "行没有工单号<br/>";
                            continue;
                        }
                        else
                        {
                            long.TryParse(jObject["OrderID"].ToString(), out orderID);

                        }
                        if (string.IsNullOrEmpty(jObject["ProcessGroupID"].ToString()))
                        {
                            msg += "第" + index + "行没有配置工艺<br/>";
                            continue;
                        }


                        orderIDs += "," + orderID;
                    }
                    StringBuilder stringBuilder = new StringBuilder();
                    if (orderIDs == "0")
                    {
                        msg = "未接收到数据，请检查";
                        result = false;

                    }
                    else
                    {
                        int count = 0;
                        SqlConnection connection = new SqlConnection(SqlHelper.MSSQLConnectionString);
                        connection.Open();
                        try
                        {
                            //   using (SqlTransaction tran = connection.BeginTransaction())

                            StringBuilder stringBuilder1 = new StringBuilder("truncate table APS_OrderPlanSheculing");

                            DateTime ReplyDate = DateTime.Now.Date;
                            if (!string.IsNullOrEmpty(jArray[0]["ReplyDate"].ToString()))
                            {
                                ReplyDate = DateTime.Parse(jArray[0]["ReplyDate"].ToString());
                            }
                            //读取日历，读出每条拉线的可用公式
                            DataSet ds1 = SqlHelper.ExecuteDataset(@"SELECT OrganizeID,WorkingDate,TotalHours,

CASE
                                  WHEN TotalHours - ISNULL(WorkHours,0) < 2 THEN 0
                                  ELSE TotalHours - ISNULL(WorkHours,0)
                                END AS RemainingHours
FROM V_APS_OrganizeWorkingTimesDetail A
LEFT JOIN(SELECT Sum(B1.PlanQty) / Min(B2.Capacity) AS WorkHours,
                               b3.LineID,
                               PlanDay
                        FROM   APS_DayPlan B1
                               INNER JOIN APS_ProcessPlan B3
                                       ON B1.ProcessPlanID = B3.ProcessPlanID
                               INNER JOIN APS_ProcessMaterial B2
                                       ON B1.MaterialID = B2.MaterialID
                                          AND B2.ProcessID = B3.ProcessID  and B2.Capacity>0
                        WHERE  PlanDay >= Cast(Getdate() AS DATE)
                        GROUP  BY b3.LineID,
                                  PlanDay) B
                     ON A.OrganizeID = B.LineID
                        AND A.WorkingDate = B.PlanDay
where WorkingDate>=CAST(GETDATE() AS DATE)
AND OrganizeID IN(
SELECT A.OrganizeID FROM APS_OrganizeProcessID A
)
AND WorkingDate>='" + ReplyDate.Date + @"' AND WorkingDate<CAST(GETDATE()+" + (GetSchedulingDays() - 1) + @" AS DATE)
ORDER BY WorkingDate

SELECT a.ProcessID,ProcessGroupID,b.ProcessName FROM APS_ProcessGroupInfo  a
inner join APS_Process b on a.ProcessID=b.ProcessID
WHERE IsScheduling=1  

SELECT ProcessID,A.OrganizeID,B.OrganizeName FROM APS_OrganizeProcessID A
INNER JOIN Dev_Organize B ON A.OrganizeID=B.OrganizeID

SELECT Capacity,MaterialID,ProcessID
FROM APS_ProcessMaterial

");


                            decimal capacity = 0;
                            foreach (JObject jObject in jArray)
                            {
                                if (jObject["isChecked"].ToString().ToLower() == "true")
                                {
                                    count++;
                                    bool isFindStartDate = false;
                                    DateTime endDate = ReplyDate;
                                    string ERPStartDate = jObject["ERPStartDate"].ToString();
                                    string MaterialID = jObject["MaterialID"].ToString();

                                    string ERPEndDate = jObject["ERPEndDate"].ToString();
                                    //工艺
                                    string processGroupID = jObject["ProcessGroupID"].ToString();

                                    string MaterialName = jObject["MaterialName"].ToString();

                                    string ControlID = jObject["ControlID"].ToString();
                                    //第一步，找到工艺需要排产的工序

                                    decimal qty = 0;
                                    decimal.TryParse(jObject["Qty"].ToString(), out qty);
                                    DataRow[] dataRows = ds1.Tables[1].Select("ProcessGroupID='" + processGroupID + "'");
                                    decimal ResourceHour = 0;//剩余小时，资源数
                                    if (dataRows.Length == 0)
                                    {
                                        jObject["ResourceCapacity"] = "找不到排产工序";
                                    }
                                    else
                                    {
                                        int resouceCount = 0;
                                        string processNames = "";
                                        decimal ExpectTime = 0;

                                        foreach (DataRow dr in dataRows)
                                        {//循环排产工序，找出相关的产能信息
                                            string ProcessID = dr["ProcessID"].ToString();
                                            string ProcessName = dr["ProcessName"].ToString();
                                            DataRow[] drCapacity = ds1.Tables[3].Select("ProcessID='" + ProcessID + "' AND MaterialID=" + MaterialID);
                                            if (drCapacity.Length == 0)
                                            {
                                                jObject["ResourceCapacity"] = ProcessName + "找不到产能";
                                            }
                                            else
                                            {
                                                decimal.TryParse(drCapacity[0]["Capacity"].ToString(), out capacity);
                                                jObject["Capacity"] = capacity;
                                                if (capacity <= 0)
                                                {
                                                    jObject["ResourceCapacity"] = ProcessName + "产能为0";
                                                }
                                                else
                                                {
                                                    jObject["ResourceCapacity"] = ProcessName + "产能为:" + string.Format("{0:0.##########}", capacity);
                                                }

                                            }
                                            DataRow[] drsLines = ds1.Tables[2].Select("ProcessID='" + ProcessID + "'");
                                            if (ControlID == "202")
                                            {//专线
                                             //                                  IF(@PlanQty < 5

                                                //   OR @MaterialName LIKE '%通讯设备%')
                                                // AND @ControlID = '202'
                                                //BEGIN
                                                //    SET @LineID = 1202
                                                //END
                                                if (MaterialName.Contains("通讯设备") || qty < 5)
                                                {
                                                    drsLines = ds1.Tables[2].Select("ProcessID='" + ProcessID + "' and OrganizeID=1202");
                                                    if (MaterialName.Contains("通讯设备"))
                                                    {
                                                        jObject["ResourceCapacity"] = "专线:" + drsLines[0]["OrganizeName"] + "(通讯设备)";
                                                    }
                                                    else
                                                    {
                                                        jObject["ResourceCapacity"] = "专线:" + drsLines[0]["OrganizeName"] + "(数量小于5)";
                                                    }

                                                    jObject["LinetID"] = drsLines[0]["OrganizeID"].ToString();
                                                }
                                            }

                                            resouceCount += drsLines.Length;
                                            processNames += processNames + "，";
                                            foreach (DataRow dataRow in drsLines)
                                            {
                                                decimal d = 0;
                                                string lineID = dataRow["OrganizeID"].ToString();
                                                string s = ds1.Tables[0].Compute("SUM(RemainingHours)", "OrganizeID=" + lineID + " AND RemainingHours>0  ").ToString();
                                                decimal.TryParse(s, out d);
                                                ResourceHour += d;
                                            }
                                            if (capacity > 0)
                                            {//如果产能大于0，找到匹配的拉线，扣减工时


                                                decimal tmpTime = qty / capacity;
                                                ExpectTime += tmpTime;

                                                while (tmpTime > 0)
                                                {
                                                    DateTime date = DateTime.Now.Date;

                                                    for (int i = 0; i < GetSchedulingDays(); i++)
                                                    {
                                                        date = DateTime.Now.Date.AddDays(i);
                                                        foreach (DataRow drLine in drsLines)
                                                        {

                                                            if (tmpTime <= 0)
                                                            {
                                                                break;
                                                            }
                                                            string lineID = drLine["OrganizeID"].ToString();
                                                            foreach (DataRow drWork in ds1.Tables[0].Select("OrganizeID=" + lineID + " AND RemainingHours>0 AND WorkingDate='" + date + "'", "WorkingDate "))
                                                            {
                                                                decimal d = 0;
                                                                decimal.TryParse(drWork["RemainingHours"].ToString(), out d);

                                                                if (d > 0)
                                                                {
                                                                    if (isFindStartDate == false)
                                                                    {
                                                                        ReplyDate = DateTime.Parse(drWork["WorkingDate"].ToString());
                                                                        endDate = ReplyDate;
                                                                        isFindStartDate = true;
                                                                    }

                                                                    decimal d2 = d - tmpTime;
                                                                    if (d > tmpTime)
                                                                    {
                                                                        drWork["RemainingHours"] = d - tmpTime;
                                                                        tmpTime = 0;
                                                                        break;
                                                                    }
                                                                    else
                                                                    {
                                                                        drWork["RemainingHours"] = 0;
                                                                        tmpTime = tmpTime - d;
                                                                    }
                                                                }
                                                                decimal.TryParse(drWork["RemainingHours"].ToString(), out d);

                                                            }
                                                        }
                                                        if (tmpTime <= 0)
                                                        {
                                                            break;
                                                        }
                                                        endDate = endDate.AddDays(1);
                                                    }
                                                    break;
                                                }
                                            }


                                        }
                                        jObject["ResourceCount"] = resouceCount;
                                        jObject["ProcessNames"] = processNames.Trim('，');
                                        jObject["ExpectTime"] = Math.Round(ExpectTime, 2);
                                        jObject["StartDate"] = ReplyDate;
                                        jObject["ResourceHour"] = string.Format("{0:0.##########}", Math.Round(ResourceHour, 1));
                                        jObject["EndDate"] = string.Format("{0:yyyy-MM-dd}", endDate);
                                    }


                                }

                            }

                            foreach (JObject jObject in jArray.Where(m => m["isChecked"].ToString().ToLower() == "true"))
                            {
                                decimal ExpectTime = 0;
                                string SalesOrderNo = jObject["SalesOrderNo"].ToString();

                                if (!string.IsNullOrEmpty(SalesOrderNo))
                                {
                                    foreach (JObject jObject2 in jArray.Where(m => m["SalesOrderNo"].ToString() == SalesOrderNo && m["isChecked"].ToString().ToLower() == "true"))
                                    {
                                        ExpectTime += decimal.Parse(jObject2["ExpectTime"].ToString() == "" ? "0" : jObject2["ExpectTime"].ToString());

                                    }
                                    jObject["AllExpectTime"] = ExpectTime;
                                }
                                else
                                {
                                    jObject["AllExpectTime"] = jObject["ExpectTime"];
                                }

                            }
                            if (count > 0)
                            {
                                result = true;
                                msg = "计算成功";
                                // jArray = new JArray(jArray.OrderBy(obj => obj["StartDate"]));
                            }
                            else
                            {
                                result = false;
                                msg = "未接收到数据，请确认是否选中";
                            }


                        }
                        catch (Exception ex)
                        {
                            result = false;
                            msg = ex.Message;

                        }
                        finally
                        {
                            connection.Close();
                        }

                        jArray = new JArray(jArray.OrderBy(obj => obj["LineID"]).ThenBy(obj => obj["StartDate"]));

                    }

                }
            }
            catch (Exception ex)
            {

            }


            return JsonConvert.SerializeObject(new
            {

                result,
                msg,
                data = jArray
            });

        }

        public string CalcHours()
        {
            bool result = true;
            string msg = "";

            try
            {
                JObject jObject = JsonConvert.DeserializeObject(BodyJson) as JObject;
                object d1 = DBNull.Value;
                object d2 = DBNull.Value;
                object d3 = DBNull.Value;
                object d4 = DBNull.Value;
                if (jObject["date2"] != null && jObject["date1"] is JArray)
                {
                    d1 = ((JArray)jObject["date1"])[0].ToString();
                    d2 = ((JArray)jObject["date1"])[1].ToString();
                }
                if (jObject["date2"] != null && jObject["date2"] is JArray)
                {
                    d3 = ((JArray)jObject["date2"])[0].ToString();
                    d4 = ((JArray)jObject["date2"])[1].ToString();
                }


                SqlParameter[] sqlParameters = new SqlParameter[4];
                sqlParameters[0] = new SqlParameter("@Date1", d1);//工单号 
                sqlParameters[1] = new SqlParameter("@Date2", d2);//工单号 
                sqlParameters[2] = new SqlParameter("@Date3", d3);//工单号 
                sqlParameters[3] = new SqlParameter("@Date4", d4);//工单号 
                SqlHelper.ExecuteNonQuery(SqlHelper.MSSQLConnectionString, "P_calchours", sqlParameters);
                msg = "计算成功";



            }
            catch (Exception ex)
            {
                result = false;
                msg = "更新失败,错误信息:" + ex.Message;
            }
            return JsonConvert.SerializeObject(new
            {

                result,
                msg
            }); ; ;
        }
