  INNER JOIN Dev_Supplier C ON A.SuplierCode=c.SupplierName

  UPDATE APS_DeliveryDataImport SET  SuplierCode=right('0000'+REPLACE(SuplierCode,' ',''),10)
UPDATE A SET  A.SuplierName=C.SupplierName
  FROM   APS_DeliveryDataImport a
   
  INNER JOIN Dev_Supplier C ON A.SuplierCode=C.Code
");

                        }

                        if (isAllOK)
