        /// <summary>
        /// 欠料获取库存等信息
        /// </summary>
        /// <returns></returns>
        public string GetOweInfo()
        {
            bool result = true;
            string msg = "";
            DataSet ds = null;
            JObject jArray = JsonConvert.DeserializeObject(BodyJson) as JObject;
            decimal stockQty = 0;
            decimal stockQty2 = 0;
            if (jArray == null)
            {
                msg = "未接收到数据，请确认是否为JSON格式";
                result = false;
            }
            else
            {

                ds = SqlHelper.ExecuteDataset(string.Format(@" 
SELECT SUM(StockQty) AS StockQty
FROM WMS_Stock
WHERE MaterialID={0}
union all 
SELECT SUM(AvailableQty)
FROM APS_MaterialReport
WHERE MaterialID={0}
 ", jArray["MaterialID"]));
                if (ds.Tables[0].Rows.Count > 0)
                {
                    decimal.TryParse(ds.Tables[0].Rows[0][0].ToString(), out stockQty);
                }

                if (ds.Tables[0].Rows.Count > 1)
                {
                    decimal.TryParse(ds.Tables[0].Rows[1][0].ToString(), out stockQty2);
                }


            }
            return JsonConvert.SerializeObject(new
            {

                result,
                msg,
                stockQty,
                stockQty2
            });
        }
