        /// <summary>
        ///更新送货日期
        /// </summary>
        /// <returns></returns>
        public ActionResult updatePOReplyDate()
        {
            bool result = true;
            string msg = "";
            DataSet ds = null;
            JArray jArray = JsonConvert.DeserializeObject(BodyJson) as JArray;
            if (jArray == null)
            {
                msg = "未接收到数据，请确认是否为JSON格式";
                result = false;
            }
            else
            {


                string sql = "";

                foreach (JObject obj in jArray)
                {
                    sql += string.Format(@"

                       UPDATE A
SET  A.ReplyDate='{0}',A.ReplyQty = {1}
FROM APS_PO A
WHERE  a.ReceivedQty < a.POQty AND MaterialID={2} and SupplierCode='{3}'"
 , obj["ReplyDate"], obj["ReplyQty"], obj["MaterialID"].ToString(), obj["SupplierCode"].ToString());
                }

                SqlConnection connection = new SqlConnection(SqlHelper.MSSQLConnectionString);
                connection.Open();

                using (SqlTransaction tran = connection.BeginTransaction())
                {
                    try
                    {
                        SqlHelper.ExecuteNonQuery(tran, CommandType.Text, sql);
                        tran.Commit();
                        msg = "操作成功";
                    }
                    catch (Exception ex)
                    {
                        tran.Rollback();
                        msg = ex.Message;
                        result = false;

                    }
                    finally
                    {
                        connection.Close();
                    }
                }


            }
            return FormResult(result, msg, "");

        }


