                                            {
                                                string ERPStartDate = jObject["ERPStartDate"].ToString();
                                                if (!string.IsNullOrEmpty(ERPStartDate))
                                                {
                                                    planDay = DateTime.Parse(ERPStartDate);
                                                }
                                                else
                                                {
                                                    string StartDate = jObject["StartDate"].ToString();
                                                    if (!string.IsNullOrEmpty(StartDate))
                                                    {
                                                        planDay = DateTime.Parse(StartDate);
                                                    }
                                                }
                                                if (planDay.Date < DateTime.Now.Date)
                                                {
                                                    planDay = DateTime.Now.Date;
                                                }
                                            }

                                            if (dataRow.Length == 0)
                                            {
                                                continue;
                                            }
                                            else
                                            {
                                                // dataRow[0]["RemainingHours"] = 11;
                                                jObject["Capacity"] = jObject["PlanQty"].ToString();
                                            }
                                            RemainingHours = 11;
                                        }



                                        decimal TotalHours = 0;
                                        decimal.TryParse(dataRow[0]["TotalHours"].ToString(), out TotalHours);
                                        // string ss = string.Format("{0:MM-dd}", DateTime.Now.AddDays(i), System.Globalization.CultureInfo.CurrentCulture.DateTimeFormat.GetDayName(DateTime.Now.AddDays(i).DayOfWeek).Replace("星期", ""));
                                        // if (jObject.ContainsKey(ss))
                                        {
                                            //日产能
                                            decimal DayCapacity = 0;
                                            //if (isPlan != "1")
                                            //{//周计划那里，有日产能
                                            //    decimal.TryParse(jObject["DayCapacity"].ToString(), out DayCapacity);
                                            //}
                                            //else
                                            {//日计划有小时产能
                                                decimal.TryParse(jObject["Capacity"].ToString(), out DayCapacity);
                                                DayCapacity = TotalHours * DayCapacity * Coefficient;
                                            }
                                            //当天可排或者需要排的数量
                                            decimal d = 0;
                                            d = Math.Ceiling(DayCapacity * (RemainingHours / TotalHours));
                                            if (d > qty)
                                            {
                                                d = qty;
                                            }
                                            decimal playQty = 0;
                                            playQty = Math.Min(qty, d);
                                            //if(i==0)
                                            //{//第一天，取当前天的数据
                                            //    DataRow[] dataRows = dtDayPlan.Select("ProcessPlanID=" + jObject["ProcessPlanID"].ToString()+" AND PlanDay='"+ planDay + "'");
                                            //    if(dataRows.Length>0)
                                            //    {
                                            //        decimal.TryParse(dataRows[0]["PlanQty"].ToString(), out playQty);
                                            //    }
                                            //}
                                            if (playQty > 0)
                                            {   //用时
                                                decimal useHour = playQty / DayCapacity * TotalHours;
                                                if (SchedulingType != "无限产能")
                                                {
                                                    dataRow[0]["RemainingHours"] = RemainingHours - useHour;
                                                }

                                                stringBuilder1.Append(string.Format(@"
INSERT INTO [dbo].[APS_DayPlan]
           ([OrderID]
           ,[MaterialID]
           ,[ProcessPlanID]
           ,[WorkShopID]
           ,[LineID]
           ,[PlanQty]
           ,[HasQty]
           ,[Status]
           ,[CreatedBy]
           ,[CreatedByName]
           ,[ModifiedBy]
           ,[ModifiedByName]
           ,[CreatedOn]
           ,[ModifyedOn]
           
           ,[PlanDay]
          
           )
		   select A.OrderID,A.MaterialID,A.ProcessPlanID,A.WorkShopID,A.LineID
		   ,{0},0,1,A.CreatedBy,A.CreatedByName,A.ModifiedBy,A.ModifiedByName,GETDATE(),GETDATE()
		   ,'{1}'
		   from APS_ProcessPlan A
		   where {2};
                                                ", playQty, planDay
                                                , isPlan == "1" ? "ProcessPlanID=" + jObject["ProcessPlanID"].ToString()
                                                : "ProcessPlanIDPre=" + jObject["ProcessPlanID"].ToString()
                                                ));


                                                qty -= playQty;
                                                if (qty <= 0)
                                                {
                                                    break;
                                                }
                                            }
                                            else
                                            {
                                                continue;
                                            }
                                        }
                                    }



                                }
                                if (count > 0)
                                {
                                    try
                                    {
                                        if (isPlan == "1")
                                        {
                                            stringBuilder1.Append(@"update A SET  A.StartDate=B.PlanDay,A.EndDate=B.EndDate
FROM APS_ProcessPlan A
 
inner JOIN 
(
SELECT 
ProcessPlanID,MIN(PlanDay) PlanDay
,MAX(PlanDay) as EndDate
FROM APS_DayPlan
WHERE PlanDay>=CAST(GETDATE() AS DATE)
GROUP BY ProcessPlanID
) B ON A.ProcessPlanID=B.ProcessPlanID
WHERE   A.ProcessPlanID IN (" + processPlanIDs + @") AND ISNULL(A.HasQty1,0)=0
 ");
                                        }
                                        SqlHelper.ExecuteNonQuery(tran, CommandType.Text, stringBuilder1.ToString());
                                        tran.Commit();
                                        result = true;
                                        msg = "操作成功";
                                        if (isPlan != "1")
                                        {
                                            jArray = new JArray(jArray.OrderBy(obj => obj["StartDate"]));
                                        }

                                    }
                                    catch (Exception ex)
                                    {
                                        result = false;
                                        msg = ex.Message;
                                        tran.Rollback();
                                    }
                                    finally
                                    {
                                        connection.Close();
                                    }

                                }
                                else
                                {
                                    result = false;
                                    msg = "未接收到数据，请确认是否选中";
                                }
                            }
                            if (!string.IsNullOrEmpty(wid))
                            {
                                SqlHelper.ExecuteNonQuery(" exec [P_aps_autodayandnight] null,null");
                            }

                        }
                        catch (Exception ex)
                        {
                            result = false;
                            msg = ex.Message;


                        }
                        finally
