                    {
                        msg = "未接收到数据，请检查";
                        result = false;

                    }
                    else
                    {
                        int count = 0;
                        //  SqlConnection connection = new SqlConnection(SqlHelper.MSSQLConnectionString);
                        //  connection.Open();
                        try
                        {
                            index = 0;
                            foreach (JObject jObject in jArray)
                            {
                                index++;
                                long orderID;
                                if (jObject.ContainsKey("OrderID") == false)
                                {
                                    msg += "第" + index + "行没有工单号<br/>";
                                    continue;
                                }
                                else
                                {
                                    long.TryParse(jObject["OrderID"].ToString(), out orderID);

                                }
                                if (orderID < 1)
                                {
                                    continue;
                                }
                                long WorkShopID = 0;
                                if (jObject.ContainsKey("WorkShopID"))
                                {
                                    long.TryParse(jObject["WorkShopID"].ToString(), out WorkShopID);
                                }
                                SqlParameter[] sqlParameters = new SqlParameter[6];
                                sqlParameters[0] = new SqlParameter("@OrderID", orderID);
                                sqlParameters[1] = new SqlParameter("@Account", dev_Account.Account);
                                sqlParameters[2] = new SqlParameter("@Name", dev_Account.Name);
                                sqlParameters[3] = new SqlParameter("@WorkShopID", WorkShopID);
                                sqlParameters[4] = new SqlParameter("@Result", SqlDbType.Bit);
                                sqlParameters[5] = new SqlParameter("@Msg", SqlDbType.NVarChar, 100);
                                sqlParameters[4].Direction = sqlParameters[5].Direction = ParameterDirection.Output;
                                SqlHelper.ExecuteNonQuery(SqlHelper.MSSQLConnectionString, "P_aps_toprocessplan", sqlParameters);
                                if ((bool)sqlParameters[4].Value != true)
                                {
                                    result = false;
                                    msg += "第" + index + "失败";
                                }

                            }
                            result = true;
                            msg = "操作成功";
                        }
                        catch (Exception ex)
                        {
                            result = false;
                            msg = ex.Message;


                        }
                        finally
                        {
                            //connection.Close();
                        }



                    }

                }
            }
            catch (Exception ex)
            {

            }


            return JsonConvert.SerializeObject(new
            {

                result,
                msg
            }); ; ;
        }
