        public void AutoPlan()
        {

            try
            {
                SqlHelper.ExecuteNonQuery(@" 

 


INSERT INTO [dbo].[APS_ProcessPlan]
           ([ProcessPartID]
           ,[MaterialID]
           ,[FirstPlanID]
           ,[OrderID]
           ,[ProcessGroupInfoID]
           ,[Capacity]
           ,[PlanQty]
           ,[HasQty]
           ,[ExpectTime]
           ,[StartDate]
           ,[EndDate]
           ,[WorkShopID]
