           ,[ModifyedOn]
           ,[Remark1]
           ,[Remark2]
           ,[Coefficient]
           ,[ViewSort]
           ,[ProcessID]
           ,[STD]
           ,[TotalPeoples]
         
           ,[ERPUpdateStatus]
           ,[HasQty1]
           ,[StartDate1]
           ,[Extend1]
		   ,ProcessPlanIDPre
,DataSource
		   )
   
   SELECT A.[ProcessPartID]
           ,A.[MaterialID]
           ,A.[FirstPlanID]
           ,A.[OrderID]
           ,C.[ProcessGroupInfoID]
           ,d3.[Capacity]
           ,A.[PlanQty]
           ,0
           ,A.[ExpectTime]
           ,A.[StartDate]+C.FixDay
           ,A.[EndDate]+C.FixDay
           ,D.WorkShopID
           ,D.OrganizeID
           ,A.[ProductionStatus]
           ,1
           ,A.[CreatedBy]
           ,A.[CreatedByName]
           ,A.[ModifiedBy]
           ,A.[ModifiedByName]
           ,A.[CreatedOn]
           ,A.[ModifyedOn]
           ,A.[Remark1]
           ,A.[Remark2]
           ,A.[Coefficient]
           ,A.[ViewSort]
           ,C.[ProcessID]
           ,A.[STD]
           ,A.[TotalPeoples]
 
           ,A.[ERPUpdateStatus]
           ,0
           ,A.[StartDate1]
           ,A.[Extend1]
		   ,A.ProcessPlanID
,a.DataSource
   FROM [APS_ProcessPlan] A
   INNER JOIN APS_Order B ON A.OrderID=B.OrderID
   INNER JOIN APS_ProcessGroupInfo C ON B.ProcessGroupID=C.ProcessGroupID  AND C.PostProcessID=A.ProcessID
   left join Dev_Organize c2 on a.LineID=c2.OrganizeID
   LEFT JOIN (
   SELECT ProcessID,OrganizeID,WorkShopID,COUNT(1) OVER(PARTITION BY ProcessID) AS C 
   ,Sailings
   FROM v_APS_OrganizeProcessID
   
   ) D ON C.ProcessID=D.ProcessID AND (D.C=1 or D.Sailings=C2.Sailings )
     LEFT JOIN APS_ProcessPlan D2 ON D2.ProcessGroupInfoID=C.ProcessGroupInfoID AND D2.OrderID=A.OrderID
   AND D2.Status=1  and ISNULL(a.DataSource,'')=ISNULL(d2.DataSource,'')
   LEFT JOIN APS_ProcessMaterial D3 ON A.MaterialID=D3.MaterialID AND D3.ProcessID=C.ProcessID and d.OrganizeID=d3.OrganizeID
   WHERE B.CompletionDate IS NULL and a.Status=1 
   AND D2.ProcessPlanID IS NULL

 
update d2 set   d2.LineID=x3.OrganizeID,d2.WorkShopID=x3.ParentID
,d2.planqty=a.planqty
    FROM [APS_ProcessPlan] A
 INNER JOIN APS_Order B ON A.OrderID=B.OrderID
 INNER JOIN APS_ProcessGroupInfo C ON B.ProcessGroupID=C.ProcessGroupID  AND C.PostProcessID=A.ProcessID
 
 inner JOIN APS_ProcessPlan D2 ON D2.ProcessID=C.ProcessID AND D2.OrderID=A.OrderID
 AND D2.Status=1 and ISNULL(a.DataSource,'')=ISNULL(d2.DataSource,'')
 INNER join Dev_Organize x2 on a.LineID=x2.OrganizeID
 INNER join Dev_Organize x3 on x2.Sailings=x3.Sailings and x3.OrganizeID<>x2.OrganizeID
 
 WHERE B.CompletionDate IS NULL and a.Status=1
 
 DELETE A2
    FROM [APS_ProcessPlan] A

   INNER JOIN APS_Order B ON A.OrderID=B.OrderID
   INNER JOIN APS_ProcessGroupInfo C ON B.ProcessGroupID=C.ProcessGroupID  AND C.PostProcessID=A.ProcessID
   INNER JOIN APS_ProcessPlan C2 ON C.ProcessID=C2.ProcessID AND C2.OrderID=A.OrderID  and ISNULL(a.DataSource,'')=ISNULL(C2.DataSource,'')
   INNER JOIN APS_DayPlan A2 ON A2.ProcessPlanID=C2.ProcessPlanID AND A2.PlanDay>=CAST(GETDATE() AS DATE)
   inner join APS_Process a3 on c2.ProcessID=a3.ProcessID
   WHERE B.CompletionDate IS NULL and a.Status=1  and a2.HasQty=0

   INSERT INTO [dbo].[APS_DayPlan]
           ([OrderID]
           ,[MaterialID]
           ,[ProcessPlanID]
           ,[WorkShopID]
           ,[LineID]
           ,[PlanQty]
           ,[HasQty]
           ,[Status]
           ,[CreatedBy]
           ,[CreatedByName]
           ,[ModifiedBy]
           ,[ModifiedByName]
           ,[CreatedOn]
           ,[ModifyedOn]
           ,[Remark1]
           ,[Remark2]
           ,[FeedingDate]
           ,[Capacity]
           ,[ExpectTime]
           ,[PlanDay]
           ,[StartTime]
           ,[EndTime],WorkingTimesID)

      SELECT  A2.[OrderID]
           ,A2.[MaterialID]
           ,d2.[ProcessPlanID]
           ,d2.[WorkShopID]
           ,d2.[LineID]
