        /// <summary>
        /// 保存上班
        /// </summary>
        /// <returns></returns>
        public string SaveWorkingTimes()
        {
            bool result = true;
            string msg = "";

            try
            {



                JArray jArray = JsonConvert.DeserializeObject(BodyJson) as JArray;
                // CheckClientJson(ref result, ref msg, jArray);
                if (result)
                {

                    List<WorkingTimes> workingTimes = JsonConvert.DeserializeObject<List<WorkingTimes>>(BodyJson);
                    int index = 0;
                    StringBuilder stringBuilder = new StringBuilder();
                    foreach (var obj in workingTimes)
                    {

                        if (obj.StartDate.HasValue == false)
                        {
                            obj.StartDate = obj.StartDate.GetValueOrDefault(DateTime.Now.Date);
                        }
                        if (obj.EndDate.HasValue == false)
                        {
                            obj.EndDate = obj.StartDate.GetValueOrDefault(DateTime.Now).AddMonths(5);
                        }



                        bool isFirstWeek = true;
                        bool flag = false;
                        while (obj.StartDate <= obj.EndDate)
                        {
                            stringBuilder.Append(@" delete  FROM [dbo].[APS_OrganizeWorkingTimesDetail]
  WHERE WorkingDate = '" + obj.StartDate.GetValueOrDefault().Date + "' and OrganizeID=" + obj.OrganizeID);
                            int bsDay = obj.BSDay;

                            foreach (var obj2 in obj.children)
                            {

                                if (string.IsNullOrEmpty(obj2.WorkingTimesID))
                                {
                                    obj2.WorkingTimesID = obj.WorkingTimesID;
                                }
                                index++;
                                if (//obj2.H1.GetValueOrDefault() > 0 &&
                                    (int)obj.StartDate.GetValueOrDefault().DayOfWeek == obj2.WeekDay)
                                {

                                    if (obj.IsBSDay)
                                    {//使用大小周
                                        if (flag == false)
                                        {
                                            obj.BSDay = bsDay;
                                            flag = true;
                                        }
                                        if ((int)obj.StartDate.GetValueOrDefault().DayOfWeek == 1)
                                        {//判断第一个起始日期
                                         // isFirstWeek = false;
                                            obj.BSDay = obj.BSDay == 0 ? 1 : 0;
                                        }

                                        if (obj.BSDay == 0 && ((int)obj.StartDate.GetValueOrDefault().DayOfWeek == 6 || (int)obj.StartDate.GetValueOrDefault().DayOfWeek == 0))
                                        {//，小周，周六日忽略

                                          //  continue;
                                          obj2.H2=obj2.H1=obj2.Peoples=0;
                                        }
                                        else if (obj.BSDay == 1 && (int)obj.StartDate.GetValueOrDefault().DayOfWeek == 0)
                                        {//周日忽略
                                            obj2.H2 = obj2.H1 = obj2.Peoples = 0;
                                            //continue;
                                        }
                                    }

                                    stringBuilder.Append(string.Format(@"

INSERT INTO [dbo].[APS_OrganizeWorkingTimesDetail]
           ([WorkingTimesDetailID]
           ,[OrganizeID]
           ,[WorkingDate]
           ,[Status]
           ,[CreatedBy]
           ,[CreatedByName]
           ,[CreatedOn]
 
           ,[Peoples]
           ,[TotalHours]
           ,[WorkingTimesID]
           ,[OverTime]
           ,[WorkTime],RemainingHours)
SELECT '{0}',{1},'{2}',1,'{3}','{4}',GETDATE(),CASE WHEN {5}=0 THEN A.TotalPeoples ELSE {5} END,{6},'{7}',{8},{9},{6}
 from Dev_Organize A
  WHERE A.OrganizeID={1}
 
                                ", StringHelper.GenerateStringID(), obj.OrganizeID, obj.StartDate, dev_Account.Account, dev_Account.Name
                                , obj2.Peoples.GetValueOrDefault(), obj2.H1.GetValueOrDefault() + obj2.H2.GetValueOrDefault(), obj2.WorkingTimesID, obj2.H2.GetValueOrDefault(0), obj2.H1.GetValueOrDefault(0)));
                                }
                                else
                                {

                                }

                            }
                            obj.StartDate = obj.StartDate.GetValueOrDefault().AddDays(1);
                        }
                        SqlHelper.ExecuteNonQuery(SqlHelper.MSSQLConnectionString, CommandType.Text, stringBuilder.ToString());
                        SqlHelper.ExecuteNonQuery(@"DELETE A  from APS_OrganizeWorkingTimesDetail a
inner join Dev_Organize b on a.OrganizeID=b.OrganizeID
inner join APS_Holiday c on b.OrganizeIDs like '%$'+CAST(c.OrganizeID as varchar(10))+'$%'
where  a.WorkingDate>=c.StartDate and a.WorkingDate<=c.EndDate
AND C.Status=1");
                        stringBuilder = new StringBuilder();
                        result = true;
                        msg = "操作成功";
                    }
                }
            }
            catch (Exception ex)
            {
                result = false;
                msg = ex.Message;
            }
            return JsonConvert.SerializeObject(new
            {

                result,
                msg,
                data = jArray
            });
        }




