        #region QF
        ///<summary>
        /// 获取合并BOM组件
        /// </summary>
        /// <returns></returns>
        public string GetMergeBOMData()
        {
            bool result = true;
            string msg = "";
            DataSet ds = null;
            try
            {
                JObject jObject = JsonConvert.DeserializeObject(BodyJson) as JObject;
                if (jObject == null)
                {
                    msg = "未接收到数据，请确认是否为JSON格式";
                    result = false;
                }
                else
                {
                    try
                    {
                        if (jObject.ContainsKey("dicID") == true)
                        {
                            int dicID = int.Parse(jObject["dicID"].ToString());
                            string fields = "";
                            if (jObject.ContainsKey("fields"))
                            {
                                fields = jObject["fields"].ToString();
                            }
                            MSSQLCore mSSQLCore = new MSSQLCore(dicID, jObject, "");
                            mSSQLCore.Fields = fields;
                            mSSQLCore.GetSql();
                            ds = SqlHelper.ExecuteDataset(SqlHelper.MSSQLConnectionString, CommandType.Text, mSSQLCore.SQL);
                            ds.Tables[0].Columns.Add("children", typeof(DataTable));
                            string MachineMouldIDs = "'a'";
                            foreach (DataRow dr in ds.Tables[0].Rows)
                            {
                                MachineMouldIDs += ",'" + dr["MachineMouldID"].ToString() + "'";
                            }
                            DataTable LIST = SqlHelper.ExecuteDataTable(@"select B.*,F.MoldName,b.BOMStartDate as StartDate
,b.BOMEndDate as EndDate,E.OrganizeName as LineName,a.MachineMouldID,C.MaterialName,C.Spec
,D.StatusName as ProductionStatusName
from APS_MachineMouldMaterial A
inner JOIN APS_OrderBOM B ON A.MaterialID = B.MaterialID
left join Dev_Status D ON D.StatusID = B.ProductionStatus
left join dev_Organize E ON E.OrganizeID = b.OutfitID
left join APS_MachineMould F ON A.MachineMouldID = F.MachineMouldID
inner join APS_Material C ON C.MaterialID = B.MaterialID  where A.MachineMouldID IN(" + MachineMouldIDs + @")


");
                            string BatchNos = "'A'";
                            ds.Tables[0].Columns.Add("IsNew");
                            Dictionary<string, List<string>> keyValuePairs = new Dictionary<string, List<string>>();
                            foreach (DataRow dr in ds.Tables[0].Rows)
                            {
                                BatchNos += ",'" + dr["BatchNo"].ToString() + "'";
                                if (keyValuePairs.ContainsKey(dr["BatchNo"].ToString()) == false)
                                {

                                    keyValuePairs.Add(dr["BatchNo"].ToString(), new List<string>());
                                }


                            }

                            DataTable dtBom = SqlHelper.ExecuteDataTable(@"SELECT A.BatchNo,B.Code,A.MaterialID FROM 
APS_OrderBOM A
INNER JOIN APS_Material B ON A.MaterialID=B.MaterialID
WHERE A.BatchNo IN(" + BatchNos + ")");
                            foreach (DataRow dr in ds.Tables[0].Rows)
                            {

                                DataRow[] dataRows = dtBom.Select("BatchNo='" + dr["BatchNo"].ToString() + "'");
                                foreach (DataRow dataRow1 in dataRows)
                                {
                                    keyValuePairs[dr["BatchNo"].ToString()].Add(dataRow1["MaterialID"].ToString());
                                }

                            }
                            if (LIST != null)
                            {

                                foreach (DataRow dr in ds.Tables[0].Rows)
                                {
                                    DataRow[] dataRows = null;
                                    int ProductionStatus = int.Parse(dr["ProductionStatus"].ToString());
                                    int IsDifficent = 0;
                                    String IsDifficentName = "";
                                    if (ProductionStatus == 25)
                                    {//已完成
                                        dataRows = LIST.Select("MachineMouldID= '" + dr["MachineMouldID"].ToString() + "' and BatchNo= '" + dr["BatchNo"].ToString() + "' ");
                                    }
                                    else if (ProductionStatus == 21)
                                    {//待生产
                                        dataRows = LIST.Select("MachineMouldID= '" + dr["MachineMouldID"].ToString() + "' and  ProductionStatus = 21 AND MaterialID=" + dr["MaterialID"].ToString());
                                    }
                                    else if (ProductionStatus == 28)
                                    {//待生产
                                        dataRows = LIST.Select("MachineMouldID= '" + dr["MachineMouldID"].ToString() + "' and  ProductionStatus = 28 AND MaterialID=" + dr["MaterialID"].ToString());
                                    }
                                    else
                                    {
                                        dataRows = LIST.Select("MachineMouldID= '" + dr["MachineMouldID"].ToString() + "' and ProductionStatus in(21,22,28) AND MaterialID=" + dr["MaterialID"].ToString());
                                        DataRow[] dataRows2 = LIST.Select("MachineMouldID= '" + dr["MachineMouldID"].ToString() + "' and ProductionStatus= '" + 21 + "'  AND MaterialID=" + dr["MaterialID"].ToString());
                                        if (dataRows2.Length != 0)
                                        {
                                            IsDifficent = 1;
                                            IsDifficentName = "有";
                                        }
                                    }
                                    List<string> listMaterial = new List<string>();
                                    DataTable children = LIST.Clone();
                                    children.Columns.Add("IsNew");
                                    foreach (DataRow dataRow in dataRows)
                                    {

                                        DataRow newRow = children.NewRow();
                                        foreach (DataColumn dataColumn in LIST.Columns)
                                        {
                                            newRow[dataColumn.ColumnName] = dataRow[dataColumn.ColumnName];
                                        }
                                        newRow["ParentID"] = dr["MoldMergeBatchID"].ToString();
                                        children.Rows.Add(newRow);
                                        if (dataRow["ProductionStatus"].ToString() == "21")
                                        {
                                            if (IsDifficentName == "")
                                            {
                                                newRow["IsNew"] = "2";
                                                dr["IsNew"] = "2";
                                            }
                                            else
                                            {
                                                if (keyValuePairs[dr["BatchNo"].ToString()].Where(m => m == dataRow["MaterialID"].ToString()).Count() > 0)
                                                {
                                                    newRow["IsNew"] = "1";
                                                    dr["IsNew"] = "1";
                                                }
                                                else
                                                {
                                                    newRow["IsNew"] = "0";
                                                    dr["IsNew"] = "0";
                                                }
                                            }

                                        }
                                    }
                                    dr["IsDifficent"] = IsDifficent;
                                    dr["IsDifficentName"] = IsDifficentName;
                                    dr["children"] = children;
                                    //m[name]

                                }
                                msg = "读取成功";

                            }
                        }
                        else
                        {
                            msg = "没有接收到dicID";
                            result = false;
                        }
                    }
                    catch (Exception ex)
                    {
                        msg = ex.Message;
                        result = false;
                    }
                }
            }
            catch (Exception ex)
            {
                result = false;
                msg = ex.Message;
            }
            if (result == false)
            {
                ds = new DataSet();
                ds.Tables.Add(new DataTable());
            }

            int count = 0;
            try
            {
                count = int.Parse(ds.Tables[1].Rows[0][0].ToString());
            }
            catch (Exception ex)
            {

            }


            return JsonConvert.SerializeObject(new
            {

                data = ds.Tables[0].DefaultView.ToTable(),//数据
                result//返回标记
                       ,
                msg//返回的信息
                       ,
                count = count < ds.Tables[0].Rows.Count ? ds.Tables[0].Rows.Count : count //记录数
            });



        }

