        public string ResetEKViewSort()
        {
            bool result = true;
            string msg = "操作成功";

            try
            {
                if (!string.IsNullOrEmpty(BodyJson))
                {

                    StringBuilder stringBuilder = new StringBuilder();
                    jArray = JsonConvert.DeserializeObject(BodyJson) as JArray;
                    string ProcessPlanID = "0";
                    foreach (JObject jObject in jArray)
                    {
                        if (!string.IsNullOrEmpty(jObject["ProcessPlanID"].ToString()))
                        {
                            ProcessPlanID += "," + jObject["ProcessPlanID"].ToString();
                        }
                    }
                    stringBuilder.Append(@"update A SET  A.StartDate=B.PlanDay
FROM APS_ProcessPlan A
 
inner JOIN 
(
SELECT 
ProcessPlanID,MIN(PlanDay) PlanDay,Max(PlanDay) as enddate
FROM APS_DayPlan
WHERE PlanDay>=CAST(GETDATE() AS DATE)
GROUP BY ProcessPlanID
) B ON A.ProcessPlanID=B.ProcessPlanID
WHERE   A.ProcessPlanID IN (" + ProcessPlanID + @") AND ISNULL(A.HasQty1,a.Hasqty)=0
AND ISNULL(A.StartDate,GETDATE())<>B.PlanDay

update A SET a.enddate=b.enddate
FROM APS_ProcessPlan A
 
inner JOIN 
(
SELECT 
ProcessPlanID,MIN(PlanDay) PlanDay,Max(PlanDay) as enddate
FROM APS_DayPlan
WHERE PlanDay>=CAST(GETDATE() AS DATE)
GROUP BY ProcessPlanID
) B ON A.ProcessPlanID=B.ProcessPlanID
WHERE   A.ProcessPlanID IN (" + ProcessPlanID + @")  
AND ISNULL(A.enddate,GETDATE())<>B.enddate
");

                    stringBuilder.Append(@"UPDATE B
SET    B.VIEWSORT = a.r
FROM   (SELECT Row_number()
                  OVER(
                   partition BY a.lineid
                   ORDER BY a.LineID, CASE WHEN a.HasQty>0 AND a.PlanQty - Isnull(A.HasQty, 0) >0 THEN 0 WHEN a.HasQty=0 
				   THEN 1 ELSE 2 END, a.startdate, b.WorkingTimesID, a.materialid) AS R,
               A.ProcessPlanID
        FROM   APS_ProcessPlan a
           LEFT JOIN (SELECT b.ProcessPlanID,
                                 Min(b.PlanDay) AS PlanDay 
								 ,min(b.WorkingTimesID) as WorkingTimesID
                          FROM   (
						  SELECT ProcessPlanID,
                                 Min(PlanDay) AS PlanDay 
                          FROM   APS_DayPlan
                          WHERE  PlanDay > Getdate() - 1
                          GROUP  BY ProcessPlanID
						  
						  
						  ) a
						  inner join APS_DayPlan b on a.ProcessPlanID=b.ProcessPlanID
						  and a.PlanDay=b.PlanDay
                          WHERE  b.PlanDay > Getdate() - 1
                          GROUP  BY b.ProcessPlanID
                                    ) b
                      ON a.ProcessPlanID = b.ProcessPlanID
        WHERE  a.ProcessPlanID IN( " + ProcessPlanID + @" )) a
       INNER JOIN APS_ProcessPlan b
               ON a.ProcessPlanID = b.ProcessPlanID 


 ");

                    SqlHelper.ExecuteNonQuery(stringBuilder.ToString());
                }
                else
                {
                    result = false;
                    msg = "未接收到数据";
                }


            }
            catch (Exception ex)
            {
                result = false;
                msg = "错误！错误信息:" + ex.Message;
            }
            return JsonConvert.SerializeObject(new
            {

                result,
                msg
            }); ; ;
        }

