                                                ", playQty, DateTime.Now.AddDays(i).Date

                                                            ));

                                                            RemainingHours =
                                                            qty -= playQty;
                                                            if (qty <= 0)
                                                            {
                                                                break;
                                                            }
                                                        }
                                                        else
                                                        {
                                                            break;
                                                        }
                                                    }
                                                }

                                            }

                                        }
                                    }
                                    //if (dataRows.Length == 0)
                                    //{
                                    //    result = false;
                                    //    msg += "第" + count + "行找不到需要排程的工序";
                                    //}

                                }


                                if (result)
                                {
                                    try
                                    {
                                        SqlHelper.ExecuteNonQuery(tran, CommandType.Text, stringBuilder1.ToString());
                                        tran.Commit();
                                        result = true;
                                        msg = "操作成功";


                                    }
                                    catch (Exception ex)
                                    {
                                        result = false;
                                        msg = ex.Message + stringBuilder1.ToString();
                                        tran.Rollback();
                                    }
                                    finally
                                    {
                                        connection.Close();
                                    }

                                }

                            }

                        }
                        catch (Exception ex)
                        {
                            result = false;
                            msg = ex.Message;


                        }
                        finally
                        {
                            connection.Close();
                        }



                    }

                }
            }
            catch (Exception ex)
            {

            }


            return JsonConvert.SerializeObject(new
            {

                result,
                msg,
                data = jArray
            }); ; ;
        }

        /// <summary>
        /// 重置PCB排序
        /// </summary>
        /// <returns></returns>
        public string ResetPCBDayPlan()
        {
            bool result = true;
            string msg = "";

            try
            {



                jArray = JsonConvert.DeserializeObject(BodyJson) as JArray;
                if (jArray == null)
                {
                    msg = "未接收到数据，请确认是否为JSON格式";
                    result = false;

                }
                else if (dev_Account == null)
                {
                    msg = "当前登录信息已经丢失，请刷新页面重新登录";
                    result = false;
                }
                else
                {
                    int index = 1;

                    string processPlanIDs = "0";
                    foreach (JObject jObject in jArray)
                    {

                        processPlanIDs += "," + jObject["ProcessPlanID"].ToString();


                    }
                    if (processPlanIDs != "0")
                    {
                        SqlHelper.ExecuteNonQuery(string.Format(@"UPDATE B SET  B.ViewSort=A.R

                            FROM (
                            SELECT 
                            ROW_NUMBER() OVER(PARTITION BY A.LINEID ORDER BY ISNULL(A.LINEID,1000),A.MATERIALID
                            ,isnull(b1.ProcessPlanID,1)
                            ,isnull(b2.ProcessPlanID,2)
                            ,isnull(b3.ProcessPlanID,3)
                            ,isnull(b4.ProcessPlanID,4)
                            ,isnull(b5.ProcessPlanID,5)
                            ,isnull(b6.ProcessPlanID,6)
                            ) as R
                            ,A.ProcessPlanID

                            FROM V_APS_MOPlanStep4 A
                            left join APS_DayPlan b1 on a.ProcessPlanID=b1.ProcessPlanID AND b1.PlanDay=CAST(GETDATE()+0 as date)
                            left join APS_DayPlan b2 on a.ProcessPlanID=b2.ProcessPlanID AND b2.PlanDay=CAST(GETDATE()+1 as date)

                            left join APS_DayPlan b3 on a.ProcessPlanID=b3.ProcessPlanID AND b3.PlanDay=CAST(GETDATE()+2 as date)

                            left join APS_DayPlan b4 on a.ProcessPlanID=b4.ProcessPlanID AND b4.PlanDay=CAST(GETDATE()+3 as date)

                            left join APS_DayPlan b5 on a.ProcessPlanID=b5.ProcessPlanID AND b5.PlanDay=CAST(GETDATE()+4 as date)
                            left join APS_DayPlan b6 on a.ProcessPlanID=b6.ProcessPlanID AND b6.PlanDay=CAST(GETDATE()+5 as date)
                            )  A
                            INNER JOIN APS_ProcessPlan B ON A.ProcessPlanID=B.ProcessPlanID
                             WHERE B.ProcessPlanID IN(
                             {0}
                             )", processPlanIDs));
                    }

                }
            }
            catch (Exception ex)
            {

            }


            return JsonConvert.SerializeObject(new
            {

                result,
                msg
            }); ;
        }
