        /// <summary>
        /// 
        /// </summary>
        /// <param name="isUpdate">是否是审核</param>
        /// <returns></returns>
        public string UpdateOrderStartDate(string isUpdate)
        {
            bool result = true;
            string msg = "";

            try
            {



                jArray = JsonConvert.DeserializeObject(BodyJson) as JArray;
                if (jArray == null || jArray.Count == 0)
                {
                    msg = "未接收到数据，请确认是否为JSON格式";
                    result = false;
                }
                else
                {


                    Entities.Configuration.ValidateOnSaveEnabled = false;


                    SqlConnection connection = new SqlConnection(SqlHelper.MSSQLConnectionString);
                    connection.Open();
                    // using (SqlTransaction tran = connection.BeginTransaction())
                    {
                        try
                        {
                            EasyManufacture.Infrastructure.SystemInterface.EAST.SAP sAP = new SystemInterface.EAST.SAP();
                            List<APS_Order> lstOrder = new List<APS_Order>();
                            foreach (JObject jObject in jArray)
                            {

                                string orderNo = jObject["OrderNo"].ToString();
                                string startDate = jObject["StartDate"].ToString();
                                string endDate = jObject["EndDate"].ToString();
                                string erpStartDate = jObject["ERPStartDate"].ToString();
                                if (string.IsNullOrEmpty(startDate))
                                {
                                    result = false;
                                    msg = orderNo + "没有开始日期";
                                    break;
                                }
                                else
                                {
                                    systemLog.SaveLog(SystemLog.SystemLogType.接口推送, "保存了数据" + Math.Abs((DateTime.Parse(startDate) - DateTime.Parse(erpStartDate)).TotalDays), dev_Account, null);
                                    if (Math.Abs((DateTime.Parse(startDate) - DateTime.Parse(erpStartDate)).TotalDays) >= 1 && string.IsNullOrEmpty(isUpdate))
                                    {
                                        jObject["Status"] = "0";
                                    }
                                    else
                                    {
                                        jObject["Status"] = "3";

                                        APS_Order aPS_Order = new APS_Order();
                                        aPS_Order.OrderNo = orderNo;
                                        aPS_Order.Extend1 = startDate;
                                        aPS_Order.Extend2 = endDate;
                                        aPS_Order.Extend9 = jObject["Extend9"].ToString();
                                        aPS_Order.ControlID = jObject["ControlID"].ToString();
                                        lstOrder.Add(aPS_Order);
                                        //sAP.UpdateOrderStartDate(orderNo, startDate, endDate, ref msg);
                                    }
                                }

                            }
                            if (result)
                            {
                                //  tran.Commit();
                                SaveData();
                                result = isAllOK;
                                msg = allMsg;

                                {
                                    systemLog.SaveLog(SystemLog.SystemLogType.接口推送, "保存了数据" + lstOrder.Count, dev_Account, null);
                                }
                                if (result)
                                {
                                    foreach (var obj in lstOrder)
                                    {
                                        string m = "";
                                        result = sAP.UpdateOrderStartDate(obj.OrderNo, obj.Extend1, obj.Extend2, obj.Extend9, ref m, obj.ControlID);
                                        if (result == false)
                                        {

                                            msg += m;
                                        }
                                        else
                                        {
                                            systemLog.SaveLog(SystemLog.SystemLogType.接口推送, m, dev_Account, null);
                                        }
                                    }
                                }
                            }



                        }
                        catch (Exception ex)
                        {
                            result = false;
                            msg = ex.Message;
                            // tran.Rollback();


                        }
                        finally
                        {

                        }
                    }
                    connection.Close();

                }

            }
            catch (Exception ex)
            {
                result = false;
                msg = ex.Message;
            }
            return JsonConvert.SerializeObject(new
            {

                result,
                msg = msg,
                data = jArray
            });

        }

