        #region 基础接口部分

        public string GetDataSource()
        {
            string dataSourceID = "";
            bool result = true;
            string msg = "";
            DataTable dtUSQL = null;
            try
            {
                JObject jObject = JsonConvert.DeserializeObject(BodyJson) as JObject;
                if (jObject == null)
                {
                    msg = "未接收到数据，请确认是否为JSON格式";
                    result = false;
                }
                else
                {
                    try
                    {
                        if (jObject.ContainsKey("DataSourceID") == true)
                        {
                            dataSourceID = jObject["DataSourceID"].ToString();
                            if (!string.IsNullOrEmpty(dataSourceID))
                            {
                                DataTable dataTable = SqlHelper.ExecuteDataTable("SELECT * FROM [Dev_DataSource] WHERE [DataSourceID]='" + dataSourceID + "'");
                                string value = "", label = "";
                                if (dataTable.Rows.Count > 0)
                                {
                                    string USQL = dataTable.Rows[0]["USQL"].ToString();
                                    try
                                    {

                                        USQL = USQL.Replace("{CenterID}", dev_Account.CenterID.ToString());
                                        USQL = USQL.Replace("{WorkFlowInstanceID}", dev_Account.WorkFlowInstanceID);
                                        USQL = USQL.Replace("{Account}", dev_Account.Account);
                                        USQL = USQL.Replace("{GroupID}", dev_Account.GroupID.ToString());
                                    }
                                    catch (Exception ex)
                                    {
                                        result = false;
                                        msg = ex.Message;
                                    }
                                    if (dev_Account.Extend2!="")
                                    {
                                        if (USQL.ToLower().Contains("where"))
                                        {
                                            USQL += " AND GroupName='" + dev_Account.Extend2 + "'";
                                        }
                                        else
                                        {
                                            USQL += " where  GroupName='" + dev_Account.Extend2 + "'";
                                        }
                                    }
                                    dtUSQL = SqlHelper.ExecuteDataTable(USQL);
                                    result = true;
                                    msg = "查询成功";

                                }
                                else
                                {
                                    result = false;
                                    msg = "记录不存在";
                                }
                            }
                        }
                        else
                        {
                            result = false;
                            msg = "未接收到DataSourceID";
                        }
                    }
                    catch (Exception ex)
                    {
                        result = false;
                        msg = ex.Message;
                    }
                }

            }

            catch (Exception ex)
            {
                result = false;
                msg = ex.Message;
            }
            return JsonConvert.SerializeObject(new
            {

                data = dtUSQL,//数据
                result//返回标记
                   ,
                msg//返回的信息
                   ,
                count = dtUSQL == null ? 0 : dtUSQL.Rows.Count
                //记录数
            });

        }

