        public string ImportOrderPlan()
        {
            bool result = true;
            string msg = "";

            try
            {



                JArray jArray = JsonConvert.DeserializeObject(BodyJson) as JArray;
                if (jArray == null || jArray.Count == 0)
                {
                    msg = "未接收到数据，请确认是否为JSON格式";
                    result = false;
                }
                else
                {


                    Entities.Configuration.ValidateOnSaveEnabled = false;


                    SqlConnection connection = new SqlConnection(SqlHelper.MSSQLConnectionString);
                    connection.Open();
                    // using (SqlTransaction tran = connection.BeginTransaction())
                    {
                        try
                        {

                            string orderNos = "''";
                            List<string> lstOrder = new List<string>();
                            foreach (JObject jObject in jArray)
                            {

                                string orderNo = jObject["OrderNo"].ToString();

                                if (!string.IsNullOrEmpty(orderNo))
                                {
                                    orderNos += ",'" + orderNo + "'";
                                    lstOrder.Add(orderNo);
                                }


                            }
                            if (!string.IsNullOrEmpty(orderNos))
                            {

                                DataTable dataTable = SqlHelper.ExecuteDataTable(String.Format(@"  SELECT  OrderNo
   FROM APS_Order
   WHERE OrderNo IN(
   {2}
   )", dev_Account.Account, dev_Account.Name, orderNos));

                                foreach (string o in lstOrder)
                                {

                                    if (dataTable.Select("OrderNo='" + o + "'").Length == 0)
                                    {
                                        msg += "," + o;
                                    }
                                }


                                SqlHelper.ExecuteNonQuery(string.Format(@"delete from APS_OrderPlan;INSERT INTO [dbo].[APS_OrderPlan]
           ([OrderID]
           ,[MaterialID]
           ,[HasQty]
           ,[AwaitQty]
           ,[PlanQty]
      
           ,[StartDate]
           ,[EndDate]
           ,[DemandDate]
           ,[ProductionStatus]
           ,[Status]
           ,[CreatedBy]
           ,[CreatedByName]
           ,[CreatedOn]
           ,[ModifyedOn]
         )
   SELECT OrderID,MaterialID,0,Qty,Qty,ERPStartDate,ERPEndDate,ERPStartDate
   ,26,1,'{0}','{1}',GETDATE(),GETDATE()
   FROM APS_Order
   WHERE OrderNo IN(
   {2}
   )
", dev_Account.Account, dev_Account.Name, orderNos));
                            }



                        }
                        catch (Exception ex)
                        {
                            result = false;
                            msg = ex.Message;
                            // tran.Rollback();


                        }
                        finally
                        {

                        }
                    }
                    connection.Close();

                }

            }
            catch (Exception ex)
            {
                result = false;
                msg = ex.Message;
            }
            if (!string.IsNullOrEmpty(msg))
            {
                msg = "以下生产订单找不到：" + msg.Trim(',');
            }
            return JsonConvert.SerializeObject(new
            {

                result,
                msg = msg,
                data = jArray
            });

        }
