        /// <summary>
        /// 金羚主看板
        /// </summary>
        /// <returns></returns>
        public string GetJLReport()
        {

            DataSet dataSet = null;
            bool result = false;
            string msg = "";

            try
            {
                dataSet = SqlHelper.ExecuteDataset(@"
--0月度累计达成
SELECT A2.OrganizeName                                          AS N1,
       Cast(Sum(HasQty) / Sum(PlanQty) * 100 AS DECIMAL(18, 2)) AS P1
FROM   Dev_Organize a2
       LEFT JOIN v_APS_DayPlan A
              ON A2.OrganizeID = A.WorkShopID
                 AND Format(A.PlanDay, 'yyyyMM') = Format(Getdate(), 'yyyyMM')
                 AND a.WorkShopName IS NOT NULL
WHERE  A2.OrganizeTypeID = 5
GROUP  BY A.WorkShopID,
          A2.OrganizeName

--1超期订单预警

SELECT Row_number()
         OVER(
           ORDER BY C1)                                        AS N1,
       *,
       FORMAT(Cast(C1 / (case when Sum(C1)
                   OVER(
                     partition BY '')=0 then 1 else Sum(C1)
                   OVER(
                     partition BY '') end) AS DECIMAL(18, 2)) * 100,'P2') AS P1
FROM   (SELECT NULL                            AS N2,
               Isnull(b.AbnormalReason, '未分配') N3,
               Sum(CASE
                     WHEN ERPStartDate <= Cast(Getdate() AS DATE) THEN 1.0
                     ELSE 0.0
                   END)                        AS C1
        FROM   [APS_AbnormalReason] B
               LEFT JOIN APS_Order A
                      ON A.CompletionDate IS NULL
                         AND A.Status = 1
                         AND A.MFGOrganizeID = 162 and A.Extend2=b.AbnormalReason
        GROUP  BY B.AbnormalReason) A
ORDER  BY C1

--2超期订单原因
SELECT Row_number()
         OVER(
           ORDER BY C1)                                        AS N1,
       *,
    FORMAT(Cast(C1 / (case when Sum(C1)
                   OVER(
                     partition BY '')=0 then 1 else Sum(C1)
                   OVER(
                     partition BY '') end) AS DECIMAL(18, 2)) * 100,'P2') AS P1
FROM   (SELECT NULL                            AS N2,
               Isnull(b.AbnormalReason, '未分配') N3,
               Sum(CASE
                     WHEN ERPStartDate <= Cast(Getdate() AS DATE) THEN 1.0
                     ELSE 0.0
                   END)                        AS C1
        FROM   [APS_AbnormalReason] B
               LEFT JOIN APS_Order A
                      ON A.CompletionDate IS NULL
                         AND A.Status = 1
                         AND A.MFGOrganizeID = 1222 and A.Extend2=b.AbnormalReason
        GROUP  BY B.AbnormalReason) A
ORDER  BY C1


--3 今日计划总量
SELECT Cast(Sum(A.PlanQty) AS INT) AS S1
--, Sum(A.HasQty)                         AS S2,
--       Sum(A.HasQty) / Sum(A2.PlanQty) * 100 AS P1
FROM   APS_DayPlan A
       INNER JOIN APS_ProcessPlan A2
               ON A.ProcessPlanID = A2.ProcessPlanID
                  AND A2.Status = 1
       INNER JOIN APS_Order A3
               ON A3.OrderID = A2.OrderID
                 
       INNER JOIN Dev_Organize B
               ON A.LineID = B.OrganizeID
       INNER JOIN Dev_Organize C
               ON A.WorkShopID = C.OrganizeID
WHERE  A.PlanDay = Cast(Getdate() AS DATE)
       AND A2.ProcessID = 'P2208290001'

--4投产达成率
SELECT Sum(CASE
             WHEN A.HasQty > 0 THEN 1
             ELSE 0
           END)                                           AS C1,
       Count(1)                                           AS C2,
       Cast(Sum(CASE
                  WHEN A.HasQty > 0 THEN 1
                  ELSE 0.0
                END) / Count(1.0) * 100 AS DECIMAL(18, 2))AS P1
FROM   APS_DayPlan A
       INNER JOIN APS_ProcessPlan A2
               ON A.ProcessPlanID = A2.ProcessPlanID
                  AND A2.Status = 1
       INNER JOIN Dev_Organize B
               ON A.LineID = B.OrganizeID
       INNER JOIN Dev_Organize C
               ON A.WorkShopID = C.OrganizeID
	   INNER JOIN APS_Order d on a.OrderID=d.OrderID and d.MFGOrganizeID=162
WHERE  A.PlanDay = Cast(Getdate() AS DATE)
 AND A2.ProcessID = 'P2208290001'
--5计划完成率
SELECT Cast(Sum(A.HasQty) AS REAL)                                  AS S1,
       Cast(Sum(A.PlanQty) AS REAL)                                 AS S2,
       Cast(Sum(A.HasQty) / Sum(A.PlanQty) * 100 AS DECIMAL(18, 2)) AS P1
FROM   APS_DayPlan A
       INNER JOIN APS_ProcessPlan A2
               ON A.ProcessPlanID = A2.ProcessPlanID
                  AND A2.Status = 1
       INNER JOIN Dev_Organize B
               ON A.LineID = B.OrganizeID
       INNER JOIN Dev_Organize C
               ON A.WorkShopID = C.OrganizeID
		INNER JOIN APS_Order d on a.OrderID=d.OrderID and d.MFGOrganizeID=162
WHERE  A.PlanDay = Cast(Getdate() AS DATE)
 AND A2.ProcessID = 'P2208290001'
--6 投产达成率
SELECT Sum(CASE
             WHEN A.HasQty > 0 THEN 1
             ELSE 0
           END)                                           AS C1,
       Count(1)                                           AS C2,
       Cast(Sum(CASE
                  WHEN A.HasQty > 0 THEN 1
                  ELSE 0.0
                END) / Count(1.0) * 100 AS DECIMAL(18, 2))AS P1
FROM   APS_DayPlan A
       INNER JOIN APS_ProcessPlan A2
               ON A.ProcessPlanID = A2.ProcessPlanID
                  AND A2.Status = 1
       INNER JOIN Dev_Organize B
               ON A.LineID = B.OrganizeID
       INNER JOIN Dev_Organize C
               ON A.WorkShopID = C.OrganizeID
	   INNER JOIN APS_Order d on a.OrderID=d.OrderID and d.MFGOrganizeID=1222
WHERE  A.PlanDay = Cast(Getdate() AS DATE)
 AND A2.ProcessID = 'P2208290001'
--7近15日计划完成情况
SELECT *,
       Cast(S1 / S2 * 100 AS DECIMAL(18, 2)) AS P1
FROM   (SELECT TOP 15 Format(PLANDAY, 'MM-dd')   AS N1,
                      -- a.PlanDay                AS N2,
                      Cast(Sum(HasQty) AS REAL)  AS S1,
                      Cast(Sum(PlanQty) AS REAL) AS S2
        FROM   v_APS_DayPlan A
        WHERE  PlanDay < Getdate()
        GROUP  BY a.PlanDay,
                  Format(PLANDAY, 'MM-dd')
        ORDER  BY PlanDay ) A

--8车间投产完成率
SELECT Format(PLANDAY, 'MM-dd')                                     N1,
       Cast(Sum(A.PlanQty) AS REAL)                                 AS S1,
       -- A.PlanDay                            AS N2,
       Cast(Sum(CASE
                  WHEN A.HasQty > 0 THEN 1
                  ELSE 0.0
                END) / Count(*) * 100 AS DECIMAL(18, 2))            AS P1,
       Cast(Sum(a.HasQty) / Sum(A.PlanQty) * 100 AS DECIMAL(18, 2)) AS P2
FROM   APS_DayPlan A
       INNER JOIN APS_ProcessPlan A2
               ON A.ProcessPlanID = A2.ProcessPlanID
                  AND A2.Status = 1
       INNER JOIN Dev_Organize B
               ON A.LineID = B.OrganizeID
       INNER JOIN Dev_Organize C
               ON A.WorkShopID = C.OrganizeID
WHERE  A.PlanDay <= Cast(Getdate() AS DATE)
       AND A.PlanDay >= Cast(Getdate() - 15 AS DATE)
GROUP  BY A.PlanDay
ORDER  BY A.PlanDay

--9 今日计划达成
SELECT Row_number()
         OVER(
           ORDER BY P1) AS N1,
       *
FROM   (SELECT B.OrganizeName                                                AS N2,
               Cast(Sum(A.PlanQty) AS REAL)                                  AS S1,
               Cast(Sum(A.HasQty) AS REAL)                                   AS S2,
               Cast(Sum(A.HasQty) / Sum(A2.PlanQty) * 100 AS DECIMAL(18, 2)) AS P1
        FROM   APS_DayPlan A
               INNER JOIN APS_ProcessPlan A2
                       ON A.ProcessPlanID = A2.ProcessPlanID
                          AND A2.Status = 1
               INNER JOIN Dev_Organize B
                       ON A.LineID = B.OrganizeID
               INNER JOIN Dev_Organize C
                       ON A.WorkShopID = C.OrganizeID
        WHERE  A.PlanDay = Cast(Getdate() AS DATE)
        GROUP  BY B.OrganizeName) A

--10 未来3日电机欠料 
SELECT Row_number()
         OVER(
           ORDER BY DemandDate, t2.demandqty) AS N1,
       Format(DemandDate, 'MM-dd')            N2,
       Spec                                   AS N3,
       Cast(OweQty AS REAL)                   AS S1,
       Cast(StockQty AS REAL)                 AS S2
FROM   APS_OrderPlanMaterialForm t2
WHERE  DemandDate >= Cast(Getdate() AS DATE)
       AND DemandDate <= Cast(Getdate() + 2 AS DATE)
       AND OweQty < 0
       AND ( t2.Code LIKE '3.01%'
              OR t2.Code LIKE '1.02%' )
       AND t2.MaterialName LIKE '%电机%'
ORDER  BY DemandDate

--11 配套前来最新收货
SELECT TOP 50 B.MaterialName             AS N1,
              Cast(D.OweQty AS REAL)     AS S1,
              Cast(A.ReceiptQty AS REAL) AS S2,
              A.CreatedOn                AS N2
FROM   WMS_ReceiptDetail A
       INNER JOIN APS_Material B
               ON A.MaterialID = B.MaterialID
       INNER JOIN WMS_Receipt C
               ON A.ReceiptID = C.ReceiptID
       INNER JOIN(SELECT MaterialID,
                         Sum(OweQty) AS OweQty
                  FROM   APS_OrderPlanMaterialForm
                  WHERE  OweQty < 0
                  GROUP  BY MaterialID) D
               ON A.MaterialID = D.MaterialID
ORDER  BY C.ReceiptDate DESC,
          C.CreatedOn DESC 


		  --12 恩平计划完成率
SELECT Cast(Sum(A.HasQty) AS REAL)                                  AS S1,
       Cast(Sum(A.PlanQty) AS REAL)                                 AS S2,
       Cast(Sum(A.HasQty) / Sum(A.PlanQty) * 100 AS DECIMAL(18, 2)) AS P1
FROM   APS_DayPlan A
       INNER JOIN APS_ProcessPlan A2
               ON A.ProcessPlanID = A2.ProcessPlanID
                  AND A2.Status = 1
       INNER JOIN Dev_Organize B
               ON A.LineID = B.OrganizeID
       INNER JOIN Dev_Organize C
               ON A.WorkShopID = C.OrganizeID
		INNER JOIN APS_Order d on a.OrderID=d.OrderID and d.MFGOrganizeID=1222
WHERE  A.PlanDay = Cast(Getdate() AS DATE)
 AND A2.ProcessID = 'P2208290001'
");
                result = true;
            }
            catch (Exception ex)
            {
                msg = ex.Message;

            }


            return JsonConvert.SerializeObject(new
            {

                result,
                msg,
                data = dataSet
            });
        }
