            {
                result = false;
                msg = "未接收到参数";
            }
            else
            {
                try
                {

                    string d1 = string.Format("{0:yyyy-MM-dd}", DateTime.Now);
                    string d2 = string.Format("{0:yyyy-MM-dd}", DateTime.Now.AddDays(60));
                    try
                    {
                        d1 = ((JArray)jObject["ReplyDate"])[0].ToString();
                        d2 = ((JArray)jObject["ReplyDate"])[1].ToString();
                    }
                    catch (Exception ex)
                    {

                    }


                    SqlHelper.ExecuteNonQuery("EXEC P_APS_GetInjectionDemand '" + d1 + "','" + d2 + "',null,null");
                    result = true;
                    msg = "数据抓取成功!";
                }
                catch (Exception ex)
                {
                    msg = ex.Message;
                }


            }
            return JsonConvert.SerializeObject(new
            {

                result,
                msg
            });
        }
