        /// <summary>
        /// 保存注塑周计划
        /// </summary>
        /// <returns></returns>
        public string SaveInjectionWeekPlan()
        {
            jArray = JsonConvert.DeserializeObject(BodyJson) as JArray;
            bool result = false;
            string msg = "";
            if (jArray == null)
            {
                result = false;
                msg = "未接收到数据";
            }
            else
            {
                try
                {
                    SaveData();
                    StringBuilder stringBuilder = new StringBuilder();
                    foreach (JObject jObject in jArray)
                    {
                        DateTime dateTime = DateTime.Now.Date;
                        for (int i = 0; i < 40; i++)
                        {
                            string key = string.Format("{0:MM-dd}", dateTime);
                            if (jObject.ContainsKey(key))
                            {
                                string val = jObject[key].ToString();

                                stringBuilder.Append(string.Format(@" DELETE 
  FROM  [dbo].[APS_MaterialDemand]
  WHERE MaterialID={0} AND DemandDay='{1}'", jObject["MaterialID"], dateTime));
                                if (!string.IsNullOrEmpty(val))
                                {
                                    stringBuilder.Append(string.Format(@"
 
INSERT INTO [dbo].[APS_MaterialDemand]
           ([MaterialID]
           ,[DemandQty]
           ,[DemandDay]
   
           ,[CreatedBy]
           ,[CreatedByName]
           ,[CreatedOn]
           ,[Status])

            SELECT {0},{2},'{1}','{3}','{4}',getdate(),1


        ", jObject["MaterialID"], dateTime, val, dev_Account.Account, dev_Account.Name));

                                }

                            }
                            dateTime = dateTime.AddDays(1);
                        }
                    }


                    SqlHelper.ExecuteNonQuery(stringBuilder.ToString());
                    result = true;
                    msg = "数据保存成功!";
                }
                catch (Exception ex)
                {
                    msg = ex.Message;
                }


            }
            return JsonConvert.SerializeObject(new
            {

                result,
                msg
            });
        }
