                bool isSetColor = false;

                DataTable dtTmp = new DataTable();
                dtTmp.Columns.Add("a");
              DataRow drNew=  dtTmp.NewRow();
                drNew["a"] = "a";
                dtTmp.Rows.Add(drNew);
                if (dtColor.Rows.Count > 0)
                {
                    
                    if(dtData.Columns.Contains("BColors")==false)
                    {
                        dtData.Columns.Add("BColors", typeof(Dictionary<string, string>));
                    }
                    if (dtData.Columns.Contains("FColors") == false)
                    {
                        dtData.Columns.Add("FColors", typeof(Dictionary<string, string>));
                    }

                    isSetColor = true;

                    string ReducedValue = "";
                    bool isReducedValue = false;
                    if (dtColor.Columns.Contains("ReducedValue"))
                    {//新版直接用颜色值对比
                        isReducedValue = true;
                    }
                    foreach (DataRow rowData in dtData.Rows)
                    {
                       
                        Dictionary<string, string> fColors = new Dictionary<string, string>();//字体颜色
                        Dictionary<string, string> bColors = new Dictionary<string, string>();//背景颜色
                        if (rowData["BColors"]!=DBNull.Value)
                        {
                            bColors = rowData["BColors"] as Dictionary<string, string>;
                        }
                        if (rowData["FColors"] != DBNull.Value)
                        {
                            fColors = rowData["FColors"] as Dictionary<string, string>;
                        }
                        foreach (DataRow rowColor in dtColor.Rows)
                        {
                            if (isReducedValue)
                            {
                                ReducedValue = rowColor["ReducedValue"].ToString();
                            }
               

                     
                            string[] colorFields = rowColor["RemarkField"].ToString().Split(',');//显示及条件字段
                            string showField = rowColor["JudgeField"].ToString();
                            if (string.IsNullOrEmpty(ReducedValue))
                            {

                               
                                if (!string.IsNullOrEmpty(rowColor["JudgeField"].ToString()))//颜色字段
                                {
                                    string color = rowData[showField].ToString();

                                    if (!string.IsNullOrEmpty(color))
                                    {

                                        foreach (string colorField in colorFields)
                                        {
                                            if (!string.IsNullOrEmpty(color) && !string.IsNullOrEmpty(colorField))
                                            {

                                                if (rowColor["ColorType"].ToString() == "BColors")
                                                {
                                                    if (bColors.ContainsKey(colorField))
                                                    {
                                                        continue;
                                                    }
                                                    bColors.Add(colorField, color);
                                                }
                                                else
                                                {
                                                    if (fColors.ContainsKey(colorField))
                                                    {
                                                        continue;
                                                    }
                                                    fColors.Add(colorField, color);
                                                }
                                            }
                                        }
                                    }


                                }
                                else
                                {//没有颜色字段，直接使用颜色值
                                    string color = rowColor["Color"].ToString();
                                    foreach (string colorField in colorFields)
                                    {
                                        if (!string.IsNullOrEmpty(color) && !string.IsNullOrEmpty(colorField))
                                        {
                                            if (rowColor["ColorType"].ToString() == "BColors")
                                            {
                                                if (bColors.ContainsKey(colorField))
                                                {
                                                    continue;
                                                }
                                                bColors.Add(colorField, color);
                                            }
                                            else
                                            {
                                                if (fColors.ContainsKey(colorField))
                                                {
                                                    continue;
                                                }
                                                fColors.Add(colorField, color);
                                            }
                                        }
                                    }
                                }
                            }
                            else
                            {
                                string color = rowColor["Color"].ToString();
                                string w = ReducedValue.Substring(0, 1);
                                ReducedValue = ReducedValue.Substring(1, ReducedValue.Length - 1);
                                string[] showFields = showField.Split(',');
                                foreach (string colorField in colorFields)
                                {
                                    if (!string.IsNullOrEmpty(color) && !string.IsNullOrEmpty(colorField))
                                    {
                                        bool flag = false;

                                       // if (!string.IsNullOrEmpty(rowData[colorField].ToString()))
                                       if(true)
                                        {
                                            switch (w)
                                            {
                                                case "=":
                                                    {//等于
                                                        if (dtData.Columns[colorField].DataType == typeof(decimal) || dtData.Columns[colorField].DataType == typeof(decimal?) || dtData.Columns[colorField].DataType == typeof(double?) || dtData.Columns[colorField].DataType == typeof(Single?))
                                                        {
                                                            decimal d = 0;
                                                            decimal.TryParse(rowData[colorField].ToString(), out d);
                                                            flag = d == decimal.Parse(ReducedValue);
                                                        }
                                                        else
                                                        {
                                                            flag = rowData[colorField].ToString() == ReducedValue;
                                                        }

                                                        break;
                                                    }
                                                case "L"://左匹配
                                                    {
                                                        flag = rowData[colorField].ToString().StartsWith(ReducedValue);
                                                        break;
                                                    }
                                                case "R"://右匹配
                                                    {
                                                        flag = rowData[colorField].ToString().EndsWith(ReducedValue);
                                                        break;
                                                    }
                                                case "!"://不等于
                                                    {
                                                        if (dtData.Columns[colorField].DataType == typeof(decimal) || dtData.Columns[colorField].DataType == typeof(decimal?) || dtData.Columns[colorField].DataType == typeof(double?) || dtData.Columns[colorField].DataType == typeof(Single?))
                                                        {
                                                            decimal d = 0;
                                                            decimal.TryParse(rowData[colorField].ToString(), out d);
                                                            flag = d != decimal.Parse(ReducedValue);
                                                        }
                                                        else
                                                        {
                                                            flag = rowData[colorField].ToString() != ReducedValue;
                                                        }
                                                        break;
                                                    }
                                                case "I"://包含
                                                    {
                                                        flag = rowData[colorField].ToString().Contains(ReducedValue) == true;
                                                        break;
                                                    }
                                                case ">"://大于
                                                    {
                                                        decimal d = 0;
                                                        decimal.TryParse(rowData[colorField].ToString(), out d);
                                                        flag = d > decimal.Parse(ReducedValue);
                                                        break;
                                                    }
                                                case "<"://小于
                                                    {
                                                        decimal d = 0;
                                                        decimal.TryParse(rowData[colorField].ToString(), out d);
                                                        flag = d < decimal.Parse(ReducedValue);
                                                        break;
                                                    }
                                                case "S"://SQL条件
                                                    {

                                                        foreach (DataColumn dc in dtData.Columns)
                                                        {
                                                            if (dc.DataType == typeof(decimal) || dc.DataType == typeof(Int32?) || dc.DataType == typeof(Int32) || dc.DataType == typeof(decimal?) || dc.DataType == typeof(double?) || dc.DataType == typeof(Single?))
                                                            {
                                                                decimal d = 0;
                                                                decimal.TryParse(rowData[dc.ColumnName].ToString(), out d);

                                                                ReducedValue = ReducedValue.Replace("[" + dc.ColumnName + "]", d.ToString());
                                                            }
                                                            else
                                                            {
                                                                ReducedValue = ReducedValue.Replace("[" + dc.ColumnName + "]", rowData[dc.ColumnName].ToString());
                                                            }
                                                        }
                                                        flag = dtTmp.Select(ReducedValue).Length > 0;
                                                        break;
                                                    }
                                                case "#":
                                                    {
                                                        flag = rowData[colorField].ToString() != "";
                                                        break;
                                                    }
                                                case "E":
                                                    {
                                                        flag = rowData[colorField].ToString() == "";
                                                        break;
                                                    }


                                            }

                                        }
                                        else
                                        {
                                            if (w == "#")
                                            {
                                                flag = rowData[colorField].ToString() != "";

                                            }
                                            else if (w == "E")
                                            {
                                                flag = true;

                                            }
                                            
                                        }
                                      

                                        if (flag)
                                        {
                                            if (rowColor["ColorType"].ToString() == "BColors")
                                            {
                                                if (bColors.ContainsKey(colorField))
                                                {
                                                    continue;
                                                }
                                                bColors.Add(colorField, rowColor["Color"].ToString());
                                            }
                                            else
                                            {
                                                if (fColors.ContainsKey(colorField))
                                                {
                                                    continue;
                                                }
                                                fColors.Add(colorField, rowColor["Color"].ToString());
                                            }
                                            foreach (string f in showFields)
                                            {
                                                if (rowColor["ColorType"].ToString() == "BColors")
                                                {
                                                    if (bColors.ContainsKey(f))
                                                    {
                                                        continue;
                                                    }
                                                    bColors.Add(f, rowColor["Color"].ToString());
                                                }
                                                else
                                                {
                                                    if (fColors.ContainsKey(f))
                                                    {
                                                        continue;
                                                    }
                                                    fColors.Add(f, rowColor["Color"].ToString());
                                                }
                                            }
                                        }
                                
                                     
                                    }
                                }

                            }

                        }




                        foreach (var ele in this.elementTableOuputs.Where(m => m.isEdit == false && m.prop2!=null&&m.prop2 .Contains("dy2")))
                        {
                            if (bColors.ContainsKey(ele.prop))
                            {
                                continue;
                            }
                            bColors.Add(ele.prop, "#e9e1e1");
                        }
                        rowData["BColors"] = bColors;
                        rowData["FColors"] = fColors;
                    }

                }
                if(isSetColor==false)
                {
                    if (dtData.Columns.Contains("BColors") == false)
                    {
                        dtData.Columns.Add("BColors", typeof(Dictionary<string, string>));
                    }
                    if (dtData.Columns.Contains("FColors") == false)
                    {
                        dtData.Columns.Add("FColors", typeof(Dictionary<string, string>));
                    }

                    foreach (var ele in this.elementTableOuputs.Where(m => m.isEdit == false&& m.prop2 !=null&& m.prop2.Contains("dy2")))
                    {
                       

                        foreach (DataRow rowData in dtData.Rows)
                        {
                            Dictionary<string, string> fColors = new Dictionary<string, string>();//字体颜色
                            Dictionary<string, string> bColors = new Dictionary<string, string>();//背景颜色
                            bColors.Add(ele.prop, "#e9e1e1");
                            rowData["BColors"] = bColors;
                            rowData["FColors"] = fColors;
                        }
                    }

                }
        
            }
            catch(Exception ex)
            {

            }
        }
